; One record of INTERNAL_COMMAND_TABLE: the name measures itself, and the
; handler is written as the label the transient runs it at, which is where
; every other reference to it names it too.

COMMAND MACRO name, handler
        LOCAL s, e
        db      e - s
s:
        db      name
e:
        dw      handler - TRANSIENT_BIAS
        ENDM

; The sign-on logo script.  One macro per record and per op kind, so
; SIGNON_LOGO_SCRIPT reads as the screen it paints rather than as bytes.
; LOGO_RUN and LOGO_CELLS count their own payload: the count byte
; RUN_SCREEN_SCRIPT reads back is how many arguments follow it, and cannot
; drift from them.

LOGO_SIZE MACRO n
        dw      n
        ENDM

LOGO_POS MACRO row, col, n
        db      row, col
        dw      n
        ENDM

LOGO_RUN MACRO attr, chars:VARARG
        LOCAL s, e
        db      000h, e - s, attr
s:
        db      chars
e:
        ENDM

LOGO_CELLS MACRO cells:VARARG
        LOCAL s, e
        db      001h, (e - s) / 2
s:
        db      cells
e:
        ENDM

LOGO_REPEAT MACRO n, char, attr
        db      0FFh, n, char, attr
        ENDM


COMMAND_ENTRY:
        ; .COM entry — jmp over the banner and the fixup table
        jmp     short COMMAND_INIT                             ;#0100: EB 4B
        nop                                                    ;#0102: 90

BANNER:
        ; Sign-on string, '$'-terminated for INT 21h AH=09h
        ; No operand in either frame loads 0103h, and COMMAND_ENTRY jumps straight over
        ; it, so the sign-on text is never printed by this program.  It is not unused
        ; though: 016Fh loads BANNER+0Dh and copies eleven bytes to VERSION_COPY, which
        ; is where the version digits CMD_VER prints come from.  So the banner is read
        ; as data even though it is never read as a message -- and only its middle
        ; eleven bytes are read at all.
        ; Format: FORMAT_STRING
        db      0Dh, "COMMAND  -  V3.30  R05  -  03.Dez.90", 0Dh, 0Ah, 0Dh, 0Ah, "$" ;#0103: 0D 43 4F 4D 4D 41 4E 44 20 20 2D 20 20 56 33 2E 33 30 20 20 52 30 35 20 20 2D 20 20 30 33 2E 44 65 7A 2E 39 30 0D 0A 0D 0A 24

BANNER_TAIL:
        ; Four bytes after the banner: 08 20 08 1A
        ; Format: FORMAT_HEX
        ; raw
        db      8, 20h, 8, 1Ah                                 ;#012D

SEGMENT_FIXUP_TABLE:
        ; Words naming the segment halves COMMAND_INIT patches
        dw      VEC_PROMPT_SEG                                 ;#0131: 93 02
        dw      VEC_PROMPT_FLAG80_SEG                          ;#0133: 97 02
        dw      VEC_DRIVE_REMOVABLE_SEG                        ;#0135: 9B 02
        dw      VEC_OPEN_DEVICE_SEG                            ;#0137: 9F 02
        dw      VEC_EXEC_CHILD_SEG                             ;#0139: A3 02
        dw      INT_22_VECTOR_SEG                              ;#013B: 66 02
        dw      INT_23_VECTOR_SEG                              ;#013D: 6A 02
        dw      INT_24_VECTOR_SEG                              ;#013F: 6E 02
        dw      UNUSED_SEG_SLOT                                ;#0141: 70 02
        dw      EXEC_TAIL_PTR_SEG                              ;#0143: A9 02
        dw      EXEC_FCB1_PTR_SEG                              ;#0145: AD 02
        dw      EXEC_FCB2_PTR_SEG                              ;#0147: B1 02
        dw      VEC_BATCH_ABORT_SEG                            ;#0149: 83 02
        dw      0                                              ;#014B: 00 00

COMMAND_INIT:
        ; Set SP, run the fixups, stage the version bytes, jump to the body
        cli                                                    ;#014D: FA
        mov     sp, 200h                                       ;#014E: BC 00 02
        cld                                                    ;#0151: FC
FIXUP_LOOP:
        ; lodsw a target, `mov [bx], cs`, until the 0 terminator
        mov     si, SEGMENT_FIXUP_TABLE                        ;#0152: BE 31 01
        lodsw                                                  ;#0155: AD
        or      ax, ax                                         ;#0156: 0B C0
        jz      short FIXUP_DONE                               ;#0158: 74 06
        mov     bx, ax                                         ;#015A: 8B D8
        mov     [bx], cs                                       ;#015C: 8C 0F
        jmp     short 155h                                     ;#015E: EB F5

FIXUP_DONE:
        ; Work out TRANSIENT_SEG: top of memory less 4F7h paragraphs
        mov     ax, [PSP_TOP_OF_MEM]                           ;#0160: A1 02 00
        mov     bx, TRANSIENT_SIZE                             ;#0163: BB 70 4F
        mov     cl, 4                                          ;#0166: B1 04
        shr     bx, cl                                         ;#0168: D3 EB
        sub     ax, bx                                         ;#016A: 2B C3
        mov     [TRANSIENT_SEG], ax                            ;#016C: A3 52 02
        mov     si, BANNER+0Dh                                 ;#016F: BE 10 01
        mov     di, VERSION_COPY                               ;#0172: BF 56 0B
        mov     cx, 0Bh                                        ;#0175: B9 0B 00
        rep     movsb                                          ;#0178: F3 A4
        cmp     byte [VERSION_R_FLAG], "R"                     ;#017A: 80 3E 5D 0B 52
        jnz     short 186h                                     ;#017F: 75 05
        mov     byte [MSG_COMMAND_VERSION+18h], "$"            ;#0181: C6 06 60 0B 24
        sti                                                    ;#0186: FB
        jmp     near COMMAND_MAIN                              ;#0187: E9 C0 15

HEAD_DATA:
        ; Six zero bytes before the signature
