SYSMSG_ERRO_DE:
        ; ". Erro de" — a template; INT_24_REPORT resets three slots in it
        ; A message template rather than a fixed string.  The 00h bytes at 0987h,
        ; 0990h and 0991h and the 0CEh pair at 0993h/0994h are slots the code writes
        ; into before printing:
        ;
        ; 1008    mov     byte [SYSMSG_ERRO_DE+ERRO_SUBJECT], 0FFh   ; cut it short
        ; 10B0    mov     byte [SYSMSG_ERRO_DE+ERRO_SUBJECT], 0DFh   ; ...or entry #47
        ; 10CD    mov     byte [SYSMSG_ERRO_DE+ERRO_AREA], 0E0h      ; entry #48
        ; 1125    mov     byte [SYSMSG_ERRO_DE+ERRO_DAMAGE], 0E5h    ; entry #53
        ;
        ; Those are reference bytes in the #954 scheme -- index = byte - 0B0h -- so
        ; the composition is not only static: the code chooses at run time which
        ; fragments the message is made of, and 0FFh cuts it short.
        ; Format: FORMAT_COMPRESSED
        db      MSGREF_CRLF                                    ;#0985: D5
        db      MSGREF_PREFIX                                  ;#0986: DD
        db      0, ".", 7                                      ;#0987: 00 2E 07
        db      MSGREF_CRLF                                    ;#098A: D5
        db      MSGREF_TWO_SPACES                              ;#098B: DE
        db      MSGREF_ERRO                                    ;#098C: D8
        db      "de ", 0, 0                                    ;#098D: 64 65 20 00 00
        db      MSGREF_CRLF                                    ;#0992: D5
        db      MSGREF_EMPTY                                   ;#0993: CE
        db      MSGREF_EMPTY                                   ;#0994: CE
        db      0FFh                                           ;#0995: FF

