        lds     dx, [si]                                       ;#0B68: C5 14
        mov     ax, 2522h                                      ;#0B6A: B8 22 25
        int     21h                                            ;#0B6D: CD 21
        lds     dx, [si+4]                                     ;#0B6F: C5 54 04
        inc     al                                             ;#0B72: FE C0
        int     21h                                            ;#0B74: CD 21
        lds     dx, [si+8]                                     ;#0B76: C5 54 08
        inc     al                                             ;#0B79: FE C0
        int     21h                                            ;#0B7B: CD 21
        pop     si                                             ;#0B7D: 5E
        pop     dx                                             ;#0B7E: 5A
        pop     ax                                             ;#0B7F: 58
        ret                                                    ;#0B80: C3

GET_SWITCH_CHAR:
        ; INT 21h AX=3700h; AL the switch char, AH the separator that pairs with it
        push    dx                                             ;#0B81: 52
        mov     ax, 3700h                                      ;#0B82: B8 00 37
        int     21h                                            ;#0B85: CD 21
        mov     ax, dx                                         ;#0B87: 8B C2
        pop     dx                                             ;#0B89: 5A
        mov     ah, 2Fh                                        ;#0B8A: B4 2F
        cmp     al, ah                                         ;#0B8C: 3A C4
        jnz     short SWITCHCHAR_RETURN                        ;#0B8E: 75 02
        mov     ah, 5Ch                                        ;#0B90: B4 5C
SWITCHCHAR_RETURN:
        ; AH is 5Ch when 2Fh gave nothing back
        ret                                                    ;#0B92: C3

CHECKSUM_TRANSIENT:
        ; Word-sum COMMAND_ENTRY..4660h and compare — the mutable half is left out
        ; Whether the transient is still the transient.  A child program gets the memory
        ; above the stub, so anything the shell left there may be gone by the time it
        ; returns, and this is how it finds out:
        ;
        ; 0B9A    mov     si, COMMAND_ENTRY
        ; mov     cx, 4660h
        ; sub     cx, si
        ; shr     cx, 1
        ; push    bx
        ; xor     bx, bx
        ; 0BA7    lodsw
        ; add     bx, ax
        ; loop    CHECKSUM_ADD_WORD
        ;
        ; A word sum, no carry kept, from the transient's entry up to LOW_COPY_SEG.  That
        ; end is not a round number picked for safety: LOW_COPY_SEG is the first of the
        ; transient's own variables, so the sum covers exactly the half that should never
        ; change and stops where the half that changes constantly begins.  The same
        ; boundary #1046 confirmed from the other side.
        ;
        ; The expected value is not a constant in the image.  RELOCATE_TRANSIENT runs the
        ; sum over the copy it has just put in place and stores the answer at 17A4h, so
        ; what is compared against is what was actually loaded, once, rather than what
        ; the file was supposed to contain.
        ;
        ; Three callers, and the same code answers a different question at each.  17A1h
        ; is the recording pass.  RELOAD_TRANSIENT_IF_BAD asks before using it, and a
        ; mismatch there says nothing at all -- it calls OPEN_COMMAND_COM and reloads,
        ; because a child having overwritten the memory is expected rather than
        ; exceptional.
        ; 11C4h asks again once that reload has finished, and a mismatch *there* is
        ; "COMMAND.COM inválido ou inconsistente", since the copy just read off the disk
        ; is the one that failed.
        push    ds                                             ;#0B93: 1E
        mov     ds, [TRANSIENT_SEG]                            ;#0B94: 8E 1E 52 02
        push    si                                             ;#0B98: 56
        push    cx                                             ;#0B99: 51
        mov     si, COMMAND_ENTRY                              ;#0B9A: BE 00 01
        mov     cx, 4660h                                      ;#0B9D: B9 60 46
        sub     cx, si                                         ;#0BA0: 2B CE
        shr     cx, 1                                          ;#0BA2: D1 E9
        push    bx                                             ;#0BA4: 53
        xor     bx, bx                                         ;#0BA5: 33 DB
CHECKSUM_ADD_WORD:
        ; Plain 16-bit sum over the whole image
        lodsw                                                  ;#0BA7: AD
        add     bx, ax                                         ;#0BA8: 03 D8
        loop    CHECKSUM_ADD_WORD                              ;#0BAA: E2 FB
        mov     ax, bx                                         ;#0BAC: 8B C3
        pop     bx                                             ;#0BAE: 5B
        pop     cx                                             ;#0BAF: 59
        pop     si                                             ;#0BB0: 5E
        pop     ds                                             ;#0BB1: 1F
        cmp     ax, [TRANSIENT_CHECKSUM]                       ;#0BB2: 3B 06 54 02
        ret                                                    ;#0BB6: C3

ASK_AND_READ_KEY:
        ; Print the message, then READ_KEY_ECHOED with the caller's JFT put aside
        call    near PRINT_MSG_SAFELY                          ;#0BB7: E8 8A 02
        call    near SAVE_CALLER_JFT                           ;#0BBA: E8 75 01
        call    near READ_KEY_ECHOED                           ;#0BBD: E8 06 00
        call    near RESTORE_CALLER_JFT                        ;#0BC0: E8 98 01
        jmp     near PRINT_BLANK_LINE                          ;#0BC3: E9 7B 02

READ_KEY_ECHOED:
        ; AX=0C07h for the key; echo it with AH=2 only when it is printable
        push    dx                                             ;#0BC6: 52
        mov     ax, 0C07h                                      ;#0BC7: B8 07 0C
        int     21h                                            ;#0BCA: CD 21
        push    ax                                             ;#0BCC: 50
        mov     dl, al                                         ;#0BCD: 8A D0
        sub     al, 20h                                        ;#0BCF: 2C 20
        cmp     al, 5Fh                                        ;#0BD1: 3C 5F
        jnb     short READKEY_FLUSH                            ;#0BD3: 73 04
        mov     ah, 2                                          ;#0BD5: B4 02
        int     21h                                            ;#0BD7: CD 21
READKEY_FLUSH:
        ; Control characters are read but not echoed
        mov     ax, 0C00h                                      ;#0BD9: B8 00 0C
        int     21h                                            ;#0BDC: CD 21
        pop     ax                                             ;#0BDE: 58
        call    near UPCASE_AL_RESIDENT                        ;#0BDF: E8 02 00
        pop     dx                                             ;#0BE2: 5A
        ret                                                    ;#0BE3: C3

UPCASE_AL_RESIDENT:
        ; Byte-identical to UPCASE_AL at 2F00h — one copy per half
        cmp     al, "a"                                        ;#0BE4: 3C 61
        jb      short UPCASE_RES_RETURN                        ;#0BE6: 72 06
        cmp     al, "z"                                        ;#0BE8: 3C 7A
        jnbe    short UPCASE_RES_RETURN                        ;#0BEA: 77 02
        sub     al, 20h                                        ;#0BEC: 2C 20
UPCASE_RES_RETURN:
        ; Unchanged unless it was a lower-case letter
        ret                                                    ;#0BEE: C3

RESTORE_ONE_HANDLE:
        ; Take the saved handle from [SI], close the live one, put it back in the JFT
        mov     cl, 0FFh                                       ;#0BEF: B1 FF
        xchg    [si], cl                                       ;#0BF1: 86 0C
        cmp     cl, 0FFh                                       ;#0BF3: 80 F9 FF
        jz      short RESTOREH_RETURN                          ;#0BF6: 74 07
        mov     ah, 3Eh                                        ;#0BF8: B4 3E
        int     21h                                            ;#0BFA: CD 21
        mov     [bx+PSP_JFT_STDIN], cl                         ;#0BFC: 88 4F 18
RESTOREH_RETURN:
        ; Nothing to restore, or the handle is back
        ret                                                    ;#0BFF: C3

SWAP_INT23_VECTOR:
        ; xchg VEC_BATCH_ABORT with 0000:008Ch — the INT 23h Ctrl-Break vector
        cli                                                    ;#0C00: FA
        xor     ax, ax                                         ;#0C01: 33 C0
        mov     ds, ax                                         ;#0C03: 8E D8
        mov     bx, 8Ch                                        ;#0C05: BB 8C 00
        mov     ax, [bx]                                       ;#0C08: 8B 07
        xchg    [cs:VEC_BATCH_ABORT], ax                       ;#0C0A: 2E 87 06 81 02
        mov     [bx], ax                                       ;#0C0F: 89 07
        mov     ax, [bx+2]                                     ;#0C11: 8B 47 02
        xchg    [cs:VEC_BATCH_ABORT+2h], ax                    ;#0C14: 2E 87 06 83 02
        mov     [bx+2], ax                                     ;#0C19: 89 47 02
        sti                                                    ;#0C1C: FB
        ret                                                    ;#0C1D: C3

SISNE_18_BRASCII_FN4:
        ; INT 21h AX=180Dh — SISNE AH=18h subfn 0Dh, the BRASCII driver AH=4 call
        ; AH=18h is marked reserved by MS-DOS; SISNE uses it as a private extension
        ; with 25 subfunctions, dispatched through DRIVE_INFO_SUBFN_TABLE at 4892h in
        ; SISNE.SIS.  COMMAND.COM reaching for 180Dh and 180Fh is the two programs
        ; talking over that private interface.
        mov     dx, 101h                                       ;#0C1E: BA 01 01
SET_BRASCII_FROM_DX:
        ; DH picks 180Dh or 180Eh; SISNE_18_BRASCII_FN4 is this with DX=101h
        push    ax                                             ;#0C21: 50
        not     dx                                             ;#0C22: F7 D2
        and     dx, 101h                                       ;#0C24: 81 E2 01 01
        mov     ax, 180Dh                                      ;#0C28: B8 0D 18
        add     al, dh                                         ;#0C2B: 02 C6
        int     21h                                            ;#0C2D: CD 21
        pop     ax                                             ;#0C2F: 58
        ret                                                    ;#0C30: C3

SISNE_18_BRASCII_FN3:
        ; INT 21h AX=180Fh — subfn 0Fh; the driver answer comes back in DH
        push    ax                                             ;#0C31: 50
        mov     ax, 180Fh                                      ;#0C32: B8 0F 18
        int     21h                                            ;#0C35: CD 21
        mov     dh, al                                         ;#0C37: 8A F0
        pop     ax                                             ;#0C39: 58
        ret                                                    ;#0C3A: C3

IS_DRIVE_REMOVABLE:
        ; IOCTL AX=4408h with the drive in BL; carry reports the answer
        push    ax                                             ;#0C3B: 50
        push    bx                                             ;#0C3C: 53
        mov     bl, al                                         ;#0C3D: 8A D8
        mov     ax, 4408h                                      ;#0C3F: B8 08 44
        int     21h                                            ;#0C42: CD 21
        cmc                                                    ;#0C44: F5
        jnb     short REMOVABLE_RETURN                         ;#0C45: 73 05
        or      al, al                                         ;#0C47: 0A C0
        jnz     short REMOVABLE_RETURN                         ;#0C49: 75 01
        stc                                                    ;#0C4B: F9
REMOVABLE_RETURN:
        ; Carry means it can be swapped out
        pop     bx                                             ;#0C4C: 5B
        pop     ax                                             ;#0C4D: 58
        ret                                                    ;#0C4E: C3

OPEN_AND_TEST_DEVICE:
        ; AX=3D02h to open, then AX=4400h and test DL bit 7 for a device
        mov     ax, 3D02h                                      ;#0C4F: B8 02 3D
        int     21h                                            ;#0C52: CD 21
        jb      short DEVICE_RETURN                            ;#0C54: 72 4C
        mov     bx, ax                                         ;#0C56: 8B D8
        mov     ax, 4400h                                      ;#0C58: B8 00 44
        int     21h                                            ;#0C5B: CD 21
        test    dl, 80h                                        ;#0C5D: F6 C2 80
        stc                                                    ;#0C60: F9
        jz      short DEVICE_CLOSE_HANDLE                      ;#0C61: 74 39
        mov     dh, 0                                          ;#0C63: B6 00
        or      dl, 3                                          ;#0C65: 80 CA 03
        mov     ax, 4401h                                      ;#0C68: B8 01 44
        int     21h                                            ;#0C6B: CD 21
        ; Redirection, and the reason PSP_JFT_STDIN/STDOUT are reached with `xchg`:
        ;
        ; 0C71    mov     al, [REDIR_SAVED_STDIN]
        ; cmp     al, 0FFh                ; 0FFh = not redirected
        ; jz      short DEVICE_DUP_TO_STDIN
        ; xchg    [PSP_JFT_STDIN], al     ; install, and take the old one
        ; mov     [REDIR_SAVED_STDIN], al ; ...park it here for the swap back
        ; mov     ah, 46h
        ; int     21h
        ;
        ; One instruction installs the new handle and saves the displaced one, so the
        ; same three lines undo the redirection next time round -- there is no separate
        ; restore path.  AH=46h then forces the duplicate onto the handle in CX.
        ; STDOUT gets the identical treatment four lines further down, and identical is
        ; literal: the only difference is the `inc cx` at 0C83h between the two blocks,
        ; `xor cx, cx` at 0C6Fh having set up handle 0 for the first.
        ;
        ; The passage is entered by falling out of the IOCTL above it, not called, which
        ; is why no operand anywhere names 0C6Dh.
        push    cs                                             ;#0C6D: 0E
        pop     ds                                             ;#0C6E: 1F
        xor     cx, cx                                         ;#0C6F: 33 C9
        mov     al, [REDIR_SAVED_STDIN]                        ;#0C71: A0 3B 03
        cmp     al, 0FFh                                       ;#0C74: 3C FF
        jz      short DEVICE_DUP_TO_STDIN                      ;#0C76: 74 07
        xchg    [PSP_JFT_STDIN], al                            ;#0C78: 86 06 18 00
        mov     [REDIR_SAVED_STDIN], al                        ;#0C7C: A2 3B 03
DEVICE_DUP_TO_STDIN:
        ; AH=46h puts the device on handle 0
        mov     ah, 46h                                        ;#0C7F: B4 46
        int     21h                                            ;#0C81: CD 21
        inc     cx                                             ;#0C83: 41
        mov     al, [REDIR_SAVED_STDOUT]                       ;#0C84: A0 3C 03
        cmp     al, 0FFh                                       ;#0C87: 3C FF
        jz      short DEVICE_DUP_TO_STDOUT                     ;#0C89: 74 07
        xchg    [PSP_JFT_STDOUT], al                           ;#0C8B: 86 06 19 00
        mov     [REDIR_SAVED_STDOUT], al                       ;#0C8F: A2 3C 03
DEVICE_DUP_TO_STDOUT:
        ; And on 1, and on 2 after it
        mov     ah, 46h                                        ;#0C92: B4 46
        int     21h                                            ;#0C94: CD 21
        inc     cx                                             ;#0C96: 41
        mov     ah, 46h                                        ;#0C97: B4 46
        int     21h                                            ;#0C99: CD 21
        clc                                                    ;#0C9B: F8
DEVICE_CLOSE_HANDLE:
        ; Close the original, keeping the flags
        pushf                                                  ;#0C9C: 9C
        mov     ah, 3Eh                                        ;#0C9D: B4 3E
        int     21h                                            ;#0C9F: CD 21
        popf                                                   ;#0CA1: 9D
DEVICE_RETURN:
        ; Carry says it was not a character device
        ret                                                    ;#0CA2: C3

PATCH_INSERT_MSG:
        ; Put the drive letter into the "Coloque o COMMAND.COM" message
        mov     byte [SYSMSG_COLOQUE_O_COMMAND_COM_NA_UNIDA+COLOQUE_DRIVE], 0CBh ;#0CA3: C6 06 27 0A CB
        mov     byte [SYSMSG_COLOQUE_O_COMMAND_COM_NA_UNIDA+COLOQUE_COLON], 0CEh ;#0CA8: C6 06 28 0A CE
        xor     al, al                                         ;#0CAD: 32 C0
        cmp     byte [HEAD_DATA_TAIL+6Ah], ":"                 ;#0CAF: 80 3E 01 02 3A
        jnz     short PATCHMSG_RETURN                          ;#0CB4: 75 0F
        mov     al, [HEAD_DATA_TAIL+69h]                       ;#0CB6: A0 00 02
        and     al, 0DFh                                       ;#0CB9: 24 DF
        mov     [SYSMSG_COLOQUE_O_COMMAND_COM_NA_UNIDA+COLOQUE_DRIVE], al ;#0CBB: A2 27 0A
        mov     byte [SYSMSG_COLOQUE_O_COMMAND_COM_NA_UNIDA+COLOQUE_COLON], ":" ;#0CBE: C6 06 28 0A 3A
        sub     al, 40h                                        ;#0CC3: 2C 40
PATCHMSG_RETURN:
        ; AL is the drive number the message now names
        ret                                                    ;#0CC5: C3

RESTORE_REDIRECTION:
        ; Both handles back through RESTORE_ONE_HANDLE, and repoint 0285h
        ; Tidying up must not ask questions, so the first thing that changes is who
        ; handles a critical error:
        ;
        ; 0CC6    mov     word [cs:VEC_INT24_ACTION], INT_24_IGNORE
        ; ...
        ; 0D1C    mov     word [cs:VEC_INT24_ACTION], INT_24_REPORT
        ;
        ; Everything between runs with failures swallowed.  Deleting a temporary file on
        ; a disk somebody swapped would otherwise put an "Abort, Retry, Ignore" prompt in
        ; front of a user who has already got their prompt back.
        ;
        ; Then the two saved handles go back, and every other one is closed whether or
        ; not COMMAND.COM opened it:
        ;
        ; 0CDC    mov     bx, 5
        ; mov     cx, 0Fh
        ; 0CE2    cmp     byte [bx+PSP_JFT_STDIN], 0FFh
        ; jz      short RESTORE_NEXT_HANDLE
        ; mov     ah, 3Eh
        ; int     21h
        ; inc     bx
        ; loop    RESTORE_CLOSE_HANDLE
        ;
        ; Slots 5 to 19 of the JFT, which is everything above the five DOS gives every
        ; process.  A child that exited without closing its files has them closed here --
        ; the shell reclaims the table rather than trusting what ran in it.
        ;
        ; The pipe temporaries are deleted last, and the two name pointers are written
        ; back rather than rotated back:
        ;
        ; 0CFD    mov     word [PIPE_NAME_PTRS], PIPE_TEMP_NAME_2
        ; mov     word [PIPE_NAME_PTRS+2], PIPE_TEMP_NAME_1
        ;
        ; #1132 has TAKE_NEXT_CHAINED_COMMAND swapping that pair once per stage, so after
        ; an odd number of stages they are the wrong way round.  Nothing counts the
        ; stages; both slots are simply assigned, which costs the same and cannot be off
        ; by one.
        mov     word [cs:VEC_INT24_ACTION], INT_24_IGNORE      ;#0CC6: 2E C7 06 85 02 EA 0F
        xor     bx, bx                                         ;#0CCD: 33 DB
        mov     si, REDIR_SAVED_STDIN                          ;#0CCF: BE 3B 03
        call    near RESTORE_ONE_HANDLE                        ;#0CD2: E8 1A FF
        inc     bx                                             ;#0CD5: 43
        mov     si, REDIR_SAVED_STDOUT                         ;#0CD6: BE 3C 03
        call    near RESTORE_ONE_HANDLE                        ;#0CD9: E8 13 FF
        mov     bx, 5                                          ;#0CDC: BB 05 00
        mov     cx, 0Fh                                        ;#0CDF: B9 0F 00
RESTORE_CLOSE_HANDLE:
        ; Anything the child left open above 4
        cmp     byte [bx+PSP_JFT_STDIN], 0FFh                  ;#0CE2: 80 7F 18 FF
        jz      short RESTORE_NEXT_HANDLE                      ;#0CE6: 74 04
        mov     ah, 3Eh                                        ;#0CE8: B4 3E
        int     21h                                            ;#0CEA: CD 21
RESTORE_NEXT_HANDLE:
        ; Fifteen slots, 5 through 13h
        inc     bx                                             ;#0CEC: 43
        loop    RESTORE_CLOSE_HANDLE                           ;#0CED: E2 F3
        test    byte [SHELL_FLAGS], SHELL_PIPE_ACTIVE          ;#0CEF: F6 06 39 03 02
        jnz     short RESTORE_INT24_AND_VERIFY                 ;#0CF4: 75 26
        test    byte [REDIR_FLAGS], REDIR_TEMPS_EXIST          ;#0CF6: F6 06 3A 03 80
        jz      short RESTORE_INT24_AND_VERIFY                 ;#0CFB: 74 1F
        mov     word [PIPE_NAME_PTRS], PIPE_TEMP_NAME_2        ;#0CFD: C7 06 C8 04 DC 04
        mov     word [PIPE_NAME_PTRS+2], PIPE_TEMP_NAME_1      ;#0D03: C7 06 CA 04 CC 04
        mov     byte [REDIR_FLAGS], 0                          ;#0D09: C6 06 3A 03 00
        mov     dx, PIPE_TEMP_NAME_1                           ;#0D0E: BA CC 04
        mov     ah, 41h                                        ;#0D11: B4 41
        int     21h                                            ;#0D13: CD 21
        mov     dx, PIPE_TEMP_NAME_2                           ;#0D15: BA DC 04
        mov     ah, 41h                                        ;#0D18: B4 41
        int     21h                                            ;#0D1A: CD 21
RESTORE_INT24_AND_VERIFY:
        ; Our own INT 24h back, and VERIFY if changed
        mov     word [cs:VEC_INT24_ACTION], INT_24_REPORT      ;#0D1C: 2E C7 06 85 02 ED 0F
        mov     al, 0FFh                                       ;#0D23: B0 FF
        xchg    [SAVED_VERIFY_FLAG], al                        ;#0D25: 86 06 7A 02
        cmp     al, 0FFh                                       ;#0D29: 3C FF
        jz      short RESTORE_RETURN                           ;#0D2B: 74 04
        mov     ah, 2Eh                                        ;#0D2D: B4 2E
        int     21h                                            ;#0D2F: CD 21
RESTORE_RETURN:
        ; Everything the child could touch is back
        ret                                                    ;#0D31: C3

SAVE_CALLER_JFT:
        ; AH=51h then park the caller PSP_JFT_PTR in SAVED_JFT_PTR_*
        push    ax                                             ;#0D32: 50
        push    bx                                             ;#0D33: 53
        call    near SWAP_INT23_VECTOR                         ;#0D34: E8 C9 FE
        mov     ah, 51h                                        ;#0D37: B4 51
        int     21h                                            ;#0D39: CD 21
        mov     ds, bx                                         ;#0D3B: 8E DB
        lds     bx, [PSP_JFT_PTR]                              ;#0D3D: C5 1E 34 00
        mov     [cs:SAVED_JFT_PTR_OFF], bx                     ;#0D41: 2E 89 1E 7D 02
        mov     [cs:SAVED_JFT_PTR_SEG], ds                     ;#0D46: 2E 8C 1E 7F 02
        mov     ax, [bx]                                       ;#0D4B: 8B 07
        mov     [cs:SAVED_JFT_ENTRY], ax                       ;#0D4D: 2E A3 7B 02
        mov     al, [cs:PSP_JFT_STDERR]                        ;#0D51: 2E A0 1A 00
        mov     ah, al                                         ;#0D55: 8A E0
        mov     [bx], ax                                       ;#0D57: 89 07
        jmp     short RESTOREJFT_RETURN                        ;#0D59: EB 10

RESTORE_CALLER_JFT:
        ; Write SAVED_JFT_ENTRY back through that pointer
        push    ax                                             ;#0D5B: 50
        push    bx                                             ;#0D5C: 53
        mov     ax, [cs:SAVED_JFT_ENTRY]                       ;#0D5D: 2E A1 7B 02
        lds     bx, [cs:SAVED_JFT_PTR_OFF]                     ;#0D61: 2E C5 1E 7D 02
        mov     [bx], ax                                       ;#0D66: 89 07
        call    near SWAP_INT23_VECTOR                         ;#0D68: E8 95 FE
RESTOREJFT_RETURN:
        ; Entry and INT 23h both back as they were
        pop     bx                                             ;#0D6B: 5B
        pop     ax                                             ;#0D6C: 58
        push    cs                                             ;#0D6D: 0E
        pop     ds                                             ;#0D6E: 1F
        ret                                                    ;#0D6F: C3

HAVE_TRANSIENT_BLOCK:
        ; Carry clear when TRANSIENT_BLOCK_SEG still holds a block
        cmp     word [TRANSIENT_BLOCK_SEG], 0                  ;#0D70: 83 3E 72 02 00
        jz      short TRANSIENT_ALLOC_BLOCK                    ;#0D75: 74 04
        clc                                                    ;#0D77: F8
        ret                                                    ;#0D78: C3

TRANSIENT_ALLOC_FAILED:
        ; Carry, with DX naming which failure it was
        stc                                                    ;#0D79: F9
        ret                                                    ;#0D7A: C3

TRANSIENT_ALLOC_BLOCK:
        ; Ask for the largest block, keep what is needed
        mov     dx, TRANSIENT_SIZE                             ;#0D7B: BA 70 4F
        mov     cl, 4                                          ;#0D7E: B1 04
        shr     dx, cl                                         ;#0D80: D3 EA
        mov     cx, dx                                         ;#0D82: 8B CA
        mov     bx, 0FFFFh                                     ;#0D84: BB FF FF
        mov     ah, 48h                                        ;#0D87: B4 48
        int     21h                                            ;#0D89: CD 21
        cmp     bx, cx                                         ;#0D8B: 3B D9
        mov     dx, SYSMSG_MEMORIA_INSUFICIENTE_COMMAND        ;#0D8D: BA B0 09
        jbe     short TRANSIENT_ALLOC_FAILED                   ;#0D90: 76 E7
        mov     ah, 48h                                        ;#0D92: B4 48
        int     21h                                            ;#0D94: CD 21
        mov     dx, SYSMSG_ERRO_NA_ALOCACAO_DE_MEMORIA         ;#0D96: BA BF 09
        jb      short TRANSIENT_ALLOC_FAILED                   ;#0D99: 72 DE
        mov     [TRANSIENT_BLOCK_SEG], ax                      ;#0D9B: A3 72 02
        sub     bx, cx                                         ;#0D9E: 2B D9
        mov     [TRANSIENT_BLOCK_PARAS], bx                    ;#0DA0: 89 1E 74 02
        add     ax, bx                                         ;#0DA4: 03 C3
        mov     [TRANSIENT_SEG], ax                            ;#0DA6: A3 52 02
        add     ax, cx                                         ;#0DA9: 03 C1
        mov     [PSP_TOP_OF_MEM], ax                           ;#0DAB: A3 02 00
        clc                                                    ;#0DAE: F8
        ret                                                    ;#0DAF: C3

RESTORE_CONTEXT:
        ; Copy the SAVE_CONTEXT block home from SAVED_CONTEXT_SEG
        push    ds                                             ;#0DB0: 1E
        ; The resident half saves and restores its variable area around a child.  The
        ; start is a real variable, SAVED_CONTEXT_SEG; the end had no name of its own
        ; until #1204 gave it one:
        ;
        ; 1294    mov     bx, RESIDENT_CONTEXT_END    ; the END of the region
        ; sub     bx, SAVED_CONTEXT_SEG       ; ...less 0337h, its START
        ; add     bx, 0Fh
        ; mov     cl, 4
        ; shr     bx, cl                      ; = 30h paragraphs for 2F2h bytes
        ; mov     ah, 48h
        ; int     21h
        ; jb      short SAVECTX_RETURN                 ; no room -- give up on saving
        ; mov     es, ax
        ; xor     di, di
        ; mov     si, SAVED_CONTEXT_SEG       ; 0337h again, as an offset
        ; mov     cx, RESIDENT_CONTEXT_END
        ; sub     cx, si
        ; rep     movsb
        ; mov     [SAVED_CONTEXT_SEG], es     ; NOW a memory operand
        ;
        ; So the block is 0337h..0629h -- 754 bytes -- and the segment it was copied to
        ; is written into the first word of the region itself.  0DB6h reads it back
        ; with `mov ds, [SAVED_CONTEXT_SEG]` to copy the block home.
        ;
        ; This note used to end by arguing that neither bound was worth naming.  That
        ; was wrong about the upper one.  0629h is where the message table starts, so
        ; annotate rendered all five uses of it as ERRMSG_DISCO_PROTEGIDO -- five lines
        ; that read as though a message address were being subtracted.  The EQU added
        ; in #1204, with a [code] override at each site, costs nothing to read.
        push    ds                                             ;#0DB1: 1E
        pop     es                                             ;#0DB2: 07
        mov     di, SAVED_CONTEXT_SEG                          ;#0DB3: BF 37 03
        mov     ds, [SAVED_CONTEXT_SEG]                        ;#0DB6: 8E 1E 37 03
        xor     si, si                                         ;#0DBA: 33 F6
        mov     cx, RESIDENT_CONTEXT_END                       ;#0DBC: B9 29 06
        sub     cx, di                                         ;#0DBF: 2B CF
        rep     movsb                                          ;#0DC1: F3 A4
        push    ds                                             ;#0DC3: 1E
        pop     es                                             ;#0DC4: 07
        pop     ds                                             ;#0DC5: 1F
        mov     ah, 49h                                        ;#0DC6: B4 49
        int     21h                                            ;#0DC8: CD 21
        mov     al, [SHELL_FLAGS_CLEARED]                      ;#0DCA: A0 36 03
        not     al                                             ;#0DCD: F6 D0
        and     [SHELL_FLAGS], al                              ;#0DCF: 20 06 39 03
        xor     ax, ax                                         ;#0DD3: 33 C0
        cmp     [SAVED_CONTEXT_SEG], ax                        ;#0DD5: 39 06 37 03
        jnz     short RESTORECTX_RETURN                        ;#0DD9: 75 03
        mov     [SHELL_FLAGS_CLEARED], al                      ;#0DDB: A2 36 03
RESTORECTX_RETURN:
        ; No saved context, or it has been taken back
        ret                                                    ;#0DDE: C3

FIND_ENV_STRING:
        ; Scan the PSP+2Ch environment for the string at DI (COMSPEC=)
        push    ds                                             ;#0DDF: 1E
        pop     es                                             ;#0DE0: 07
        mov     ax, [PSP_ENV_SEG]                              ;#0DE1: A1 2C 00
        or      ax, ax                                         ;#0DE4: 0B C0
        jz      short ENV_STRING_NOT_FOUND                     ;#0DE6: 74 44
        mov     ds, ax                                         ;#0DE8: 8E D8
        xor     si, si                                         ;#0DEA: 33 F6
ENVFIND_NEXT_STRING:
        ; Start the name again against this string
        mov     di, ENV_NAME_COMSPEC_1                         ;#0DEC: BF 40 0B
        cmp     byte [si], 0                                   ;#0DEF: 80 3C 00
        jz      short ENV_STRING_NOT_FOUND                     ;#0DF2: 74 38
ENVFIND_COMPARE_CHAR:
        ; One character each side
        lodsb                                                  ;#0DF4: AC
        inc     di                                             ;#0DF5: 47
        cmp     [es:di-1], al                                  ;#0DF6: 26 38 45 FF
        jz      short ENVFIND_CHECK_EQUALS                     ;#0DFA: 74 07
ENVFIND_SKIP_STRING:
        ; No match: run to this string's NUL
        or      al, al                                         ;#0DFC: 0A C0
        jz      short ENVFIND_NEXT_STRING                      ;#0DFE: 74 EC
        lodsb                                                  ;#0E00: AC
        jmp     short ENVFIND_SKIP_STRING                      ;#0E01: EB F9

ENVFIND_CHECK_EQUALS:
        ; The name matched only if '=' comes next
        cmp     al, "="                                        ;#0E03: 3C 3D
        jnz     short ENVFIND_COMPARE_CHAR                     ;#0E05: 75 ED
        mov     al, [si]                                       ;#0E07: 8A 04
        cmp     al, " "                                        ;#0E09: 3C 20
        jbe     short ENV_STRING_NOT_FOUND                     ;#0E0B: 76 1F
        cmp     al, ";"                                        ;#0E0D: 3C 3B
        jz      short ENV_STRING_NOT_FOUND                     ;#0E0F: 74 1B
        cmp     al, ","                                        ;#0E11: 3C 2C
        jz      short ENV_STRING_NOT_FOUND                     ;#0E13: 74 17
        push    es                                             ;#0E15: 06
        push    ds                                             ;#0E16: 1E
        pop     es                                             ;#0E17: 07
        mov     di, si                                         ;#0E18: 8B FE
        push    cx                                             ;#0E1A: 51
        mov     cx, 50h                                        ;#0E1B: B9 50 00
        xor     al, al                                         ;#0E1E: 32 C0
        repne   scasb                                          ;#0E20: F2 AE
        pop     cx                                             ;#0E22: 59
        pop     es                                             ;#0E23: 07
        jnz     short ENV_STRING_NOT_FOUND                     ;#0E24: 75 06
        mov     cx, di                                         ;#0E26: 8B CF
        sub     cx, si                                         ;#0E28: 2B CE
        clc                                                    ;#0E2A: F8
        ret                                                    ;#0E2B: C3

ENV_STRING_NOT_FOUND:
        ; FIND_ENV_STRING's carry-set exit; 0E2Ah is the clc one
        stc                                                    ;#0E2C: F9
        ret                                                    ;#0E2D: C3

FIND_ENV_STRING_SAVED:
        ; FIND_ENV_STRING with DS, ES, SI and DI kept
        push    ds                                             ;#0E2E: 1E
        push    es                                             ;#0E2F: 06
        push    si                                             ;#0E30: 56
        push    di                                             ;#0E31: 57
        call    near FIND_ENV_STRING                           ;#0E32: E8 AA FF
        jb      short ENVSAVED_RETURN                          ;#0E35: 72 05
        mov     di, STUB_NAME_BUF                              ;#0E37: BF 00 02
        rep     movsb                                          ;#0E3A: F3 A4
ENVSAVED_RETURN:
        ; Copied to STUB_NAME_BUF, or carry
        pop     di                                             ;#0E3C: 5F
        pop     si                                             ;#0E3D: 5E
        pop     es                                             ;#0E3E: 07
        pop     ds                                             ;#0E3F: 1F
        ret                                                    ;#0E40: C3

PRINT_BLANK_LINE:
        ; PRINT_MSG_SAFELY with DX preset to ERRMSG_CRLF
        mov     dx, ERRMSG_CRLF                                ;#0E41: BA 1B 08
PRINT_MSG_SAFELY:
        ; Save BRASCII state and the caller's JFT around PRINT_COMPRESSED_MSG
        push    dx                                             ;#0E44: 52
        call    near SISNE_18_BRASCII_FN3                      ;#0E45: E8 E9 FD
        mov     [BRASCII_SAVED], dx                            ;#0E48: 89 16 8E 02
        cmp     dh, 1                                          ;#0E4C: 80 FE 01
        jz      short MSGSAFE_PRINT_IT                         ;#0E4F: 74 03
        call    near SISNE_18_BRASCII_FN4                      ;#0E51: E8 CA FD
MSGSAFE_PRINT_IT:
        ; BRASCII settled: save the JFT and print
        pop     dx                                             ;#0E54: 5A
        call    near SAVE_CALLER_JFT                           ;#0E55: E8 DA FE
        call    near PRINT_COMPRESSED_MSG                      ;#0E58: E8 12 00
        call    near RESTORE_CALLER_JFT                        ;#0E5B: E8 FD FE
        push    dx                                             ;#0E5E: 52
        mov     dx, [BRASCII_SAVED]                            ;#0E5F: 8B 16 8E 02
        cmp     dh, 1                                          ;#0E63: 80 FE 01
        jz      short MSGSAFE_RETURN                           ;#0E66: 74 03
        call    near SET_BRASCII_FROM_DX                       ;#0E68: E8 B6 FD
MSGSAFE_RETURN:
        ; DX back as the caller left it
        pop     dx                                             ;#0E6B: 5A
        ret                                                    ;#0E6C: C3

PRINT_COMPRESSED_MSG:
        ; DX to a message; bytes from 0B0h up are references to entries (#954)
        push    ax                                             ;#0E6D: 50
        push    dx                                             ;#0E6E: 52
        push    si                                             ;#0E6F: 56
        mov     si, dx                                         ;#0E70: 8B F2
COMPRESSED_NEXT_BYTE:
        ; Literal, reference, or the 0FFh terminator
        lodsb                                                  ;#0E72: AC
        cmp     al, 0B0h                                       ;#0E73: 3C B0
        jb      short COMPRESSED_PUT_CHAR                      ;#0E75: 72 16
        cmp     al, 0FFh                                       ;#0E77: 3C FF
        jz      short COMPRESSED_RETURN                        ;#0E79: 74 1A
        sub     al, 0B0h                                       ;#0E7B: 2C B0
        cbw                                                    ;#0E7D: 98
        shl     ax, 1                                          ;#0E7E: D1 E0
        push    bx                                             ;#0E80: 53
        mov     bx, ax                                         ;#0E81: 8B D8
        mov     dx, [bx+ERROR_MSG_INDEX]                       ;#0E83: 8B 97 00 09
        pop     bx                                             ;#0E87: 5B
        call    near PRINT_COMPRESSED_MSG                      ;#0E88: E8 E2 FF
        jmp     short COMPRESSED_NEXT_BYTE                     ;#0E8B: EB E5

COMPRESSED_PUT_CHAR:
        ; Below 0B0h: it stands for itself
        mov     dl, al                                         ;#0E8D: 8A D0
        mov     ah, 2                                          ;#0E8F: B4 02
        int     21h                                            ;#0E91: CD 21
        jmp     short COMPRESSED_NEXT_BYTE                     ;#0E93: EB DD

COMPRESSED_RETURN:
        ; 0FFh ends this piece, not the whole message
        pop     si                                             ;#0E95: 5E
        pop     dx                                             ;#0E96: 5A
        pop     ax                                             ;#0E97: 58
        ret                                                    ;#0E98: C3

RESIDENT_PROMPT_ENTRY:
        ; Re-establish SS:SP=CS:200h, DS=ES=CS, reinstall the vectors, back to the prompt
        ; Where control lands after anything at all has run, so it assumes nothing:
        ;
        ; 0E99    cli
        ; push    cs
        ; pop     ss
        ; mov     sp, 200h
        ; sti
        ;
        ; The stack is rebuilt before a single push, and the `cli` brackets it because SS
        ; and SP take two instructions to set and an interrupt between them would run on
        ; half a stack.  200h is STUB_NAME_BUF's address read as a stack top -- the same
        ; 0200h that #1152 found holding COMMAND.COM's path, used from the other end.
        ;
        ; Then seven words go to offset 0Ah.  That is the PSP's save area for the INT
        ; 22h, 23h and 24h vectors, which DOS reads back when the process ends, so
        ; putting them there is not bookkeeping -- it is what makes the *next* child
        ; inherit the right handlers.
        ;
        ; SHELL_FLAGS decides between two quite different endings:
        ;
        ; 0ED2    mov     al, [SHELL_FLAGS]
        ; test    al, 7
        ; jnz     short PROMPT_ENTER_TRANSIENT
        ; test    al, 0D0h
        ; jnz     short PROMPT_FREE_TRANSIENT
        ;
        ; Bits 0-2 are FOR, pipe and batch -- something is still in progress, so restore
        ; the redirection, reload the transient if RELOAD_PENDING asked, and jump back
        ; into it.  None of those and one of the high bits instead, and 0EFBh takes the
        ; other road: restore the redirection and hand the transient's memory back with
        ; AH=49h.
        ;
        ; So the shell gives up its own working memory whenever it has nothing to resume,
        ; and takes it again next time.  That is the same trade as #1166's batch reader
        ; reopening per line and #1128's COPY replaying its search -- hold nothing across
        ; the part you do not control -- applied to the transient itself.
        cli                                                    ;#0E99: FA
        push    cs                                             ;#0E9A: 0E
        pop     ss                                             ;#0E9B: 17
        mov     sp, 200h                                       ;#0E9C: BC 00 02
        sti                                                    ;#0E9F: FB
        cld                                                    ;#0EA0: FC
        push    cs                                             ;#0EA1: 0E
        pop     ds                                             ;#0EA2: 1F
        push    cs                                             ;#0EA3: 0E
        pop     es                                             ;#0EA4: 07
        mov     si, INT_22_23_24_VECTORS                       ;#0EA5: BE 64 02
        mov     di, 0Ah                                        ;#0EA8: BF 0A 00
        mov     cx, 7                                          ;#0EAB: B9 07 00
        rep     movsw                                          ;#0EAE: F3 A5
        xor     al, al                                         ;#0EB0: 32 C0
        mov     [ERROR_LOCATION_CHAR], al                      ;#0EB2: A2 87 02
        mov     [BAT_READING], al                              ;#0EB5: A2 88 02
        mov     [FOR_NEST_GUARD], al                           ;#0EB8: A2 35 03
        cmp     [RELOAD_FAILED], al                            ;#0EBB: 38 06 90 02
        jnz     short PROMPT_CHECK_FLAGS                       ;#0EBF: 75 11
        cmp     [RELOAD_PENDING], al                           ;#0EC1: 38 06 78 02
        jz      short PROMPT_CHECK_TRANSIENT                   ;#0EC5: 74 03
        call    near INSTALL_INT_22_23_24                      ;#0EC7: E8 98 FC
PROMPT_CHECK_TRANSIENT:
        ; Is the transient still where we left it
        call    near SISNE_18_BRASCII_FN4                      ;#0ECA: E8 51 FD
        call    near HAVE_TRANSIENT_BLOCK                      ;#0ECD: E8 A0 FE
        jb      short PROMPT_NO_TRANSIENT                      ;#0ED0: 72 26
PROMPT_CHECK_FLAGS:
        ; FOR, chain or redirection still pending
        mov     al, [SHELL_FLAGS]                              ;#0ED2: A0 39 03
        test    al, 7                                          ;#0ED5: A8 07
        jnz     short PROMPT_ENTER_TRANSIENT                   ;#0ED7: 75 04
        test    al, 0D0h                                       ;#0ED9: A8 D0
        jnz     short PROMPT_FREE_TRANSIENT                    ;#0EDB: 75 1E
PROMPT_ENTER_TRANSIENT:
        ; Undo redirection and go back in
        mov     byte [SHELL_FLAGS_CLEARED], 0                  ;#0EDD: C6 06 36 03 00
        call    near RESTORE_REDIRECTION                       ;#0EE2: E8 E1 FD
        cmp     byte [RELOAD_PENDING], 0                       ;#0EE5: 80 3E 78 02 00
        jz      short PROMPT_JUMP_TO_TRANSIENT                 ;#0EEA: 74 08
        call    near RELOAD_TRANSIENT_IF_BAD                   ;#0EEC: E8 7B 02
        mov     byte [RELOAD_PENDING], 0                       ;#0EEF: C6 06 78 02 00
PROMPT_JUMP_TO_TRANSIENT:
        ; Far jump through the saved entry point
        jmp     far word [TRANSIENT_ENTRY_OFF]                 ;#0EF4: FF 2E 50 02

PROMPT_NO_TRANSIENT:
        ; The block is gone: report and start over
        jmp     near REPORT_AND_RESET                          ;#0EF8: E9 F9 02

PROMPT_FREE_TRANSIENT:
        ; Release the block before starting over
        call    near RESTORE_REDIRECTION                       ;#0EFB: E8 C8 FD
        xor     ax, ax                                         ;#0EFE: 33 C0
        xchg    [TRANSIENT_BLOCK_SEG], ax                      ;#0F00: 87 06 72 02
        mov     es, ax                                         ;#0F04: 8E C0
        mov     ah, 49h                                        ;#0F06: B4 49
        int     21h                                            ;#0F08: CD 21
POST_CHILD_DISPATCH:
        ; Branch on SHELL_FLAGS 10h, 40h then 80h; 80h is set when none matched
        ; The three high SHELL_FLAGS bits are not independent states like 0, 1 and 2 --
        ; they choose which way out of a finished child:
        ;
        ; 0F0A    mov     al, [SHELL_FLAGS]
        ; test    al, 10h
        ; jnz     short RESTORE_AND_PROMPT
        ; test    al, 40h
        ; jnz     short RETURN_TO_FARCALL_CALLER   ; back to the caller
        ; test    al, 80h
        ; jnz     short POST_CHILD_SECOND_PASS
        ; test    byte [SHELL_FLAGS], 50h
        ; jnz     short PROMPTFLAG_GO
        ; or      byte [SHELL_FLAGS], SHELL_BEEN_HERE
        ; jmp     near RESIDENT_PROMPT_ENTRY
        ;
        ; Bit 80h is set by that last arm and consumed by the 0F17h test, so it marks
        ; "been here once" rather than describing any state.  The 40h arm is the
        ; interesting one and is fully readable: it puts the caller's PSP back with
        ; AH=50h, zeroes CMD_TAIL_PTR, restores BX and DX from the trampoline slots,
        ; arms RELOAD_PENDING and leaves through FARCALL_RET_OFF -- so a program that
        ; called COMMAND.COM gets control back with its own PSP.  What sets 40h is not
        ; visible here; 122Ch builds SHELL_FLAGS with `or al, ah` in the "Impossível
        ; ativar COMMAND.COM" path, which is suggestive and not proof.
        mov     al, [SHELL_FLAGS]                              ;#0F0A: A0 39 03
        test    al, 10h                                        ;#0F0D: A8 10
        jnz     short RESTORE_AND_PROMPT                       ;#0F0F: 75 17
        test    al, 40h                                        ;#0F11: A8 40
        jnz     short RETURN_TO_FARCALL_CALLER                 ;#0F13: 75 19
        test    al, 80h                                        ;#0F15: A8 80
        jnz     short POST_CHILD_SECOND_PASS                   ;#0F17: 75 40
PROMPT_ENTRY_MARK_SEEN:
        ; Set SHELL_BEEN_HERE unless 50h is already on, then fall into the above
        test    byte [SHELL_FLAGS], 50h                        ;#0F19: F6 06 39 03 50
        jnz     short PROMPTFLAG_GO                            ;#0F1E: 75 05
        or      byte [SHELL_FLAGS], SHELL_BEEN_HERE            ;#0F20: 80 0E 39 03 80
PROMPTFLAG_GO:
        ; Bit 7 set unless 10h or 40h already was
        jmp     near RESIDENT_PROMPT_ENTRY                     ;#0F25: E9 71 FF

RESTORE_AND_PROMPT:
        ; SHELL_HAVE_CONTEXT: RESTORE_CONTEXT, then back to the prompt
        call    near RESTORE_CONTEXT                           ;#0F28: E8 85 FE
        jmp     near RESIDENT_PROMPT_ENTRY                     ;#0F2B: E9 6B FF

RETURN_TO_FARCALL_CALLER:
        ; AH=50h back to the caller PSP, arm RELOAD_PENDING, retf through the slot
        mov     byte [SHELL_FLAGS_CLEARED], 0                  ;#0F2E: C6 06 36 03 00
        call    near RESTORE_CONTEXT                           ;#0F33: E8 7A FE
        xor     ax, ax                                         ;#0F36: 33 C0
        mov     [CMD_TAIL_PTR], ax                             ;#0F38: A3 89 02
        mov     bx, [FARCALL_SAVED_BX]                         ;#0F3B: 8B 1E 23 06
        mov     ah, 50h                                        ;#0F3F: B4 50
        int     21h                                            ;#0F41: CD 21
        mov     dx, [FARCALL_SAVED_DX]                         ;#0F43: 8B 16 21 06
        call    near SET_BRASCII_FROM_DX                       ;#0F47: E8 D7 FC
        xor     ax, ax                                         ;#0F4A: 33 C0
        xchg    [RELOAD_FAILED], al                            ;#0F4C: 86 06 90 02
        mov     byte [RELOAD_PENDING], 1                       ;#0F50: C6 06 78 02 01
        jmp     far word [FARCALL_RET_OFF]                     ;#0F55: FF 2E 25 06

POST_CHILD_SECOND_PASS:
        ; SHELL_BEEN_HERE was already set — the been-here-once arm
        cmp     byte [STARTUP_DONE], 0                         ;#0F59: 80 3E 77 02 00
        jz      short SECONDPASS_RESTORE_BRASCII               ;#0F5E: 74 08
        and     byte [SHELL_FLAGS], 7Fh                        ;#0F60: 80 26 39 03 7F
        jmp     near RESIDENT_PROMPT_ENTRY                     ;#0F65: E9 31 FF

SECONDPASS_RESTORE_BRASCII:
        ; A temporary shell puts the code page back
        mov     dx, [BRASCII_AT_STARTUP]                       ;#0F68: 8B 16 8C 02
        call    near SET_BRASCII_FROM_DX                       ;#0F6C: E8 B2 FC
        push    cs                                             ;#0F6F: 0E
        pop     es                                             ;#0F70: 07
        mov     si, SAVED_INT_VECTORS                          ;#0F71: BE 56 02
        mov     di, 0Ah                                        ;#0F74: BF 0A 00
        mov     cx, 7                                          ;#0F77: B9 07 00
        rep     movsw                                          ;#0F7A: F3 A5
        mov     ax, 4C00h                                      ;#0F7C: B8 00 4C
        int     21h                                            ;#0F7F: CD 21
INT_23_HANDLER:
        ; Ctrl-C handler; the far pointer at 0268h reaches it
        sti                                                    ;#0F81: FB
        cld                                                    ;#0F82: FC
        mov     ah, 0Dh                                        ;#0F83: B4 0D
        int     21h                                            ;#0F85: CD 21
        push    cs                                             ;#0F87: 0E
        pop     ds                                             ;#0F88: 1F
        and     byte [SHELL_FLAGS], 0FCh                       ;#0F89: 80 26 39 03 FC
        or      byte [SHELL_FLAGS_CLEARED], 3                  ;#0F8E: 80 0E 36 03 03
        call    near ASK_ABORT_BATCH                           ;#0F93: E8 03 00
        stc                                                    ;#0F96: F9
        retf                                                   ;#0F97: CB

BATCH_ABORT_IGNORE:
        ; The iret VEC_BATCH_ABORT points at; the routine is the next byte
        iret                                                   ;#0F98: CF

ASK_ABORT_BATCH:
        ; "Cancelar arquivo de comandos (S/N)?" — N keeps going
        call    near CHECK_BATCH_ACTIVE                        ;#0F99: E8 22 00
        jz      short ABORT_RETURN                             ;#0F9C: 74 1F
        call    near PRINT_BLANK_LINE                          ;#0F9E: E8 A0 FE
ABORT_ASK_AGAIN:
        ; Anything but N, S or Return asks once more
        mov     dx, SYSMSG_CANCELAR_ARQUIVO_DE_COMANDOS_S      ;#0FA1: BA 70 09
        call    near ASK_AND_READ_KEY                          ;#0FA4: E8 10 FC
        cmp     al, "N"                                        ;#0FA7: 3C 4E
        jz      short ABORT_RETURN                             ;#0FA9: 74 12
        cmp     al, "S"                                        ;#0FAB: 3C 53
        jz      short ABORT_STOP_BATCH                         ;#0FAD: 74 04
        cmp     al, ASCII_CR                                   ;#0FAF: 3C 0D
        jnz     short ABORT_ASK_AGAIN                          ;#0FB1: 75 EE
ABORT_STOP_BATCH:
        ; Drop SHELL_BATCH_ACTIVE and note that it was dropped
        and     byte [SHELL_FLAGS], 0FBh                       ;#0FB3: 80 26 39 03 FB
        or      byte [SHELL_FLAGS_CLEARED], SHELL_BATCH_ACTIVE ;#0FB8: 80 0E 36 03 04
ABORT_RETURN:
        ; No batch running, or the answer was no
        ret                                                    ;#0FBD: C3

CHECK_BATCH_ACTIVE:
        ; SHELL_BATCH_ACTIVE through a zeroed BX, so later [bx+n] forms reuse it
        push    ds                                             ;#0FBE: 1E
        push    bx                                             ;#0FBF: 53
        xor     bx, bx                                         ;#0FC0: 33 DB
BATCH_ACTIVE_TEST:
        ; Bit 2 here, or in a saved context further down
        test    byte [bx+SHELL_FLAGS], 4                       ;#0FC2: F6 87 39 03 04
        jnz     short BATCH_ACTIVE_ANSWER                      ;#0FC7: 75 19
        test    byte [bx+SHELL_FLAGS], 10h                     ;#0FC9: F6 87 39 03 10
        jz      short BATCH_ACTIVE_ANSWER                      ;#0FCE: 74 12
        cmp     word [bx+SAVED_CONTEXT_SEG], 0                 ;#0FD0: 83 BF 37 03 00
        jz      short BATCH_ACTIVE_ANSWER                      ;#0FD5: 74 0B
        mov     ds, [bx+SAVED_CONTEXT_SEG]                     ;#0FD7: 8E 9F 37 03
        mov     bx, SAVED_CONTEXT_SEG                          ;#0FDB: BB 37 03
        neg     bx                                             ;#0FDE: F7 DB
        jmp     short BATCH_ACTIVE_TEST                        ;#0FE0: EB E0

BATCH_ACTIVE_ANSWER:
        ; Zero flag says whether a batch file is running
        pop     bx                                             ;#0FE2: 5B
        pop     ds                                             ;#0FE3: 1F
        ret                                                    ;#0FE4: C3

INT_24_HANDLER:
        ; Critical-error handler; the far pointer at 026Ch reaches it
        jmp     word [cs:VEC_INT24_ACTION]                     ;#0FE5: 2E FF 26 85 02

INT_24_IGNORE:
        ; AL=0 and iret: the do-nothing INT 24h policy
        mov     al, 0                                          ;#0FEA: B0 00
        iret                                                   ;#0FEC: CF

INT_24_REPORT:
        ; The reporting policy — saves everything and builds the message
        ; The message is mutable, so the first thing the handler does is undo the last
        ; error:
        ;
        ; 0FFE    mov     byte [SYSMSG_ERRO_DE+ERRO_AREA], 0CEh
        ; mov     byte [SYSMSG_ERRO_DE+ERRO_DAMAGE], 0CEh
        ; mov     byte [SYSMSG_ERRO_DE+ERRO_SUBJECT], 0FFh
        ; call    near FILL_ERROR_LOCATION
        ;
        ; SYSMSG_ERRO_DE is a template with three slots in it, and FILL_ERROR_LOCATION
        ; writes the drive letter or device name into them.  Resetting them first is not
        ; tidiness: a critical error can arrive while the bytes still hold whatever the
        ; previous one put there, and nothing else ever clears them.
        ;
        ; The 0FFh is also a question.  If it is still there afterwards,
        ; FILL_ERROR_LOCATION found nothing to name, and 1017h falls back to
        ; COPY_VOLUME_LABEL -- so an error on a disk with no identifiable device gets
        ; identified by its volume label instead.
        ;
        ; The prompt itself is four bytes of text and one instruction of policy:
        ;
        ; 1033    cmp al, ASCII_CR
        ; jnz     short INT24_LOOK_UP_LETTER
        ; mov al, "P"
        ; 1039    mov     di, ERR_OPTION_LETTERS_B
        ; mov     cx, 4
        ; repne   scasb
        ; jnz     short INT24_ASK_CHOICE
        ; dec     cl
        ; and     cl, 3
        ;
        ; Enter is Persistir.  Pressing it costs one `mov al, "P"`, which is the cheapest
        ; possible way to give a prompt a default, and the retry is the safe answer to
        ; choose blind.  Ctrl-C is handled earlier, at 102Fh, and takes the same exit as
        ; Cancelar.
        ;
        ; Which option was picked never gets looked up.  `repne scasb` leaves CX counting
        ; down from four, so the leftover count *is* the index, and `dec cl / and cl, 3`
        ; turns it into the number the code below wants.  The scan and the decode are the
        ; same work done once.
        sti                                                    ;#0FED: FB
        cld                                                    ;#0FEE: FC
        push    ds                                             ;#0FEF: 1E
        push    es                                             ;#0FF0: 06
        push    bp                                             ;#0FF1: 55
        push    si                                             ;#0FF2: 56
        push    di                                             ;#0FF3: 57
        push    dx                                             ;#0FF4: 52
        push    cx                                             ;#0FF5: 51
        push    bx                                             ;#0FF6: 53
        push    ax                                             ;#0FF7: 50
        mov     bp, sp                                         ;#0FF8: 8B EC
        push    cs                                             ;#0FFA: 0E
        pop     ds                                             ;#0FFB: 1F
        push    cs                                             ;#0FFC: 0E
        pop     es                                             ;#0FFD: 07
        mov     byte [SYSMSG_ERRO_DE+ERRO_AREA], 0CEh          ;#0FFE: C6 06 93 09 CE
        mov     byte [SYSMSG_ERRO_DE+ERRO_DAMAGE], 0CEh        ;#1003: C6 06 94 09 CE
        mov     byte [SYSMSG_ERRO_DE+ERRO_SUBJECT], 0FFh       ;#1008: C6 06 87 09 FF
        call    near FILL_ERROR_LOCATION                       ;#100D: E8 6C 00
        cmp     byte [SYSMSG_ERRO_DE+ERRO_SUBJECT], 0FFh       ;#1010: 80 3E 87 09 FF
        jnz     short INT24_PRINT_MESSAGE                      ;#1015: 75 03
        call    near COPY_VOLUME_LABEL                         ;#1017: E8 E3 00
INT24_PRINT_MESSAGE:
        ; The assembled 'Erro de ...' line
        mov     dx, SYSMSG_ERRO_DE                             ;#101A: BA 85 09
        call    near PRINT_MSG_SAFELY                          ;#101D: E8 24 FE
        or      bh, bh                                         ;#1020: 0A FF
        jz      short INT24_ASK_CHOICE                         ;#1022: 74 05
        call    near ASK_FOR_COMMAND_COM                       ;#1024: E8 BC 01
        jmp     short INT24_ABORT                              ;#1027: EB 37

INT24_ASK_CHOICE:
        ; Cancelar, Persistir or Ignorar
        mov     dx, SYSMSG_CANCELAR_PERSISTIR_IGNORAR          ;#1029: BA A3 09
        call    near ASK_AND_READ_KEY                          ;#102C: E8 88 FB
        cmp     al, 3                                          ;#102F: 3C 03
        jz      short INT24_ABORT                              ;#1031: 74 2D
        cmp     al, ASCII_CR                                   ;#1033: 3C 0D
        jnz     short INT24_LOOK_UP_LETTER                     ;#1035: 75 02
        mov     al, "P"                                        ;#1037: B0 50
INT24_LOOK_UP_LETTER:
        ; Which of the four letters was pressed
        mov     di, ERR_OPTION_LETTERS_B                       ;#1039: BF AC 09
        mov     cx, 4                                          ;#103C: B9 04 00
        repne   scasb                                          ;#103F: F2 AE
        jnz     short INT24_ASK_CHOICE                         ;#1041: 75 E6
        dec     cl                                             ;#1043: FE C9
        and     cl, 3                                          ;#1045: 80 E1 03
        cmp     cl, 2                                          ;#1048: 80 F9 02
        jnz     short INT24_RETURN_CODE                        ;#104B: 75 22
        cmp     byte [BAT_READING], 0                          ;#104D: 80 3E 88 02 00
        jnz     short INT24_ABORT                              ;#1052: 75 0C
        and     byte [SHELL_FLAGS], 0FCh                       ;#1054: 80 26 39 03 FC
        or      byte [SHELL_FLAGS_CLEARED], 3                  ;#1059: 80 0E 36 03 03
        jmp     short INT24_RETURN_CODE                        ;#105E: EB 0F

INT24_ABORT:
        ; Give the batch file a chance to stop too
        and     byte [SHELL_FLAGS], 0FCh                       ;#1060: 80 26 39 03 FC
        or      byte [SHELL_FLAGS_CLEARED], 3                  ;#1065: 80 0E 36 03 03
        call    near ASK_ABORT_BATCH                           ;#106A: E8 2C FF
        mov     cl, 2                                          ;#106D: B1 02
INT24_RETURN_CODE:
        ; CL goes back to the caller of the handler
        mov     [bp], cl                                       ;#106F: 88 4E 00
        pop     ax                                             ;#1072: 58
        pop     bx                                             ;#1073: 5B
        pop     cx                                             ;#1074: 59
        pop     dx                                             ;#1075: 5A
        pop     di                                             ;#1076: 5F
        pop     si                                             ;#1077: 5E
        pop     bp                                             ;#1078: 5D
        pop     es                                             ;#1079: 07
        pop     ds                                             ;#107A: 1F
        iret                                                   ;#107B: CF

FILL_ERROR_LOCATION:
        ; Choose the message references INT_24_REPORT's template will expand
        ; The critical-error line is not built from text.  It is built from references,
        ; written into the template #1139 found INT_24_REPORT resetting on the way in:
        ;
        ; 1093    test    ah, 1
        ; mov     cl, 0D9h
        ; jz      short ERRLOC_CHECK_DEVICE
        ; mov     cl, 0DAh
        ; 109C    test    bl, 80h
        ; mov     ch, 0DCh
        ; ...
        ; 10B5    mov     [SYSMSG_ERRO_DE+ERRO_ACTION], cl
        ; mov     [SYSMSG_ERRO_DE+ERRO_PLACE], ch
        ;
        ; Every one of those bytes is 0B0h or above, which #954's scheme reads as "entry
        ; n of the first group".  0D9h is entry 41, "leitura", and 0DAh is 42,
        ; "escrita" -- AH bit 0 chooses which.  0DBh and 0DCh are " na" and " no
        ; dispositivo", picked by bit 15 of the device attribute at [si+5].  0DFh is
        ; "danificada", 0E0h is "área afetada:", and 0E1h through 0E4h are "Sistema",
        ; "Tabela de alocação (FAT)", "Diretório" and "Dados" -- which is why the area is
        ; computed as `shr al, 1 / and al, 3 / add al, 0E1h` rather than looked up: the
        ; two bits INT 24h puts in AH are already the index, and adding the base of a run
        ; of four consecutive entries turns them into the reference.
        ;
        ; The device name is the one part copied as characters.  1082h loads the device
        ; header from the saved BP:SI, steps 0Ah into it, and moves eight bytes with four
        ; `movsw` -- a fixed-size field needing no terminator and no count.
        ;
        ; So the whole line is chosen rather than composed: five reference bytes and one
        ; eight-character name, and the expander does the rest.  Nothing here knows what
        ; any of the words are.
        add     al, "A"                                        ;#107C: 04 41
        mov     [ERRMSG_NA_UNIDADE+4], al                      ;#107E: A2 56 08
        push    ds                                             ;#1081: 1E
        lds     si, [bp+0Ah]                                   ;#1082: C5 76 0A
        mov     bl, [si+5]                                     ;#1085: 8A 5C 05
        add     si, 0Ah                                        ;#1088: 83 C6 0A
        mov     di, ERRMSG_NO_DISPOSITIVO+10h                  ;#108B: BF 69 08
        movsw                                                  ;#108E: A5
        movsw                                                  ;#108F: A5
        movsw                                                  ;#1090: A5
        movsw                                                  ;#1091: A5
        pop     ds                                             ;#1092: 1F
        test    ah, 1                                          ;#1093: F6 C4 01
        mov     cl, 0D9h                                       ;#1096: B1 D9
        jz      short ERRLOC_CHECK_DEVICE                      ;#1098: 74 02
        mov     cl, 0DAh                                       ;#109A: B1 DA
ERRLOC_CHECK_DEVICE:
        ; Bit 7 of BL: a device rather than a drive
        test    bl, 80h                                        ;#109C: F6 C3 80
        mov     ch, 0DCh                                       ;#109F: B5 DC
        mov     bh, 0                                          ;#10A1: B7 00
        jnz     short ERRLOC_STORE_CODES                       ;#10A3: 75 10
        mov     ch, 0DBh                                       ;#10A5: B5 DB
        mov     bh, [ERROR_LOCATION_CHAR]                      ;#10A7: 8A 3E 87 02
        test    ah, 80h                                        ;#10AB: F6 C4 80
        jz      short ERRLOC_STORE_CODES                       ;#10AE: 74 05
        mov     byte [SYSMSG_ERRO_DE+ERRO_SUBJECT], 0DFh       ;#10B0: C6 06 87 09 DF
ERRLOC_STORE_CODES:
        ; The two bytes that name where it happened
        mov     [SYSMSG_ERRO_DE+ERRO_ACTION], cl               ;#10B5: 88 0E 90 09
        mov     [SYSMSG_ERRO_DE+ERRO_PLACE], ch                ;#10B9: 88 2E 91 09
        test    ah, 80h                                        ;#10BD: F6 C4 80
        jnz     short ERRLOC_BUILD_OPTIONS                     ;#10C0: 75 10
        mov     al, ah                                         ;#10C2: 8A C4
        shr     al, 1                                          ;#10C4: D0 E8
        and     al, 3                                          ;#10C6: 24 03
        add     al, 0E1h                                       ;#10C8: 04 E1
        mov     [ERRMSG_AREA_AFETADA+0Fh], al                  ;#10CA: A2 98 08
        mov     byte [SYSMSG_ERRO_DE+ERRO_AREA], 0E0h          ;#10CD: C6 06 93 09 E0
ERRLOC_BUILD_OPTIONS:
        ; Then trim the four options down to the legal ones
        mov     si, SYSMSG_CANCELAR_PERSISTIR_IGNORAR_FAL      ;#10D2: BE 96 09
        mov     di, SYSMSG_CANCELAR_PERSISTIR_IGNORAR          ;#10D5: BF A3 09
        mov     cx, di                                         ;#10D8: 8B CF
        sub     cx, si                                         ;#10DA: 2B CE
        rep     movsb                                          ;#10DC: F3 A4
        inc     si                                             ;#10DE: 46
        inc     si                                             ;#10DF: 46
        mov     di, ERR_OPTION_LETTERS_B+1h                    ;#10E0: BF AD 09
        test    ah, 10h                                        ;#10E3: F6 C4 10
        call    near ADD_ERROR_OPTION                          ;#10E6: E8 09 00
        test    ah, 20h                                        ;#10E9: F6 C4 20
        call    near ADD_ERROR_OPTION                          ;#10EC: E8 03 00
        test    ah, 8                                          ;#10EF: F6 C4 08
ADD_ERROR_OPTION:
        ; Append an option letter and its table reference byte
        jnz     short ERROROPT_STEP                            ;#10F2: 75 06
        mov     byte [si], 0CEh                                ;#10F4: C6 04 CE
        mov     byte [di], "C"                                 ;#10F7: C6 05 43
ERROROPT_STEP:
        ; Both cursors on, whether or not it was copied
        inc     si                                             ;#10FA: 46
        inc     di                                             ;#10FB: 47
        ret                                                    ;#10FC: C3

COPY_VOLUME_LABEL:
        ; AH=59h, then 11 bytes into the "Coloque o disco" blank
        push    bx                                             ;#10FD: 53
        push    bp                                             ;#10FE: 55
        push    ds                                             ;#10FF: 1E
        ; The "insert the correct disk" message is filled in before it is printed:
        ;
        ; 1101    mov     ah, 59h         ; extended error info
        ; int     21h             ; ...ES:DI is the volume label
        ; push    es
        ; pop     ds
        ; mov     si, di
        ; pop     es
        ; mov     di, ERRMSG_COLOQUE_O_DISCO_CORRETO+11h
        ; mov     cx, 0Bh         ; 11 bytes
        ;
        ; 8DEh is the run of blanks in "Coloque o disco correto    ", so the volume
        ; label DOS hands back is copied straight into the message text -- the same
        ; patch-before-print trick as the reference slots at 0985h (#960) and the
        ; version digits in MSG_SISNE_PLUS.
        ;
        ; Note the frame: this code is below 2120h, in the stub, so 8DEh is a plain
        ; address and not a transient one.  #966 rewrote it as
        ; MSG_ARQUIVO_DE_COMANDOS_DEFEITUOSO less TRANSIENT_BIAS, because that
        ; sweep only checked where the TARGET landed, never where the
        ; referencing instruction was.  See #983.
        push    es                                             ;#1100: 06
        mov     ah, 59h                                        ;#1101: B4 59
        int     21h                                            ;#1103: CD 21
        push    es                                             ;#1105: 06
        pop     ds                                             ;#1106: 1F
        mov     si, di                                         ;#1107: 8B F7
        pop     es                                             ;#1109: 07
        mov     di, ERRMSG_COLOQUE_O_DISCO_CORRETO+11h         ;#110A: BF DE 08
        mov     cx, 0Bh                                        ;#110D: B9 0B 00
        pop     ds                                             ;#1110: 1F
        pop     bp                                             ;#1111: 5D
        pop     bx                                             ;#1112: 5B
        mov     cl, 0Ch                                        ;#1113: B1 0C
        sub     al, 13h                                        ;#1115: 2C 13
        jb      short VOLUME_STORE_INDEX                       ;#1117: 72 11
        mov     cl, 12h                                        ;#1119: B1 12
        cmp     al, cl                                         ;#111B: 3A C1
        jnb     short VOLUME_STORE_INDEX                       ;#111D: 73 0B
        mov     cl, al                                         ;#111F: 8A C8
        cmp     al, 0Fh                                        ;#1121: 3C 0F
        jnz     short VOLUME_STORE_INDEX                       ;#1123: 75 05
        mov     byte [SYSMSG_ERRO_DE+ERRO_DAMAGE], 0E5h        ;#1125: C6 06 94 09 E5
VOLUME_STORE_INDEX:
        ; Compressed reference: 0B0h plus the drive
        add     cl, 0B0h                                       ;#112A: 80 C1 B0
        mov     [SYSMSG_ERRO_DE+ERRO_SUBJECT], cl              ;#112D: 88 0E 87 09
        ret                                                    ;#1131: C3

EXEC_CHILD:
        ; Switch to the local stack, then INT 21h AX=4B00h to load and run a program
        cli                                                    ;#1132: FA
        push    cs                                             ;#1133: 0E
        pop     ss                                             ;#1134: 17
        mov     sp, 200h                                       ;#1135: BC 00 02
        sti                                                    ;#1138: FB
        mov     ax, 4B00h                                      ;#1139: B8 00 4B
        int     21h                                            ;#113C: CD 21
        cld                                                    ;#113E: FC
        jnb     short EXEC_CHILD_RETURNED                      ;#113F: 73 17
        push    cs                                             ;#1141: 0E
        pop     ds                                             ;#1142: 1F
        mov     bx, 0Ch                                        ;#1143: BB 0C 00
        cmp     ax, bx                                         ;#1146: 3B C3
        jnb     short EXEC_REPORT_FAILURE                      ;#1148: 73 02
        mov     bx, ax                                         ;#114A: 8B D8
EXEC_REPORT_FAILURE:
        ; AX indexes CMD_LOAD_ERROR_INDEX, 0Ch at most
        shl     bx, 1                                          ;#114C: D1 E3
        mov     dx, [bx+CMD_LOAD_ERROR_INDEX]                  ;#114E: 8B 97 0C 0B
        call    near PRINT_MSG_SAFELY                          ;#1152: E8 EF FC
