REPORT_AND_RESET:
        ; Drop FOR/pipe/batch, then resume, halt, or fall back to the prompt
        ; What to do when the transient could not be brought back.  Three outcomes, and
        ; the first thing decided is what cannot survive:
        ;
        ; 11F7    mov     al, [SHELL_FLAGS]
        ; and     al, 0F8h
        ;
        ; Bits 0, 1 and 2 are FOR, pipe and batch, and all three describe work in
        ; progress inside a transient that is now gone.  The high five stay, because they
        ; say how to resume rather than what was running.
        ;
        ; 11FE    xor     dx, dx
        ; xchg    [CMD_TAIL_PTR], dx
        ;
        ; One instruction takes the pending startup command and clears it, so whichever
        ; arm runs next cannot pick it up a second time.  What DX turns out to hold picks
        ; the POST_CHILD_DISPATCH arm: a pointer that is still 80h means nothing was
        ; consumed, anything else means part of the tail was.
        ;
        ; Then the one path with no way out:
        ;
        ; 121A    cmp     byte [STARTUP_DONE], 0
        ; jz      short RESET_MARK_AND_RETRY
        ; mov     dx, SYSMSG_IMPOSSIVEL_CARREGAR_COMMAND_CO
        ; call    near PRINT_MSG_SAFELY
        ; sti
        ; 1228    jmp     short RESET_HANG_FOREVER
        ;
        ; STARTUP_DONE is set by /P, so the halt is reserved for the permanent shell.  A
        ; secondary COMMAND.COM that cannot reload can return to whoever started it; the
        ; permanent one has nobody to return to, so it prints and stops.  `sti` before
        ; the loop is the whole courtesy: interrupts stay on, so the keyboard still
        ; answers and Ctrl-Alt-Del still reboots.
        ;
        ; Otherwise 122Ah puts the chosen bit back, records in SHELL_FLAGS_CLEARED that
        ; all three low bits were dropped, sets RELOAD_FAILED so the prompt knows not to
        ; try again, and goes back to the resident prompt with a different message -- the
        ; one that suggests EXIT.
        call    near PRINT_MSG_SAFELY                          ;#11F4: E8 4D FC
        mov     al, [SHELL_FLAGS]                              ;#11F7: A0 39 03
        and     al, 0F8h                                       ;#11FA: 24 F8
        mov     ah, 0                                          ;#11FC: B4 00
        xor     dx, dx                                         ;#11FE: 33 D2
        xchg    [CMD_TAIL_PTR], dx                             ;#1200: 87 16 89 02
        or      dx, dx                                         ;#1204: 0B D2
        jz      short RESET_CHECK_FLAGS                        ;#1206: 74 0C
        mov     ah, 80h                                        ;#1208: B4 80
        cmp     dx, PSP_TAIL_LEN                               ;#120A: 81 FA 80 00
        jnz     short RESET_MARK_AND_RETRY                     ;#120E: 75 1A
        mov     ah, 40h                                        ;#1210: B4 40
        jmp     short RESET_MARK_AND_RETRY                     ;#1212: EB 16

RESET_CHECK_FLAGS:
        ; Bits 4 and 6 mean a child is still owed
        test    al, 0D0h                                       ;#1214: A8 D0
        jnz     short RESET_MARK_AND_RETRY                     ;#1216: 75 12
        mov     ah, 80h                                        ;#1218: B4 80
        cmp     byte [STARTUP_DONE], 0                         ;#121A: 80 3E 77 02 00
        jz      short RESET_MARK_AND_RETRY                     ;#121F: 74 09
        mov     dx, SYSMSG_IMPOSSIVEL_CARREGAR_COMMAND_CO      ;#1221: BA 4C 0A
        call    near PRINT_MSG_SAFELY                          ;#1224: E8 1D FC
        sti                                                    ;#1227: FB
RESET_HANG_FOREVER:
        ; Nothing left to return to: stop here
        jmp     short RESET_HANG_FOREVER                       ;#1228: EB FE

RESET_MARK_AND_RETRY:
