        mov     byte [RELOAD_FAILED], 0FFh                     ;#123A: C6 06 90 02 FF
        jmp     near RESIDENT_PROMPT_ENTRY                     ;#123F: E9 57 FC
        cld                                                    ;#1242: FC
        push    cs                                             ;#1243: 0E
        pop     es                                             ;#1244: 07
        lodsb                                                  ;#1245: AC
        and     al, 7Fh                                        ;#1246: 24 7F
        cbw                                                    ;#1248: 98
        mov     cx, ax                                         ;#1249: 8B C8
        mov     di, PSP_TAIL_LEN                               ;#124B: BF 80 00
        rep     movsb                                          ;#124E: F3 A4
        mov     al, ASCII_CR                                   ;#1250: B0 0D
        stosb                                                  ;#1252: AA
