INIT_VERSION_AND_BANNER:
        ; Require 031Eh (DOS 3.30), then patch the version into MSG_SISNE_PLUS
        ; The version test is four instructions and the rest builds the sign-on line out
        ; of what it learned.  MSG_SISNE_PLUS is a template in the image --
        ; "  SISNE Plus  V0.00  R00$$" -- and the zeros are where the numbers go:
        ;
        ; 14BC    cmp     ax, 31Eh
        ; jnb     short INIT_PATCH_DOS_VERSION
        ; jmp     near INIT_VERSION_TOO_OLD
        ; 14C4    add     [MSG_SISNE_PLUS+BANNER_DOS_MAJOR], ah
        ; aam
        ; xchg    ah, al
        ; add     [MSG_SISNE_PLUS+BANNER_DOS_MINOR], ax
        ;
        ; Adding rather than storing is the point.  The byte already holds '0', so adding
        ; the binary 3 makes '3' without a lookup, and after `aam` splits the minor
        ; version into tens and units the `xchg` puts them in the order the text wants --
        ; so `add ...+BANNER_DOS_MINOR, ax` converts *both* digits with one word add
        ; onto two adjacent '0' characters.
        ;
        ; The release comes from AX=1808h rather than from DOS, and AL is one-based:
        ; 14D5h treats zero as unsupported and 14E9h decrements before converting, so the
        ; 6 that SISNE.SIS returns prints as R05.  A non-zero AH means a lettered
        ; release, so 14DDh writes 'P' over the 'R' and a letter over the byte at +18h,
        ; which is why the template ends in two '$' -- the first is a spare column that
        ; the letter takes when there is one, and the second still terminates the string
        ; either way.
        ;
        ; So the banner is assembled before anything is printed, and nothing later has to
        ; know how to format a version.
        call    near SISNE_18_BRASCII_FN3                      ;#14AC: E8 82 F7
        mov     [BRASCII_AT_STARTUP], dx                       ;#14AF: 89 16 8C 02
        call    near SISNE_18_BRASCII_FN4                      ;#14B3: E8 68 F7
        mov     ah, 30h                                        ;#14B6: B4 30
        int     21h                                            ;#14B8: CD 21
        xchg    al, ah                                         ;#14BA: 86 E0
        cmp     ax, 31Eh                                       ;#14BC: 3D 1E 03
        jnb     short INIT_PATCH_DOS_VERSION                   ;#14BF: 73 03
        jmp     near INIT_VERSION_TOO_OLD                      ;#14C1: E9 81 00

INIT_PATCH_DOS_VERSION:
        ; Two digits of int 21h/30h into the banner
        add     [MSG_SISNE_PLUS+BANNER_DOS_MAJOR], ah          ;#14C4: 00 26 35 0B
        aam                                                    ;#14C8: D4 0A
        xchg    ah, al                                         ;#14CA: 86 C4
        add     [MSG_SISNE_PLUS+BANNER_DOS_MINOR], ax          ;#14CC: 01 06 37 0B
        mov     ax, 1808h                                      ;#14D0: B8 08 18
        int     21h                                            ;#14D3: CD 21
        or      al, al                                         ;#14D5: 0A C0
        jz      short INIT_VERSION_TOO_OLD                     ;#14D7: 74 6C
        or      ah, ah                                         ;#14D9: 0A E4
