        mov     si, PSP_TAIL_LEN                               ;#1753: BE 80 00
        lodsb                                                  ;#1756: AC
        mov     ah, 7Eh                                        ;#1757: B4 7E
        cmp     al, ah                                         ;#1759: 3A C4
        jbe     short PSPTAIL_AT_END                           ;#175B: 76 02
        mov     al, ah                                         ;#175D: 8A C4
PSPTAIL_AT_END:
