        push    si                                             ;#175F: 56
        cbw                                                    ;#1760: 98
        add     si, ax                                         ;#1761: 03 F0
        mov     byte [si], ASCII_CR                            ;#1763: C6 04 0D
        pop     si                                             ;#1766: 5E
CMD_TAIL_LOOP:
        ; Walk the tail: CF ends it, ZF skips a blank, otherwise run one command
        call    near SKIP_BLANKS                               ;#1767: E8 D2 FF
        jb      short STARTUP_AUTOEXEC                         ;#176A: 72 07
        jz      short CMD_TAIL_LOOP                            ;#176C: 74 F9
        call    near PARSE_STARTUP_SWITCH                      ;#176E: E8 92 FE
        jmp     short CMD_TAIL_LOOP                            ;#1771: EB F4

STARTUP_AUTOEXEC:
        ; Tail exhausted — patch the boot drive letter into AUTOEXEC_PATH
        call    near USE_ENV_HIT                               ;#1773: E8 23 FF
        push    cs                                             ;#1776: 0E
        pop     ds                                             ;#1777: 1F
        mov     ah, 19h                                        ;#1778: B4 19
        int     21h                                            ;#177A: CD 21
        add     al, "A"                                        ;#177C: 04 41
        mov     [AUTOEXEC_PATH], al                            ;#177E: A2 E3 03
        mov     ax, [HEAD_DATA_TAIL+69h]                       ;#1781: A1 00 02
        cmp     ah, 3Ah                                        ;#1784: 80 FC 3A
        jnz     short RELOCATE_TRANSIENT                       ;#1787: 75 03
        mov     [AUTOEXEC_PATH], al                            ;#1789: A2 E3 03
RELOCATE_TRANSIENT:
        ; Copy 2120h..6F8Fh up to TRANSIENT_SEG:0100h with a descending rep movsw
        ; The split between the two halves, exactly:
        ;
        ; 178D    mov     es, [TRANSIENT_SEG]
        ; mov     cx, TRANSIENT_LEN
        ; mov     si, IMAGE_LAST_WORD
        ; mov     di, IMAGE_LAST_WORD - TRANSIENT_BIAS
        ; shr     cx, 1
        ; std
        ; rep     movsw
        ;
        ; A descending word copy of 4E70h bytes, so 2120h..6F8Fh in the file lands at
        ; 0100h..4F6Fh in TRANSIENT_SEG.  6F90h - 2120h is 4E70h, the whole tail of the
        ; image, and 6F8Eh - 4F6Eh is the 2020h that every transient address is offset
        ; by.
        ;
        ; Which half is which follows from what happens next: RELOAD_TRANSIENT_IF_BAD
        ; checksums the copy with CHECKSUM_TRANSIENT and calls OPEN_COMMAND_COM to
        ; reload it from disk when the sum is wrong.  A block that gets clobbered and
        ; re-read is the TRANSIENT portion; the 8224 bytes below 2120h are the resident
        ; stub that survives.  Five labels had this backwards until #982 -- see that
        ; entry.
        push    es                                             ;#178C: 06
        mov     es, [TRANSIENT_SEG]                            ;#178D: 8E 06 52 02
        mov     cx, TRANSIENT_LEN                              ;#1791: B9 70 4E
        mov     si, IMAGE_LAST_WORD                            ;#1794: BE 8E 6F
        mov     di, IMAGE_LAST_WORD - TRANSIENT_BIAS           ;#1797: BF 6E 4F
        shr     cx, 1                                          ;#179A: D1 E9
        std                                                    ;#179C: FD
        rep     movsw                                          ;#179D: F3 A5
        cld                                                    ;#179F: FC
        pop     es                                             ;#17A0: 07
        call    near CHECKSUM_TRANSIENT                        ;#17A1: E8 EF F3
        mov     [TRANSIENT_CHECKSUM], ax                       ;#17A4: A3 54 02
        call    near INSTALL_INT_22_23_24                      ;#17A7: E8 B8 F3
        mov     si, 0Ah                                        ;#17AA: BE 0A 00
        mov     di, SAVED_INT_VECTORS                          ;#17AD: BF 56 02
        mov     cx, 7                                          ;#17B0: B9 07 00
        rep     movsw                                          ;#17B3: F3 A5
        mov     si, INT_22_23_24_VECTORS                       ;#17B5: BE 64 02
        mov     di, 0Ah                                        ;#17B8: BF 0A 00
        mov     cx, 7                                          ;#17BB: B9 07 00
        rep     movsw                                          ;#17BE: F3 A5
        cmp     byte [STARTUP_DONE], 0                         ;#17C0: 80 3E 77 02 00
        jz      short RELOC_SHRINK_BLOCK                       ;#17C5: 74 13
        mov     si, 0Ah                                        ;#17C7: BE 0A 00
        mov     di, SAVED_INT_VECTORS                          ;#17CA: BF 56 02
        mov     cx, 7                                          ;#17CD: B9 07 00
        rep     movsw                                          ;#17D0: F3 A5
        mov     dx, 1242h                                      ;#17D2: BA 42 12
        mov     ax, 252Eh                                      ;#17D5: B8 2E 25
        int     21h                                            ;#17D8: CD 21
RELOC_SHRINK_BLOCK:
        ; Give back everything above 1310h
        mov     bx, 1310h                                      ;#17DA: BB 10 13
        mov     cl, 4                                          ;#17DD: B1 04
        shr     bx, cl                                         ;#17DF: D3 EB
        mov     ah, 4Ah                                        ;#17E1: B4 4A
        int     21h                                            ;#17E3: CD 21
        cmp     byte [COMSPEC_SOURCE], 0                       ;#17E5: 80 3E 7D 14 00
        jz      short RELOC_CHECK_AUTOEXEC                     ;#17EA: 74 18
        mov     bx, 0Ah                                        ;#17EC: BB 0A 00
        mov     ah, 48h                                        ;#17EF: B4 48
        int     21h                                            ;#17F1: CD 21
        mov     si, ENV_NAME_COMSPEC_2                         ;#17F3: BE 20 13
        push    es                                             ;#17F6: 06
        mov     es, ax                                         ;#17F7: 8E C0
        xor     di, di                                         ;#17F9: 33 FF
        mov     cx, 50h                                        ;#17FB: B9 50 00
        rep     movsw                                          ;#17FE: F3 A5
        pop     es                                             ;#1800: 07
        mov     [PSP_ENV_SEG], ax                              ;#1801: A3 2C 00
RELOC_CHECK_AUTOEXEC:
        ; /D aside, is there an AUTOEXEC.BAT to open
        cmp     byte [SKIP_AUTOEXEC], 0                        ;#1804: 80 3E 7C 14 00
        jnz     short RELOC_CHECK_TAIL                         ;#1809: 75 0F
        mov     dx, AUTOEXEC_PATH                              ;#180B: BA E3 03
        call    near OPEN_FILE_READONLY                        ;#180E: E8 1D FF
        jb      short RELOC_CHECK_TAIL                         ;#1811: 72 07
        or      byte [SHELL_FLAGS], SHELL_BATCH_ACTIVE         ;#1813: 80 0E 39 03 04
        jmp     short RELOC_CHOOSE_SIGNON                      ;#1818: EB 07

RELOC_CHECK_TAIL:
        ; No batch file: a command tail suppresses the banner
        cmp     word [CMD_TAIL_PTR], 0                         ;#181A: 83 3E 89 02 00
        jnz     short RELOC_SIZE_ENVIRONMENT                   ;#181F: 75 4E
RELOC_CHOOSE_SIGNON:
        ; The sign-on screen, or three plain lines
        cmp     byte [VECTOR_INSTALL_FLAG], 0                  ;#1821: 80 3E 7B 14 00
        jz      short RELOC_PLAIN_BANNER                       ;#1826: 74 1F
        ; A far call whose target is computed rather than stored, which is why #957's
        ; reachability sweep found SIGNON_FAR_ENTRY with nothing pointing at it:
        ;
        ; 1828    mov     word [SIGNON_ENTRY_PTR], 122h
        ; mov     [SIGNON_ENTRY_PTR+2h], cs
        ; mov     ax, SIGNON_BIAS
        ; shr     ax, 1           ; x4 -- 1890h / 16 = 189h paragraphs
        ; add     [SIGNON_ENTRY_PTR+2h], ax
        ; call    far word [SIGNON_ENTRY_PTR]
        ;
        ; (CS + 189h) * 16 + 122h is CS*16 + 19B2h, so the call lands on CS:19B2h.
        ; 1890h is the sign-on block's bias, named SIGNON_BIAS in #1069, and 122h plus
        ; it is SIGNON_FAR_ENTRY -- so both halves name something after all.  It used to
        ; render as a bare literal with a [literals] entry holding it that way.  That
        ; 1890h also happens to be MONTH_NAME_TABLE's address is a coincidence.
        ;
        ; 16AF is the same idiom used honestly, and there the label IS the point:
        ;
        ; 16AF    mov     ax, ENV_NAME_COMSPEC_2
        ; mov     cl, 4
        ; shr     ax, cl
        ; mov     cx, ax
        ; mov     ax, ds
        ; add     ax, cx
        ; mov     [PSP_ENV_SEG], ax       ; PSP environment pointer
        ;
        ; [2Ch] ends up at DS:1320h, exactly where the built-in "COMSPEC=\COMMAND.COM"
        ; string sits, so a fresh child inherits an environment consisting of it.  Three
        ; things have to line up for that: 1320h is paragraph-aligned, so the four-bit
        ; shift above loses nothing; ENV_NAME_COMSPEC_2 is the eight bytes "COMSPEC=" and
        ; MSG_COMMAND_COM_PATH the twelve after it, so the two labels are one string read
        ; end to end; and the zeros that follow supply the second terminator an
        ; environment block needs.  None of that is arranged by the code -- it is where
        ; the strings were placed.
        mov     word [SIGNON_ENTRY_PTR], 122h                  ;#1828: C7 06 91 14 22 01
        mov     [SIGNON_ENTRY_PTR+2h], cs                      ;#182E: 8C 0E 93 14
        mov     ax, SIGNON_BIAS                                ;#1832: B8 90 18
        shr     ax, 1                                          ;#1835: D1 E8
        shr     ax, 1                                          ;#1837: D1 E8
        shr     ax, 1                                          ;#1839: D1 E8
        shr     ax, 1                                          ;#183B: D1 E8
        add     [SIGNON_ENTRY_PTR+2h], ax                      ;#183D: 01 06 93 14
        call    far word [SIGNON_ENTRY_PTR]                    ;#1841: FF 1E 91 14
        jmp     short RELOC_SIZE_ENVIRONMENT                   ;#1845: EB 28

RELOC_PLAIN_BANNER:
        ; Copyright, version, and the command version
        mov     ah, 40h                                        ;#1847: B4 40
        mov     bx, 1                                          ;#1849: BB 01 00
        mov     dx, MSG_STUB_CRLF                              ;#184C: BA 82 18
        mov     cx, 1                                          ;#184F: B9 01 00
        int     21h                                            ;#1852: CD 21
        mov     dx, SYSMSG_OS_DIREITOS_DE_PROPRIEDADE_DO_      ;#1854: BA 25 14
        call    near PRINT_COMPRESSED_MSG                      ;#1857: E8 13 F6
        call    near STUB_PRINT_CRLF                           ;#185A: E8 1D 00
        mov     dx, MSG_SISNE_PLUS                             ;#185D: BA 26 0B
        call    near STUB_PRINT_DOLLAR                         ;#1860: E8 1A 00
        call    near STUB_PRINT_CRLF                           ;#1863: E8 14 00
        mov     dx, MSG_COMMAND_VERSION                        ;#1866: BA 48 0B
        call    near STUB_PRINT_DOLLAR                         ;#1869: E8 11 00
        call    near STUB_PRINT_CRLF                           ;#186C: E8 0B 00
