        mov     cx, [ENV_USED_LEN]                             ;#1873: 8B 0E 82 14
        jmp     near RESIZE_ENV_BLOCK                          ;#1877: E9 69 FA

STUB_PRINT_CRLF:
        ; AH=9 on MSG_STUB_CRLF
        mov     dx, MSG_STUB_CRLF                              ;#187A: BA 82 18
STUB_PRINT_DOLLAR:
        ; AH=9 on whatever DX already points at
        mov     ah, 9                                          ;#187D: B4 09
        int     21h                                            ;#187F: CD 21
        ret                                                    ;#1881: C3

MSG_STUB_CRLF:
