        db      11 dup (0)
        db      "JAN"                                          ;#1890: 4A 41 4E
        db      "FEV"                                          ;#1893: 46 45 56
        db      "MAR"                                          ;#1896: 4D 41 52
        db      "ABR"                                          ;#1899: 41 42 52
        db      "MAI"                                          ;#189C: 4D 41 49
        db      "JUN"                                          ;#189F: 4A 55 4E
        db      "JUL"                                          ;#18A2: 4A 55 4C
        db      "AGO"                                          ;#18A5: 41 47 4F
        db      "SET"                                          ;#18A8: 53 45 54
        db      "OUT"                                          ;#18AB: 4F 55 54
        db      "NOV"                                          ;#18AE: 4E 4F 56
        db      "DEZ"                                          ;#18B1: 44 45 5A
        db      "DOMINGO"                                      ;#18B4: 44 4F 4D 49 4E 47 4F
        db      "SEGUNDA"                                      ;#18BB: 53 45 47 55 4E 44 41
        db      " TERÇA "                                      ;#18C2: 20 54 45 52 80 41 20
        db      "QUARTA "                                      ;#18C9: 51 55 41 52 54 41 20
        db      "QUINTA "                                      ;#18D0: 51 55 49 4E 54 41 20
        db      " SEXTA "                                      ;#18D7: 20 53 45 58 54 41 20
        db      "SABADO "                                      ;#18DE: 53 41 42 41 44 4F 20

BIOS_CURSOR_ROW_21:
        ; DH=15h then BIOS_SET_CURSOR
        mov     dh, 15h                                        ;#18E5: B6 15
BIOS_SET_CURSOR:
        ; INT 10h AH=2 with BH=0, row and column already in DX
        mov     ah, 2                                          ;#18E7: B4 02
        mov     bh, 0                                          ;#18E9: B7 00
        int     10h                                            ;#18EB: CD 10
        ret                                                    ;#18ED: C3

BIOS_PRINT_DECIMAL:
        ; Two decimal digits via INT 10h AH=0Eh — init-time output, before DOS handles
        mov     si, ax                                         ;#18EE: 8B F0
        call    near BIOS_CURSOR_ROW_21                        ;#18F0: E8 F2 FF
        mov     ax, si                                         ;#18F3: 8B C6
BIOS_PRINT_2_DIGITS:
        ; div by 10 then add 3030h — the low two digits, without recursing
        cbw                                                    ;#18F5: 98
        mov     dl, 0Ah                                        ;#18F6: B2 0A
        div     dl                                             ;#18F8: F6 F2
        add     ax, 3030h                                      ;#18FA: 05 30 30
        mov     dl, ah                                         ;#18FD: 8A D4
        mov     ah, 0Eh                                        ;#18FF: B4 0E
        mov     bh, 0                                          ;#1901: B7 00
        int     10h                                            ;#1903: CD 10
        mov     ah, 0Eh                                        ;#1905: B4 0E
        mov     al, dl                                         ;#1907: 8A C2
        int     10h                                            ;#1909: CD 10
        ret                                                    ;#190B: C3

BIOS_WRITE_STRING:
        ; CX characters through INT 10h AH=0Eh
        call    near BIOS_CURSOR_ROW_21                        ;#190C: E8 D6 FF
        mov     bh, 0                                          ;#190F: B7 00
BIOSWRITE_NEXT_CHAR:
        ; AH=0Eh, one character at a time
        lodsb                                                  ;#1911: AC
        mov     ah, 0Eh                                        ;#1912: B4 0E
        int     10h                                            ;#1914: CD 10
        loop    BIOSWRITE_NEXT_CHAR                            ;#1916: E2 F9
        ret                                                    ;#1918: C3

DRAW_SIGNON_SCREEN:
        ; Clear, logo, then the time, date, weekday and version banner
        ; The whole sign-on screen, and clearing it is the first three instructions.
        ; SHOW_SIGNON_LOGO paints the picture #1150 describes, and everything after that
        ; is text placed by column number:
        ;
        ; 05h  hours          31h  day
        ; 08h  minutes        34h  month name
        ; 0Bh  hundredths     38h  year
        ; 44h  weekday        20h  the version banner
        ;
        ; Nothing measures anything: BIOS_PRINT_DECIMAL takes the column in DL, so the
        ; layout is nine constants rather than a format string, and moving a field means
        ; changing one byte.
        ;
        ; The year is split rather than formatted:
        ;
        ; 1972    mov     dl, 64h
        ; div     dl
        ; mov     cl, ah
        ; mov     dl, 38h
        ; call    near BIOS_PRINT_DECIMAL
        ; mov     al, cl
        ; call    near BIOS_PRINT_2_DIGITS
        ;
        ; Dividing by 100 leaves the century in AL and the year in AH, and the two are
        ; printed by different routines -- the century by the one that takes a column,
        ; the remainder by the one that does not, because it goes immediately after.
        ;
        ; The banner length is the part worth having:
        ;
        ; 1999    cmp byte [MSG_SISNE_PLUS+BANNER_SUFFIX], "$"
        ; jz      short SIGNON_VERSION_WIDTH
        ; inc     cx
        ;
        ; Nine characters, or ten if BANNER_SUFFIX is no longer '$'.  That is #1135's
        ; spare column seen from the other end: INIT_VERSION_AND_BANNER writes a release
        ; letter over the first of the template's two '$' when AH=1808h reports one, and
        ; this is the reader that notices and takes one more character.  Neither routine
        ; mentions the other; the '$' is the whole protocol between them.
        mov     dx, 0                                          ;#1919: BA 00 00
        call    near BIOS_SET_CURSOR                           ;#191C: E8 C8 FF
        mov     cx, 0                                          ;#191F: B9 00 00
        mov     dh, 18h                                        ;#1922: B6 18
        mov     dl, 4Fh                                        ;#1924: B2 4F
        mov     ax, 600h                                       ;#1926: B8 00 06
        mov     bh, 7                                          ;#1929: B7 07
        int     10h                                            ;#192B: CD 10
        call    near SHOW_SIGNON_LOGO                          ;#192D: E8 8E 00
        mov     ah, 2Ch                                        ;#1930: B4 2C
        int     21h                                            ;#1932: CD 21
        push    dx                                             ;#1934: 52
        mov     al, ch                                         ;#1935: 8A C5
        mov     dl, 5                                          ;#1937: B2 05
        call    near BIOS_PRINT_DECIMAL                        ;#1939: E8 B2 FF
        mov     al, cl                                         ;#193C: 8A C1
        mov     dl, 8                                          ;#193E: B2 08
        call    near BIOS_PRINT_DECIMAL                        ;#1940: E8 AB FF
        pop     ax                                             ;#1943: 58
        mov     al, ah                                         ;#1944: 8A C4
        mov     dl, 0Bh                                        ;#1946: B2 0B
        call    near BIOS_PRINT_DECIMAL                        ;#1948: E8 A3 FF
        mov     ah, 2Ah                                        ;#194B: B4 2A
        int     21h                                            ;#194D: CD 21
        push    ax                                             ;#194F: 50
        push    cx                                             ;#1950: 51
        dec     dh                                             ;#1951: FE CE
        mov     bl, dh                                         ;#1953: 8A DE
        mov     al, dl                                         ;#1955: 8A C2
        mov     dl, 31h                                        ;#1957: B2 31
        call    near BIOS_PRINT_DECIMAL                        ;#1959: E8 92 FF
        mov     dh, bl                                         ;#195C: 8A F3
        shl     bl, 1                                          ;#195E: D0 E3
        add     bl, dh                                         ;#1960: 02 DE
        xor     bh, bh                                         ;#1962: 32 FF
        lea     si, [bx+0]                                     ;#1964: 8D B7 00 00
        mov     dl, 34h                                        ;#1968: B2 34
        mov     cx, 3                                          ;#196A: B9 03 00
        cld                                                    ;#196D: FC
        call    near BIOS_WRITE_STRING                         ;#196E: E8 9B FF
        pop     ax                                             ;#1971: 58
        mov     dl, 64h                                        ;#1972: B2 64
        div     dl                                             ;#1974: F6 F2
        mov     cl, ah                                         ;#1976: 8A CC
        mov     dl, 38h                                        ;#1978: B2 38
        call    near BIOS_PRINT_DECIMAL                        ;#197A: E8 71 FF
        mov     al, cl                                         ;#197D: 8A C1
        call    near BIOS_PRINT_2_DIGITS                       ;#197F: E8 73 FF
        pop     ax                                             ;#1982: 58
        ; Day names, indexed in the sign-on frame:
        ;
        ; 1983    mov     cx, 7
        ; mul     cl
        ; mov     bx, ax
        ; lea     si, [bx+DAY_NAMES_IN_SIGNON]
        ; mov     dl, 44h
        ; call    near BIOS_WRITE_STRING
        ;
        ; Seven bytes per entry and a base of 24h, which is DAY_NAME_TABLE at 18B4h read
        ; in the frame this code runs in (#1069).
        ;
        ; The instruction is 8D B7 24 00 -- `lea` with a 16-bit displacement, four bytes
        ; where three would do, since 24h fits in a byte.  That matters for naming it:
        ; the displacement has to come from a [values] EQU, because a [labels] symbol is
        ; relocatable and cannot be folded, and the override has to declare four bytes
        ; and not the three the short form would take.  #1109 got both wrong at once and
        ; concluded the operand could not be named at all.
        mov     cx, 7                                          ;#1983: B9 07 00
        mul     cl                                             ;#1986: F6 E1
        mov     bx, ax                                         ;#1988: 8B D8
        lea     si, [bx+DAY_NAMES_IN_SIGNON]                   ;#198A: 8D B7 24 00
        mov     dl, 44h                                        ;#198E: B2 44
        call    near BIOS_WRITE_STRING                         ;#1990: E8 79 FF
        push    ds                                             ;#1993: 1E
        push    ss                                             ;#1994: 16
        pop     ds                                             ;#1995: 1F
        mov     cx, 9                                          ;#1996: B9 09 00
        cmp     byte [MSG_SISNE_PLUS+BANNER_SUFFIX], "$"       ;#1999: 80 3E 3E 0B 24
        jz      short SIGNON_VERSION_WIDTH                     ;#199E: 74 01
        inc     cx                                             ;#19A0: 41
SIGNON_VERSION_WIDTH:
        ; Nine characters, or ten with the P suffix
        mov     dl, 20h                                        ;#19A1: B2 20
        mov     si, MSG_SISNE_PLUS+BANNER_DOS_MAJOR            ;#19A3: BE 35 0B
        call    near BIOS_WRITE_STRING                         ;#19A6: E8 63 FF
        pop     ds                                             ;#19A9: 1F
        mov     dh, 16h                                        ;#19AA: B6 16
        mov     dl, 0                                          ;#19AC: B2 00
        call    near BIOS_SET_CURSOR                           ;#19AE: E8 36 FF
        ret                                                    ;#19B1: C3

SIGNON_FAR_ENTRY:
        ; Far stub reached by the computed call at 1841h; clears the screen, runs the logo
        push    ds                                             ;#19B2: 1E
        push    es                                             ;#19B3: 06
        push    cs                                             ;#19B4: 0E
        pop     ds                                             ;#19B5: 1F
        push    cs                                             ;#19B6: 0E
        pop     es                                             ;#19B7: 07
        call    near DRAW_SIGNON_SCREEN                        ;#19B8: E8 5E FF
        pop     es                                             ;#19BB: 07
        pop     ds                                             ;#19BC: 1F
        retf                                                   ;#19BD: CB

SHOW_SIGNON_LOGO:
        ; RUN_SCREEN_SCRIPT on SIGNON_LOGO_SCRIPT, addressed in the biased frame
        push    ds                                             ;#19BE: 1E
        push    si                                             ;#19BF: 56
        mov     si, cs                                         ;#19C0: 8C CE
        mov     ds, si                                         ;#19C2: 8E DE
        mov     si, SIGNON_LOGO_SCRIPT - SIGNON_BIAS           ;#19C4: BE 3D 01
        call    near RUN_SCREEN_SCRIPT                         ;#19C7: E8 43 05
        pop     si                                             ;#19CA: 5E
        pop     ds                                             ;#19CB: 1F
        ret                                                    ;#19CC: C3

SIGNON_LOGO_SCRIPT:
        ; The sign-on screen: 89 (row, col, n, ops) records painting "SISNE Plus"
        ; The sign-on logo screen, painted straight into video RAM.  The leading
        ; word is the length of what follows -- 1233 bytes, 19CFh..1E9Fh, which is
        ; how the end of the script is known rather than guessed.  Then 89 records,
        ; each a row, a column, a byte count and the ops that fill it; rows 0..20,
        ; columns 0..79.
        ; Writing past column 79 wraps to column 0 of the next row, which is how the
        ; box sides are drawn: row 0 lays down a corner, 78 dashes and a corner, and
        ; the 81st cell spills over to start row 1's left border.
        ;
        ; The LOGO_ macros at the top of the listing are the encoding, and there are
        ; three op kinds:
        ;
        ; LOGO_RUN     00 n attr  c1..cn   n characters sharing one attribute
        ; LOGO_CELLS   01 n       (c,a)*n  n cells, each with its own attribute
        ; LOGO_REPEAT  FF n c attr         one cell repeated n times
        ;
        ; Each emits its own kind byte, and LOGO_RUN and LOGO_CELLS count the payload
        ; they are given, so both of the numbers the reader takes off the stream are
        ; the macro name and its arguments here rather than bytes to be matched up.
        ; The characters are written as themselves -- the frame really is drawn in
        ; the source -- which is CP437 read the way the screen reads it.
        ;
        ; RUN_SCREEN_SCRIPT at 1F0Dh is the reader, and it confirms every part of
        ; this from the other side: it loads the leading length word into [615h],
        ; takes row and column, then the record count into [617h], and dispatches on
        ; `cmp cl,1 / cmp cl,0 / cmp cl,0FFh` -- the same three kinds and no fourth.
        ; SCRIPT_NEXT_BYTE, SCRIPT_OP_REPEAT, SCRIPT_OP_RUN and SCRIPT_OP_CELLS are
        ; its pieces, and SCREEN_WRITE_RUN is what finally reaches INT 10h.
        ;
        ; Attributes are 03h, 07h and 0Bh -- cyan, light grey and bright cyan --
        ; plus 70h, black on grey, which is the status bar built into row 21.
        ;
        ; Rendering all 89 records gives an 80x22 framed screen.  Rows 4..6 carry a
        ; line of small box-drawing capitals, rows 9..13 spell SISNE in full blocks,
        ; "Plus" sits beside it on rows 14..16, and row 19 is the copyright:
        ;
        ; +--------------------------------------------------------------+
        ; | 9        ,-----.  ,-.  ,-----.  ,-----.  ,-----.              |
        ; |13        S        I    S        N        E     (full blocks)  |
        ; |16                                        Plus                 |
        ; |19    Os direitos de propriedade estao reservados a Scopus     |
        ; |          e Itautec.                                           |
        ; |21  `-  :  :  --  SISNE PLUS  --  /   /  -----------------'    |
        ; +--------------------------------------------------------------+
        ;
        ; Row 21 is the bottom border with a status bar built into it, and the
        ; blanks in `:  :` and `/   /` are placeholders the clock and date are
        ; written into later -- which is what MONTH_NAME_TABLE and DAY_NAME_TABLE
        ; next door are for.
        ;
        ; The row 19 record is col 8, 64 characters at attribute 07h, using 00 as
        ; the word separator (character 0 is a blank cell).  Those 64 bytes used to
        ; fall outside the declared block: the walk decoded 1E00h as code (`4Fh` as
        ; `dec di`, `73 00` as a `jnb`) and the bulk string pass cut the rest into
        ; six "messages" at the 00 separators.  See #952.
        ; Format: FORMAT_LOGO_SCRIPT
        ; - A record header and an op are told apart by their first two bytes, which
        ; - the table itself keeps distinct: an op begins 00, 01 or 0FFh, and a header
        ; - begins with its row, so every row from 2 up is a header by its first byte
        ; - alone.  Rows 0 and 1 are the two that collide, and their columns settle it
        ; - -- no op counts 0 cells or 79 of them.  Any of that being wrong moves a
        ; - byte, and the rebuild is what says so.
        ; - Cells come in ones and twos only, so there is a clause for each: rendering
        ; - a pair as one run would let a character and its attribute merge into one
        ; - string wherever the attribute is itself printable (70h is 'p', on row 20).
        ; - The copyright on row 19 is the one run too wide for a 90-column line: 64
        ; - characters, continued over three with the assembler's own backslash and cut
        ; - at the 00 word separators so each line ends on a word.
        LOGO_SIZE 1233                                         ;#19CD: D1 04
        LOGO_POS 0, 0, 14                                      ;#19CF: 00 00 0E 00
        LOGO_CELLS "┌", 3                                      ;#19D3: 01 01 DA 03
        LOGO_REPEAT 78, "─", 3                                 ;#19D7: FF 4E C4 03
        LOGO_CELLS "┐", 3, "│", 3                              ;#19DB: 01 02 BF 03 B3 03
        LOGO_POS 1, 79, 6                                      ;#19E1: 01 4F 06 00
        LOGO_CELLS "│", 3, "│", 3                              ;#19E5: 01 02 B3 03 B3 03
        LOGO_POS 2, 79, 6                                      ;#19EB: 02 4F 06 00
        LOGO_CELLS "│", 3, "│", 3                              ;#19EF: 01 02 B3 03 B3 03
