SCRIPT_NEXT_BYTE:
        ; Next script byte, counted off SCRIPT_BYTES_LEFT and nothing else
        mov     al, [si]                                       ;#1EAB: 8A 04
        inc     si                                             ;#1EAD: 46
        dec     word [SCRIPT_BYTES_LEFT]                       ;#1EAE: FF 0E 15 06
        ret                                                    ;#1EB2: C3

SCREEN_WRITE_RUN:
        ; Cursor from [612h]/[613h]/[614h], INT 10h AH=9 the run, then advance the column
        push    ax                                             ;#1EB3: 50
        push    bx                                             ;#1EB4: 53
        push    cx                                             ;#1EB5: 51
        mov     bh, [SCREEN_PAGE]                              ;#1EB6: 8A 3E 12 06
        mov     dh, [SCRIPT_ROW]                               ;#1EBA: 8A 36 13 06
        mov     dl, [SCRIPT_COL]                               ;#1EBE: 8A 16 14 06
        mov     ah, 2                                          ;#1EC2: B4 02
        int     10h                                            ;#1EC4: CD 10
        pop     cx                                             ;#1EC6: 59
        pop     bx                                             ;#1EC7: 5B
        pop     ax                                             ;#1EC8: 58
        mov     bh, [SCREEN_PAGE]                              ;#1EC9: 8A 3E 12 06
        mov     ah, 9                                          ;#1ECD: B4 09
        int     10h                                            ;#1ECF: CD 10
        xor     ah, ah                                         ;#1ED1: 32 E4
        mov     al, [SCRIPT_COL]                               ;#1ED3: A0 14 06
        add     ax, cx                                         ;#1ED6: 03 C1
        xor     dh, dh                                         ;#1ED8: 32 F6
        mov     dl, [SCREEN_LAST_COL]                          ;#1EDA: 8A 16 1A 06
        cmp     ax, dx                                         ;#1EDE: 3B C2
        jbe     short RUN_COLUMN_ONLY                          ;#1EE0: 76 27
        sub     dl, [SCRIPT_COL]                               ;#1EE2: 2A 16 14 06
        inc     dl                                             ;#1EE6: FE C2
        sub     cx, dx                                         ;#1EE8: 2B CA
        xor     dh, dh                                         ;#1EEA: 32 F6
        mov     dl, [SCREEN_LAST_COL]                          ;#1EEC: 8A 16 1A 06
        inc     dl                                             ;#1EF0: FE C2
        mov     di, dx                                         ;#1EF2: 8B FA
        mov     dl, 1                                          ;#1EF4: B2 01
RUN_COUNT_ROWS:
        ; Subtract a line's worth until it fits
        cmp     cx, di                                         ;#1EF6: 3B CF
        jb      short RUN_STORE_POSITION                       ;#1EF8: 72 06
        sub     cx, di                                         ;#1EFA: 2B CF
        inc     dl                                             ;#1EFC: FE C2
        jmp     short RUN_COUNT_ROWS                           ;#1EFE: EB F6

RUN_STORE_POSITION:
        ; Column from the remainder, row from the count
        mov     [SCRIPT_COL], cl                               ;#1F00: 88 0E 14 06
        add     [SCRIPT_ROW], dl                               ;#1F04: 00 16 13 06
        ret                                                    ;#1F08: C3

RUN_COLUMN_ONLY:
        ; The run stayed on one line
        mov     [SCRIPT_COL], al                               ;#1F09: A2 14 06
        ret                                                    ;#1F0C: C3

RUN_SCREEN_SCRIPT:
        ; Interpret a screen script at DS:SI — the reader for SIGNON_LOGO_SCRIPT
        ; A small interpreter, and the format is worth having in one place because
        ; sixteen labels each hold a piece of it.
        ;
        ; The screen is asked about first -- AH=0Fh gives the page and the column count,
        ; and mode 7 sets SCREEN_IS_MONO -- so the same script paints a mono or a colour
        ; display without carrying two copies of anything.
        ;
        ; Then a word of total length, and records until it runs out:
        ;
        ; row     1 byte
        ; col     1 byte
        ; length  2 bytes
        ; ops     until length is exhausted
        ;
        ; and each op is a byte of kind, a byte of count, and then whatever that kind
        ; needs.  Three kinds: 0FFh repeats one character and attribute COUNT times, 00
        ; takes one attribute and then COUNT characters, 01 takes COUNT (character,
        ; attribute) pairs.  Anything else gives up: 1F8Bh jumps to SCRIPT_UNKNOWN_OP,
        ; which rings the bell twice through AH=0Eh and falls into the epilogue, so the
        ; rest of the script is never drawn.  Nothing in SIGNON_LOGO_SCRIPT reaches it.
        ;
        ; Two counters run at once and only one of them is anybody's job.
        ; SCRIPT_NEXT_BYTE decrements SCRIPT_BYTES_LEFT and never touches
        ; SCRIPT_REC_LEFT, so every caller follows its own read with `dec word
        ; [SCRIPT_REC_LEFT]` -- 1F78h, 1F92h, 1F9Ch and the rest.  The length word at
        ; 1F50h is read straight from [si] instead, which is why 1F5Bh has to subtract 2
        ; from BYTES_LEFT by hand.  A byte read without its matching decrement would not
        ; break the build or the picture, only the record boundary, and the file has no
        ; way to notice.
        ;
        ; The exit sets the border.  A colour screen gets AH=0Bh with the byte that
        ; follows the script; a mono one skips it, which is the only thing SCREEN_IS_MONO
        ; decides after the run is over.
        push    ax                                             ;#1F0D: 50
        push    bx                                             ;#1F0E: 53
        push    cx                                             ;#1F0F: 51
        push    dx                                             ;#1F10: 52
        push    bp                                             ;#1F11: 55
        push    di                                             ;#1F12: 57
        push    es                                             ;#1F13: 06
        pushf                                                  ;#1F14: 9C
        mov     byte [SCREEN_IS_MONO], 0                       ;#1F15: C6 06 11 06 00
        mov     ah, 0Fh                                        ;#1F1A: B4 0F
        int     10h                                            ;#1F1C: CD 10
        mov     [SCREEN_PAGE], bh                              ;#1F1E: 88 3E 12 06
        dec     ah                                             ;#1F22: FE CC
        mov     [SCREEN_LAST_COL], ah                          ;#1F24: 88 26 1A 06
        cmp     al, 7                                          ;#1F28: 3C 07
        jnz     short SCRIPT_TAKE_LENGTH                       ;#1F2A: 75 05
        mov     byte [SCREEN_IS_MONO], 1                       ;#1F2C: C6 06 11 06 01
SCRIPT_TAKE_LENGTH:
        ; Mode settled; the byte count comes next
        mov     ax, [si]                                       ;#1F31: 8B 04
        add     si, 2                                          ;#1F33: 83 C6 02
        mov     [SCRIPT_BYTES_LEFT], ax                        ;#1F36: A3 15 06
SCRIPT_CHECK_COUNT:
        ; SCRIPT_REC_LEFT zero ends the script; otherwise read the next op
        mov     ax, [SCRIPT_BYTES_LEFT]                        ;#1F39: A1 15 06
        cmp     ax, 0                                          ;#1F3C: 3D 00 00
        jnz     short SCRIPT_TAKE_POSITION                     ;#1F3F: 75 03
        jmp     near SCRIPT_SET_BORDER                         ;#1F41: E9 C2 00

SCRIPT_TAKE_POSITION:
        ; Row and column for this record
        call    near SCRIPT_NEXT_BYTE                          ;#1F44: E8 64 FF
        mov     [SCRIPT_ROW], al                               ;#1F47: A2 13 06
        call    near SCRIPT_NEXT_BYTE                          ;#1F4A: E8 5E FF
        mov     [SCRIPT_COL], al                               ;#1F4D: A2 14 06
        mov     ax, [si]                                       ;#1F50: 8B 04
        mov     [SCRIPT_REC_LEFT], ax                          ;#1F52: A3 17 06
        add     si, 2                                          ;#1F55: 83 C6 02
        mov     ax, [SCRIPT_BYTES_LEFT]                        ;#1F58: A1 15 06
        sub     ax, 2                                          ;#1F5B: 2D 02 00
        mov     [SCRIPT_BYTES_LEFT], ax                        ;#1F5E: A3 15 06
SCRIPT_NEXT_RECORD:
        ; Where all three op handlers rejoin to take the next record
        mov     ax, [SCRIPT_REC_LEFT]                          ;#1F61: A1 17 06
        cmp     ax, 0                                          ;#1F64: 3D 00 00
        jz      short SCRIPT_CHECK_COUNT                       ;#1F67: 74 D0
        call    near SCRIPT_NEXT_BYTE                          ;#1F69: E8 3F FF
        mov     cl, al                                         ;#1F6C: 8A C8
        dec     word [SCRIPT_REC_LEFT]                         ;#1F6E: FF 0E 17 06
        call    near SCRIPT_NEXT_BYTE                          ;#1F72: E8 36 FF
        mov     [SCRIPT_OP_COUNT], al                          ;#1F75: A2 19 06
        dec     word [SCRIPT_REC_LEFT]                         ;#1F78: FF 0E 17 06
        cmp     cl, 1                                          ;#1F7C: 80 F9 01
        jz      short SCRIPT_OP_CELLS                          ;#1F7F: 74 4D
        cmp     cl, 0                                          ;#1F81: 80 F9 00
        jz      short SCRIPT_OP_RUN                            ;#1F84: 74 25
        cmp     cl, 0FFh                                       ;#1F86: 80 F9 FF
        jz      short SCRIPT_OP_REPEAT                         ;#1F89: 74 03
        jmp     short SCRIPT_UNKNOWN_OP                        ;#1F8B: EB 66
        nop                                                    ;#1F8D: 90

SCRIPT_OP_REPEAT:
        ; Op 0FFh — read char and attribute, repeat [619h] times
        call    near SCRIPT_NEXT_BYTE                          ;#1F8E: E8 1A FF
        push    ax                                             ;#1F91: 50
        dec     word [SCRIPT_REC_LEFT]                         ;#1F92: FF 0E 17 06
        call    near SCRIPT_NEXT_BYTE                          ;#1F96: E8 12 FF
        mov     bl, al                                         ;#1F99: 8A D8
        pop     ax                                             ;#1F9B: 58
        dec     word [SCRIPT_REC_LEFT]                         ;#1F9C: FF 0E 17 06
        xor     cx, cx                                         ;#1FA0: 33 C9
        mov     cl, [SCRIPT_OP_COUNT]                          ;#1FA2: 8A 0E 19 06
        call    near SCREEN_WRITE_RUN                          ;#1FA6: E8 0A FF
        jmp     short SCRIPT_NEXT_RECORD                       ;#1FA9: EB B6

SCRIPT_OP_RUN:
        ; Op 00 — one attribute, then [619h] characters
        call    near SCRIPT_NEXT_BYTE                          ;#1FAB: E8 FD FE
        dec     word [SCRIPT_REC_LEFT]                         ;#1FAE: FF 0E 17 06
        mov     bl, al                                         ;#1FB2: 8A D8
RUN_NEXT_CELL:
        ; One cell of the run, while the count lasts
        mov     al, [SCRIPT_OP_COUNT]                          ;#1FB4: A0 19 06
        cmp     al, 0                                          ;#1FB7: 3C 00
        jz      short SCRIPT_NEXT_RECORD                       ;#1FB9: 74 A6
        call    near SCRIPT_NEXT_BYTE                          ;#1FBB: E8 ED FE
        dec     word [SCRIPT_REC_LEFT]                         ;#1FBE: FF 0E 17 06
        dec     byte [SCRIPT_OP_COUNT]                         ;#1FC2: FE 0E 19 06
        mov     cx, 1                                          ;#1FC6: B9 01 00
        call    near SCREEN_WRITE_RUN                          ;#1FC9: E8 E7 FE
        jmp     short RUN_NEXT_CELL                            ;#1FCC: EB E6

SCRIPT_OP_CELLS:
        ; Op 01 — [619h] (char, attribute) pairs
        mov     al, [SCRIPT_OP_COUNT]                          ;#1FCE: A0 19 06
        cmp     al, 0                                          ;#1FD1: 3C 00
        jz      short SCRIPT_NEXT_RECORD                       ;#1FD3: 74 8C
        call    near SCRIPT_NEXT_BYTE                          ;#1FD5: E8 D3 FE
        push    ax                                             ;#1FD8: 50
        dec     word [SCRIPT_REC_LEFT]                         ;#1FD9: FF 0E 17 06
        call    near SCRIPT_NEXT_BYTE                          ;#1FDD: E8 CB FE
        mov     bl, al                                         ;#1FE0: 8A D8
        pop     ax                                             ;#1FE2: 58
        dec     word [SCRIPT_REC_LEFT]                         ;#1FE3: FF 0E 17 06
        dec     byte [SCRIPT_OP_COUNT]                         ;#1FE7: FE 0E 19 06
        mov     cx, 1                                          ;#1FEB: B9 01 00
        call    near SCREEN_WRITE_RUN                          ;#1FEE: E8 C2 FE
        jmp     short SCRIPT_OP_CELLS                          ;#1FF1: EB DB

SCRIPT_UNKNOWN_OP:
        ; Two bells through AH=0Eh, then the script is abandoned
        mov     bh, [SCREEN_PAGE]                              ;#1FF3: 8A 3E 12 06
        mov     al, ASCII_BEL                                  ;#1FF7: B0 07
        mov     ah, 0Eh                                        ;#1FF9: B4 0E
        push    bx                                             ;#1FFB: 53
        push    ax                                             ;#1FFC: 50
        int     10h                                            ;#1FFD: CD 10
        pop     ax                                             ;#1FFF: 58
        pop     bx                                             ;#2000: 5B
        int     10h                                            ;#2001: CD 10
        jmp     short BORDER_RESTORE                           ;#2003: EB 10
        nop                                                    ;#2005: 90

SCRIPT_SET_BORDER:
        ; The exit: AH=0Bh with the trailing colour byte, on colour only
        cmp     byte [SCREEN_IS_MONO], 1                       ;#2006: 80 3E 11 06 01
        jz      short BORDER_RESTORE                           ;#200B: 74 08
        mov     bl, [si]                                       ;#200D: 8A 1C
        xor     bh, bh                                         ;#200F: 32 FF
        mov     ah, 0Bh                                        ;#2011: B4 0B
        int     10h                                            ;#2013: CD 10
BORDER_RESTORE:
        ; Flags and the four registers back
        popf                                                   ;#2015: 9D
        pop     es                                             ;#2016: 07
        pop     di                                             ;#2017: 5F
        pop     bp                                             ;#2018: 5D
        pop     dx                                             ;#2019: 5A
        pop     cx                                             ;#201A: 59
        pop     bx                                             ;#201B: 5B
        pop     ax                                             ;#201C: 58
        ret                                                    ;#201D: C3

