CGA_TO_ANSI_COLOUR:
        ; CGA colour -> ANSI digit: "04261537", all eight agree
        ; CLS is where the ANSI strings around 255Ch are used, and it prints them in
        ; pieces rather than patching anything.  The 24h bytes inside them are AH=9
        ; terminators, not slots:
        ;
        ; 5197    mov     dx, ANSI_ATTR_NORMAL - TRANSIENT_BIAS   ; attributes off
        ; 519E    test    word [CLS_OPTION_FLAGS], SWITCH_L  ; /L
        ; 51A6    mov     dx, ANSI_ATTR_BOLD - TRANSIENT_BIAS     ; bold
        ; 51AD    test    word [CLS_OPTION_FLAGS], SWITCH_P  ; /P
        ; 51B5    mov     dx, ANSI_ATTR_BLINK - TRANSIENT_BIAS    ; blink
        ; 51BC    mov     dx, ANSI_FG_PREFIX - TRANSIENT_BIAS     ; ESC "[3"
        ; 51C5    mov     bl, [CLS_FG_COLOUR]
        ; 51C9    mov     dl, [bx+CGA_TABLE_IN_TRANSIENT]   ; the digit, via AH=2
        ; 51D1    mov     dx, ANSI_BG_PREFIX - TRANSIENT_BIAS     ; ";4"
        ; 51D8    mov     bl, [CLS_BG_COLOUR]
        ; 51E4    mov     dx, ANSI_COLOUR_END - TRANSIENT_BIAS    ; "m"
        ; 51EB    mov     dx, ANSI_CLEAR_SCREEN - TRANSIENT_BIAS   ; clear
        ;
        ; So SISNE's CLS takes a foreground and a background colour (defaults 7 and 0)
        ; plus /L and /P, and emits one SGR sequence followed by a clear.
        ;
        ; The table at 534h -- 2554h in the file -- is the translation this needs,
        ; because CGA colour numbers and ANSI colour numbers disagree:
        ;
        ; CGA  0 black  1 blue  2 green  3 cyan  4 red  5 magenta  6 brown  7 grey
        ; ANSI 0 black  4 blue  2 green  6 cyan  1 red  5 magenta  3 yellow 7 white
        ;
        ; "04261537" is exactly that mapping, and all eight entries agree, so this is
        ; not a guess about eight bytes that happen to be digits.  #956 read the 24h
        ; bytes as "digit slots patched before use" and that was wrong -- nothing
        ; writes to them.
        ; Format: FORMAT_STRING
        db      "04261537"                                     ;#2554: 30 34 32 36 31 35 33 37

ANSI_CLEAR_SCREEN:
        ; ESC "[2J$" — clear the screen
        ; Format: FORMAT_STRING
        db      1Bh, "[2J$"                                    ;#255C: 1B 5B 32 4A 24

ANSI_FG_PREFIX:
        ; ESC "[3" then a $ terminator — AH=9 prints just this much
        ; Format: FORMAT_STRING
        db      1Bh, "[3$"                                     ;#2561: 1B 5B 33 24

ANSI_BG_PREFIX:
        ; ";4" — printed after the foreground digit
        ; Format: FORMAT_STRING
        db      ";4$"                                          ;#2565: 3B 34 24

ANSI_COLOUR_END:
        ; "m" — closes the SGR sequence
        ; Format: FORMAT_STRING
        db      "m$"                                           ;#2568: 6D 24

ANSI_ATTR_NORMAL:
        ; ESC "[0m$" — all attributes off
        ; Format: FORMAT_STRING
        db      1Bh, "[0m$"                                    ;#256A: 1B 5B 30 6D 24

ANSI_ATTR_BOLD:
        ; ESC "[1m$" — bright
        ; Format: FORMAT_STRING
        db      1Bh, "[1m$"                                    ;#256F: 1B 5B 31 6D 24

ANSI_ATTR_BLINK:
        ; ESC "[5m$" — blink
        ; Format: FORMAT_STRING
        db      1Bh, "[5m$"                                    ;#2574: 1B 5B 35 6D 24

