        mov     bx, cs                                         ;#3088: 8C CB
        sub     bx, ax                                         ;#308A: 2B D8
        mov     [es:TRANSIENT_BLOCK_PARAS], bx                 ;#308C: 26 89 1E 74 02
        mov     bx, ax                                         ;#3091: 8B D8
        ret                                                    ;#3093: C3

CHECK_CONTEXT_ROOM:
