        mov     ds, [cs:LOW_COPY_SEG]                          ;#30A7: 2E 8E 1E 60 46
        cmp     bx, [TRANSIENT_BLOCK_PARAS]                    ;#30AC: 3B 1E 74 02
        cmc                                                    ;#30B0: F5
        jb      short SAVECHECKED_ALLOCATE                     ;#30B1: 72 34
        mov     ah, 48h                                        ;#30B3: B4 48
        int     21h                                            ;#30B5: CD 21
        jb      short SAVECHECKED_ALLOCATE                     ;#30B7: 72 2E
        mov     es, ax                                         ;#30B9: 8E C0
