LOOKUP_NAME_TABLE:
        ; ES:DI a (len, name, word) table, DS:SI the candidate; word in CX
        ; The reader for every (len, text, word) table in the image.  Six call sites pass
        ; five tables: INTERNAL_COMMAND_TABLE at 4287h, PROMPT_CHAR_TABLE at 3AC7h,
        ; IF_KEYWORD_TABLE at 5940h, ON_OFF_TABLE at 4E60h, and EXTENSION_TABLE from both
        ; 42D7h and 43A2h.
        ;
        ; 314A    mov     cl, [es:di]     ; length byte
        ; inc     di
        ; jcxz    TABLE_RETURN           ; 0 terminates the table
        ; lodsb
        ; call    near UPCASE_AL
        ; inc     di
        ; cmp     al, [es:di-1]
        ; loope   TABLE_COMPARE_CHAR
        ; lahf
        ; add     di, cx          ; mismatch -- skip the rest of the name
        ; mov     cx, [es:di]     ; ...and pick up the record's word
        ; inc     di
        ; inc     di
        ; sahf
        ; jnz     short TABLE_NEXT_ENTRY     ; next record
        ;
        ; 5940h passes IF_KEYWORD_TABLE + 1, stepping over the table's leading 00, and
        ; 3AC7h loads PROMPT_CHAR_TABLE less TRANSIENT_BIAS.  That is why its records
        ; begin with 01 -- a one-character name is just the shortest case of the same
        ; format, not a special layout.
        ;
        ; The two smallest tables show what the record's word is for:
        ;
        ; ON_OFF_TABLE      03 "OFF" 00 FF   02 "ON" 01 FF
        ; EXTENSION_TABLE   05 ".COM" 00 FF  05 ".EXE" 01 FF
        ; 05 ".BAT" 02 FF  02 "." FF 00
        ;
        ; (each name NUL-terminated inside its own length).  So CL comes back
        ; holding the index and CH the 0FFh filler, which is why #1039 found
        ; BEST_EXT_INDEX compared against CL and not CX.  A bare "." maps to 0FFh, the
        ; same not-found sentinel that variable starts at.
        push    bp                                             ;#3140: 55
        push    ax                                             ;#3141: 50
        push    si                                             ;#3142: 56
        mov     bp, sp                                         ;#3143: 8B EC
TABLE_NEXT_ENTRY:
        ; Length byte, then that many characters
        mov     si, [bp]                                       ;#3145: 8B 76 00
        xor     ch, ch                                         ;#3148: 32 ED
        mov     cl, [es:di]                                    ;#314A: 26 8A 0D
        inc     di                                             ;#314D: 47
        jcxz    TABLE_RETURN                                   ;#314E: E3 16
TABLE_COMPARE_CHAR:
        ; Upcased, and `loope` stops on the first miss
        lodsb                                                  ;#3150: AC
        call    near UPCASE_AL                                 ;#3151: E8 AC FD
        inc     di                                             ;#3154: 47
        cmp     al, [es:di-1]                                  ;#3155: 26 3A 45 FF
        loope   TABLE_COMPARE_CHAR                             ;#3159: E1 F5
        lahf                                                   ;#315B: 9F
        add     di, cx                                         ;#315C: 03 F9
        mov     cx, [es:di]                                    ;#315E: 26 8B 0D
        inc     di                                             ;#3161: 47
        inc     di                                             ;#3162: 47
        sahf                                                   ;#3163: 9E
        jnz     short TABLE_NEXT_ENTRY                         ;#3164: 75 DF
TABLE_RETURN:
        ; CX holds the entry's value, or the scan ran out
        pop     ax                                             ;#3166: 58
        pop     ax                                             ;#3167: 58
        pop     bp                                             ;#3168: 5D
        ret                                                    ;#3169: C3

COPY_MAYBE_QUOTED:
