        pop     ax                                             ;#31A2: 58
        ret                                                    ;#31A3: C3

PARSE_SWITCHES:
        ; Parse switch letters; AX is the mask of accepted ones, result in AX
        ; The switch parser returns two answers and neither is in a register.  It builds
        ; a stack frame and writes the flags it wants the caller to see:
        ;
        ; 31A9    xor     ax, ax
        ; push    ax                  ; [bp+2] -- the accumulated mask
        ; pushf                       ; [bp]   -- the flags to return
        ; mov     bp, sp
        ;
        ; [bp] is a FLAGS image, so bit 6 is ZF and bit 0 is CF.  SWITCHES_NEXT_TOKEN
        ; does `or byte [bp], 40h` and SKIP_WHITESPACE either finds a token, in which
        ; case 31B8h clears it again, or does not.  SWITCHES_MARK_BAD does
        ; `or byte [bp], 1`.  SWITCHES_RETURN pops the lot: `popf` makes both real and
        ; `pop ax` hands back the mask.
        ;
        ; So the caller reads them as ordinary flags and never knows they were composed:
        ;
        ; 44EF    call    near PARSE_SWITCHES
        ; jb      short DIRSW_BAD_PARAM
        ; jnz     short DIRSW_TOO_MANY
        ;
        ; Every command does the same two tests in the same order -- carry for a letter
        ; it refuses, zero clear for something following the switches.  The parser cannot
        ; leave the real flags alone because it calls SKIP_WHITESPACE and UPCASE_AL
        ; between deciding and returning, and either would destroy them, which is why the
        ; answer is written down before the work rather than after.
        ;
        ; The two wrappers have the same problem one level up and solve it the ordinary
        ; way.  PARSE_SWITCHES_OR_FAIL wants to fold AX into FILEOP_OPTION_FLAGS before
        ; testing carry, and `or [FILEOP_OPTION_FLAGS], ax` would clear it, so 4C1Eh
        ; brackets the fold in `pushf` and `popf`.  COPY_PARSE_SWITCHES does the same
        ; across nine instructions of mode folding, 5DB4h to 5DC7h.  Both are preserving
        ; flags the parser composed rather than any the hardware set -- the value has been
        ; hand-made and passed through three routines by the time a command branches on
        ; it.
        push    bp                                             ;#31A4: 55
        push    cx                                             ;#31A5: 51
        push    bx                                             ;#31A6: 53
        mov     bx, ax                                         ;#31A7: 8B D8
        xor     ax, ax                                         ;#31A9: 33 C0
        push    ax                                             ;#31AB: 50
        pushf                                                  ;#31AC: 9C
        mov     bp, sp                                         ;#31AD: 8B EC
SWITCHES_NEXT_TOKEN:
        ; Bit 6 says a blank came before this one
        or      byte [bp], 40h                                 ;#31AF: 80 4E 00 40
        call    near SKIP_WHITESPACE                           ;#31B3: E8 55 FD
        jz      short SWITCHES_RETURN                          ;#31B6: 74 0B
        and     byte [bp], 0BFh                                ;#31B8: 80 66 00 BF
        cmp     al, [cs:SWITCHAR_CHAR]                         ;#31BC: 2E 3A 06 62 46
        jz      short SWITCHES_HAVE_SLASH                      ;#31C1: 74 06
SWITCHES_RETURN:
        ; Flags in AX, the byte at [bp] in the caller
        popf                                                   ;#31C3: 9D
        pop     ax                                             ;#31C4: 58
        pop     bx                                             ;#31C5: 5B
        pop     cx                                             ;#31C6: 59
        pop     bp                                             ;#31C7: 5D
        ret                                                    ;#31C8: C3

SWITCHES_HAVE_SLASH:
        ; Past the switch character
        inc     si                                             ;#31C9: 46
        call    near SKIP_WHITESPACE                           ;#31CA: E8 3E FD
        jz      short SWITCHES_MARK_BAD                        ;#31CD: 74 1B
        call    near UPCASE_AL                                 ;#31CF: E8 2E FD
        inc     si                                             ;#31D2: 46
        push    di                                             ;#31D3: 57
        mov     cx, 10h                                        ;#31D4: B9 10 00
        repne   scasb                                          ;#31D7: F2 AE
        pop     di                                             ;#31D9: 5F
        jnz     short SWITCHES_MARK_BAD                        ;#31DA: 75 0E
        mov     ax, 1                                          ;#31DC: B8 01 00
        shl     ax, cl                                         ;#31DF: D3 E0
        test    ax, bx                                         ;#31E1: 85 D8
        jz      short SWITCHES_MARK_BAD                        ;#31E3: 74 05
        or      [bp+2], ax                                     ;#31E5: 09 46 02
        jmp     short SWITCHES_NEXT_TOKEN                      ;#31E8: EB C5

SWITCHES_MARK_BAD:
        ; Bit 0 records it and the scan carries on
        or      byte [bp], 1                                   ;#31EA: 80 4E 00 01
        jmp     short SWITCHES_NEXT_TOKEN                      ;#31EE: EB BF

PARSE_NO_SWITCHES:
