        xor     ax, ax                                         ;#31F0: 33 C0
PARSE_SWITCHES_AT_BP:
        ; ES:DI=CMD_SWITCH_LETTERS, DS:SI=SS:BP, then PARSE_SWITCHES; registers preserved
        push    es                                             ;#31F2: 06
        push    di                                             ;#31F3: 57
        push    ds                                             ;#31F4: 1E
        push    si                                             ;#31F5: 56
        push    cs                                             ;#31F6: 0E
        pop     es                                             ;#31F7: 07
        mov     di, CMD_SWITCH_LETTERS - TRANSIENT_BIAS        ;#31F8: BF 2D 0C
        push    ss                                             ;#31FB: 16
        pop     ds                                             ;#31FC: 1F
        mov     si, bp                                         ;#31FD: 8B F5
        call    near PARSE_SWITCHES                            ;#31FF: E8 A2 FF
        mov     bp, si                                         ;#3202: 8B EE
        pop     si                                             ;#3204: 5E
        pop     ds                                             ;#3205: 1F
        pop     di                                             ;#3206: 5F
        pop     es                                             ;#3207: 07
        ret                                                    ;#3208: C3

