        push    cx                                             ;#322C: 51
        call    near DIGIT_AT_BP                               ;#322D: E8 21 00
        jb      short DECIMALBP_RETURN                         ;#3230: 72 1C
        mov     dx, cx                                         ;#3232: 8B D1
DECIMALBP_NEXT_DIGIT:
