        call    near DIGIT_AT_BP                               ;#3235: E8 19 00
        cmc                                                    ;#3238: F5
        jnb     short DECIMALBP_RETURN                         ;#3239: 73 13
        dec     ah                                             ;#323B: FE CC
        stc                                                    ;#323D: F9
        jz      short DECIMALBP_RETURN                         ;#323E: 74 0E
        mov     bx, dx                                         ;#3240: 8B DA
        shl     dx, 1                                          ;#3242: D1 E2
        shl     dx, 1                                          ;#3244: D1 E2
        add     dx, bx                                         ;#3246: 03 D3
        shl     dx, 1                                          ;#3248: D1 E2
        add     dx, cx                                         ;#324A: 03 D1
        jmp     short DECIMALBP_NEXT_DIGIT                     ;#324C: EB E6

DECIMALBP_RETURN:
