        xchg    al, ah                                         ;#326F: 86 E0
        cmp     al, "0"                                        ;#3271: 3C 30
        jnz     short TWODIGITS_WRITE                          ;#3273: 75 02
        sub     al, bh                                         ;#3275: 2A C7
TWODIGITS_WRITE:
