        mov     bh, 0                                          ;#3277: B7 00
        stosw                                                  ;#3279: AB
        ret                                                    ;#327A: C3

PUT_DECIMAL:
        ; DI:SI as decimal into FORMAT_SCRATCH, AH wide — 8 for DIR free space
        ; Binary to decimal without a divide.  DI:SI is the 32-bit input and the answer
        ; is built as packed BCD, one bit at a time:
        ;
        ; 3281    mov     cx, 20h
        ; 3284    shl     si, 1
        ; rcl     di, 1
        ; xchg    ax, dx
        ; call    near SHIFT_BCD_WORD
        ; xchg    ax, dx
        ; xchg    ax, bx
        ; call    near SHIFT_BCD_WORD
        ; xchg    ax, bx
        ; adc     al, al
        ; daa
        ; loop    DECIMAL_SHIFT_BIT
        ;
        ; Thirty-two passes, one per bit.  Each pass shifts the input left so its top bit
        ; lands in the carry, doubles the BCD accumulator held across AX, BX and DX, and
        ; adds that carry in at the bottom with `adc al, al / daa`.  Doubling a decimal
        ; number and adding a bit is the whole of it -- `daa` after each half is what
        ; keeps the nibbles decimal, so no division ever happens.
        ;
        ; DI is the high word of the input on the way in and only becomes a destination
        ; afterwards, at 3297h, when the routine points it at FORMAT_SCRATCH itself.  A
        ; caller passing a 16-bit value writes `xor di, di` first, which is why 4732h and
        ; 476Ah look like they are clearing a pointer and are not.
        ;
        ; FORMAT_SCRATCH is 470Bh, and 470Bh is also where DIR_MAYBE_FREE_SPACE sits in
        ; the listing -- a transient routine, three thousand bytes away from anything to
        ; do with formatting.  The two are the same number in different frames: the stub
        ; runs where the listing says, the transient runs 2020h lower, so runtime 470Bh
        ; is listing 672Bh, inside TRANSIENT_VARS.  The stub writes its digits into the
        ; transient's variable area.
        xor     al, al                                         ;#327B: 32 C0
        xor     bx, bx                                         ;#327D: 33 DB
        xor     dx, dx                                         ;#327F: 33 D2
        mov     cx, 20h                                        ;#3281: B9 20 00
DECIMAL_SHIFT_BIT:
        ; Thirty-two rounds of shift-and-subtract
        shl     si, 1                                          ;#3284: D1 E6
        rcl     di, 1                                          ;#3286: D1 D7
        xchg    ax, dx                                         ;#3288: 92
        call    near SHIFT_BCD_WORD                            ;#3289: E8 52 00
        xchg    ax, dx                                         ;#328C: 92
        xchg    ax, bx                                         ;#328D: 93
        call    near SHIFT_BCD_WORD                            ;#328E: E8 4D 00
        xchg    ax, bx                                         ;#3291: 93
        adc     al, al                                         ;#3292: 12 C0
        daa                                                    ;#3294: 27
        loop    DECIMAL_SHIFT_BIT                              ;#3295: E2 ED
        mov     di, FORMAT_SCRATCH                             ;#3297: BF 0B 47
        mov     cx, 1019h                                      ;#329A: B9 19 10
        call    near PUT_BCD_BYTE                              ;#329D: E8 21 00
        mov     al, bh                                         ;#32A0: 8A C7
        call    near PUT_BCD_BYTE                              ;#32A2: E8 1C 00
        mov     al, bl                                         ;#32A5: 8A C3
        call    near PUT_BCD_BYTE                              ;#32A7: E8 17 00
        mov     al, dh                                         ;#32AA: 8A C6
        call    near PUT_BCD_BYTE                              ;#32AC: E8 12 00
        mov     al, dl                                         ;#32AF: 8A C2
        call    near PUT_BCD_BYTE                              ;#32B1: E8 0D 00
        xor     al, al                                         ;#32B4: 32 C0
        stosb                                                  ;#32B6: AA
        xchg    al, ah                                         ;#32B7: 86 E0
        stc                                                    ;#32B9: F9
        sbb     di, ax                                         ;#32BA: 1B F8
        mov     dx, di                                         ;#32BC: 8B D7
        jmp     near PRINT_NUL_STDOUT                          ;#32BE: E9 23 07

PUT_BCD_BYTE:
