        mov     byte [es:bp+PB_DRIVE], 0FFh                    ;#3519: 26 C6 46 50 FF
        mov     word [es:bp+PB_SPACE], 4Fh                     ;#351E: 26 C7 46 64 4F 00
        xor     bx, bx                                         ;#3524: 33 DB
        call    near PB_TAKE_DRIVE                             ;#3526: E8 0D 01
        call    near PB_CHECK_ROOT                             ;#3529: E8 47 01
        mov     al, [si]                                       ;#352C: 8A 04
        call    near IS_NAME_TERMINATOR                        ;#352E: E8 E7 F9
        jnb     short TAKE_PATH_COMPONENT_NO_SLASH             ;#3531: 73 61
        mov     [es:bp+PB_MARK], di                            ;#3533: 26 89 7E 60
        mov     [es:bp+PB_CUR], di                             ;#3537: 26 89 7E 62
FINISH_PATH_BLOCK:
        ; Terminate the built path and record its end in the PB
        ; PB_FLAGS is what the caller asks for; BH and BL are what the block answers
        ; with, and they have never been written down in one place.  Every bit below is
        ; a measurement -- where it is set, where it is read -- taken from the whole
        ; listing rather than from any one routine.
        ;
        ; BH is what went wrong, and four of its bits leave the path builder:
        ;
        ; bit 0   the drive is not one DOS knows      DIRSW_PATH_ERROR: unidade
        ; bit 3   the name or extension overran, or   CMD_SUPRIME, ASSIGN, via 48h
        ; a wildcard was not allowed
        ; bit 6   the directory does not exist        DIRSW_PATH_ERROR: diretorio
        ; bit 7   the path did not fit                DIRSW_PATH_ERROR: muito longo
        ;
        ; Bits 1 and 2 are read only by PB_POINT_DTA_HERE and DOTS_ALL_DONE, inside the
        ; builder; bit 5 is never touched at all.  Bit 4 is the one worth recording:
        ; 35C1h sets it, 35D1h clears it, 3610h sets it again, and nothing anywhere
        ; tests it.  The three sites are all in the colon handling, so it is a decision
        ; being written down and then not used -- the same shape as IF's /A, which the
        ; note at 5999h found admitted by the mask and never read.
        ;
        ; BL is what the path turned out to contain.  Bits 2 and 3 are the name and the
        ; extension, set together by PUT_STAR_AT_MARK and WILDNOSLASH_MARK and read in
        ; six places; bits 4, 5 and 6 are the extension's own three, set together by
        ; APPEND_DOT_MARK; bit 0 is the drive and bit 1 the appended separator.  Bit 7
        ; is PB_MARK_COLLAPSED, the only BL bit a caller reads -- CMD_SUPRIME tests it
        ; at 47E4h to decide the file was not found.
        ;
        ; `and bl, 8Ch` at PB_RETAKE_POSITIONS keeps bits 2, 3 and 7 and drops the rest,
        ; which is the same division: what the path contains survives a collapse, what
        ; the builder did along the way does not.
        mov     byte [es:di], 0                                ;#353B: 26 C6 05 00
        mov     [es:bp+PB_SAVED_AL], al                        ;#353F: 26 88 46 5C
        mov     [es:bp+PB_SAVED_SI], si                        ;#3543: 26 89 76 56
        mov     [es:bp+PB_SAVED_BL], bl                        ;#3547: 26 88 5E 5A
        or      bl, [es:bp+PB_DONE]                            ;#354B: 26 0A 5E 5B
        and     bl, 7Fh                                        ;#354F: 80 E3 7F
        call    near PB_CHECK_WILDCARD_OK                      ;#3552: E8 70 01
        call    near PB_RESOLVE_IF_ASKED                       ;#3555: E8 B9 01
        call    near PB_RECORD_END                             ;#3558: E8 5F 03
        mov     [es:bp+PB_SAVED_BH], bh                        ;#355B: 26 88 7E 5D
        mov     [es:bp+PB_DONE], bl                            ;#355F: 26 88 5E 5B
        mov     bl, [es:bp+PB_SAVED_BL]                        ;#3563: 26 8A 5E 5A
        mov     ah, [es:bp+PB_DRIVE_USED]                      ;#3567: 26 8A 66 5F
        mov     al, [es:bp+PB_SAVED_AL]                        ;#356B: 26 8A 46 5C
        mov     si, [es:bp+PB_SAVED_SI]                        ;#356F: 26 8B 76 56
        cmp     bh, 1                                          ;#3573: 80 FF 01
        cmc                                                    ;#3576: F5
        pop     dx                                             ;#3577: 5A
        pop     cx                                             ;#3578: 59
        pop     bp                                             ;#3579: 5D
        ret                                                    ;#357A: C3

TAKE_PATH_COMPONENT:
        ; One component per pass — slash, name, extension, then loop
        ; One component per pass.  Nothing calls 357Bh itself: the first pass is reached
        ; by falling in, and 35B6h and 3609h are the two ways round again, so the loop is
        ; the routine.  There is one way in from outside, and it is not here --
        ; TAKE_PATH_COMPONENT_NO_SLASH at 3594h, where 3531h joins for a component that
        ; needs no separator in front of it.
        ;
        ; A pass is a slash, then the name, then the extension, both through the one
        ; scanner SCAN_NAME_COMPONENT -- eight characters with BL bits 2 and 3, then
        ; three with bits 5 and 6.  What ends the name decides what happens next.  A '\'
        ; goes straight back to the top for another component.  A ':' is the drive case.
        ; Anything else means an extension is coming, and that is where the tidying is:
        ;
        ; 35D6    and     bh, 0FBh
        ; or      bl, 10h
        ; jcxz    PB_WRITE_DOT
        ; mov     al, [si]
        ; call    near IS_NAME_TERMINATOR
        ; jz      short PB_SCAN_EXTENSION
        ; 35E5    mov al, "."
        ; call    near PUT_BYTE_BOUNDED
        ;
        ; The '.' is written only if something follows it.  A name ending in a bare dot
        ; loses it, so "FOO." becomes "FOO" in the built path, while `jcxz` keeps the dot
        ; when the *name* was the empty one -- ".BAT" and "." still have theirs.  The
        ; extension pass then runs either way and finds nothing when there is nothing.
        ;
        ; Past three characters the extension is not truncated quietly like the name is.
        ; 3631h sets BH bit 3 and keeps consuming, so the caller can tell "the extension
        ; was too long" from "the extension was three characters", which the name half
        ; never bothers to distinguish.
        call    near APPEND_SLASH                              ;#357B: E8 46 04
        test    bl, 48h                                        ;#357E: F6 C3 48
        jnz     short PB_MOVE_EXT_FLAG                         ;#3581: 75 05
        test    bh, 8                                          ;#3583: F6 C7 08
        jz      short PB_START_COMPONENT                       ;#3586: 74 06
PB_MOVE_EXT_FLAG:
        ; Carry the 'had an extension' bit forward
        and     bh, 0F7h                                       ;#3588: 80 E7 F7
        or      bh, 2                                          ;#358B: 80 CF 02
PB_START_COMPONENT:
        ; Mark where this component begins
        and     bl, 83h                                        ;#358E: 80 E3 83
        or      bh, 4                                          ;#3591: 80 CF 04
TAKE_PATH_COMPONENT_NO_SLASH:
        ; Where 3531h enters — no slash, no bit fixing, straight to the name
        mov     [es:bp+PB_MARK], di                            ;#3594: 26 89 7E 60
        mov     dh, 4                                          ;#3598: B6 04
        mov     dl, 8                                          ;#359A: B2 08
        mov     cx, 8                                          ;#359C: B9 08 00
        call    near SCAN_NAME_COMPONENT                       ;#359F: E8 F5 03
        mov     [es:bp+PB_CUR], di                             ;#35A2: 26 89 7E 62
        jnb     short PB_AFTER_NAME                            ;#35A6: 73 07
        jcxz    PB_COMPONENT_FINISHED                          ;#35A8: E3 03
        and     bh, 0FBh                                       ;#35AA: 80 E7 FB
PB_COMPONENT_FINISHED:
        ; Nothing more to take — hand back to FINISH_PATH_BLOCK
        jmp     short FINISH_PATH_BLOCK                        ;#35AD: EB 8C

PB_AFTER_NAME:
        ; The name ended; the terminator says what follows
        inc     si                                             ;#35AF: 46
        cmp     al, "\"                                        ;#35B0: 3C 5C
        jnz     short PB_NAME_ENDED_COLON                      ;#35B2: 75 09
        jcxz    PB_EMPTY_COMPONENT                             ;#35B4: E3 02
        jmp     short TAKE_PATH_COMPONENT                      ;#35B6: EB C3

PB_EMPTY_COMPONENT:
        ; Two separators running together
        or      bh, 2                                          ;#35B8: 80 CF 02
        jmp     short TAKE_PATH_COMPONENT_NO_SLASH             ;#35BB: EB D7

PB_NAME_ENDED_COLON:
        ; A ':' after the name — the drive case
        cmp     al, ":"                                        ;#35BD: 3C 3A
        jnz     short PB_NAME_ENDED_DOT                        ;#35BF: 75 15
        or      bh, 10h                                        ;#35C1: 80 CF 10
        jcxz    PB_COMPONENT_FINISHED                          ;#35C4: E3 E7
        and     bh, 0FBh                                       ;#35C6: 80 E7 FB
        test    bl, 8                                          ;#35C9: F6 C3 08
        jnz     short PB_COMPONENT_FINISHED                    ;#35CC: 75 DF
        or      bl, 80h                                        ;#35CE: 80 CB 80
        and     bh, 0EFh                                       ;#35D1: 80 E7 EF
        jmp     short PB_COMPONENT_FINISHED                    ;#35D4: EB D7

PB_NAME_ENDED_DOT:
        ; Anything else means an extension is coming
        and     bh, 0FBh                                       ;#35D6: 80 E7 FB
        or      bl, 10h                                        ;#35D9: 80 CB 10
        jcxz    PB_WRITE_DOT                                   ;#35DC: E3 07
        mov     al, [si]                                       ;#35DE: 8A 04
        call    near IS_NAME_TERMINATOR                        ;#35E0: E8 35 F9
        jz      short PB_SCAN_EXTENSION                        ;#35E3: 74 09
PB_WRITE_DOT:
        ; Put the '.' down, something follows it
        mov     al, "."                                        ;#35E5: B0 2E
        call    near PUT_BYTE_BOUNDED                          ;#35E7: E8 DF 03
        mov     [es:bp+PB_CUR], di                             ;#35EA: 26 89 7E 62
PB_SCAN_EXTENSION:
        ; Three characters with the extension's own BL bits
        mov     dh, 20h                                        ;#35EE: B6 20
        mov     dl, 40h                                        ;#35F0: B2 40
        mov     cx, 3                                          ;#35F2: B9 03 00
        call    near SCAN_NAME_COMPONENT                       ;#35F5: E8 9F 03
        jb      short PB_COMPONENT_DONE                        ;#35F8: 72 19
        inc     si                                             ;#35FA: 46
        cmp     al, "\"                                        ;#35FB: 3C 5C
        jnz     short PB_EXT_ENDED_COLON                       ;#35FD: 75 0D
        jcxz    PB_NEXT_COMPONENT                              ;#35FF: E3 08
        test    bl, 4                                          ;#3601: F6 C3 04
        jnz     short PB_NEXT_COMPONENT                        ;#3604: 75 03
        or      bh, 2                                          ;#3606: 80 CF 02
PB_NEXT_COMPONENT:
        ; Round again for the component after this one
        jmp     near TAKE_PATH_COMPONENT                       ;#3609: E9 6F FF

PB_EXT_ENDED_COLON:
        ; A ':' after the extension
        cmp     al, ":"                                        ;#360C: 3C 3A
        jnz     short PB_EXT_OVERRUN                           ;#360E: 75 06
PB_MARK_HAD_COLON:
        ; Note the colon and finish
        or      bh, 10h                                        ;#3610: 80 CF 10
PB_COMPONENT_DONE:
        ; The component is complete
        jmp     near FINISH_PATH_BLOCK                         ;#3613: E9 25 FF

PB_EXT_OVERRUN:
        ; More characters than the extension holds
        test    bl, 24h                                        ;#3616: F6 C3 24
        jnz     short PB_MARK_TOO_LONG                         ;#3619: 75 16
        and     bl, 0EFh                                       ;#361B: 80 E3 EF
        call    near PUT_BYTE_BOUNDED                          ;#361E: E8 A8 03
PB_SWALLOW_REST:
        ; Read on without storing, to find the terminator
        mov     al, [si]                                       ;#3621: 8A 04
        call    near IS_NAME_TERMINATOR                        ;#3623: E8 F2 F8
        jb      short PB_COMPONENT_DONE                        ;#3626: 72 EB
        inc     si                                             ;#3628: 46
        cmp     al, "\"                                        ;#3629: 3C 5C
        jz      short PB_NEXT_COMPONENT                        ;#362B: 74 DC
        cmp     al, ":"                                        ;#362D: 3C 3A
        jz      short PB_MARK_HAD_COLON                        ;#362F: 74 DF
PB_MARK_TOO_LONG:
        ; BH bit 3 records the overflow, then keep swallowing
        or      bh, 8                                          ;#3631: 80 CF 08
        jmp     short PB_SWALLOW_REST                          ;#3634: EB EB

PB_TAKE_DRIVE:
        ; The argument's drive through PARSE_DRIVE_INTO_FCB, then "X:" into the path
        call    near PARSE_DRIVE_LETTER                        ;#3636: E8 65 FE
        jz      short PB_SUPPLY_DRIVE                          ;#3639: 74 20
        js      short PB_DRIVE_UNKNOWN                         ;#363B: 78 0B
        push    ax                                             ;#363D: 50
        mov     al, ah                                         ;#363E: 8A C4
        dec     al                                             ;#3640: FE C8
        call    near PARSE_DRIVE_INTO_FCB                      ;#3642: E8 A4 FC
        pop     ax                                             ;#3645: 58
        jz      short PB_DRIVE_NOTED                           ;#3646: 74 03
PB_DRIVE_UNKNOWN:
        ; Not a drive DOS knows: bit 0 of BH
        or      bh, 1                                          ;#3648: 80 CF 01
PB_DRIVE_NOTED:
        ; Bit 0 of BL says a drive was given
        or      bl, 1                                          ;#364B: 80 CB 01
PB_EMIT_DRIVE:
        ; The letter and its colon into the buffer
        call    near PUT_BYTE_BOUNDED                          ;#364E: E8 78 03
        mov     al, ":"                                        ;#3651: B0 3A
        call    near PUT_BYTE_BOUNDED                          ;#3653: E8 73 03
PB_STORE_DRIVE_USED:
        ; Which drive the block ended up on
        mov     [es:bp+PB_DRIVE_USED], ah                      ;#3656: 26 88 66 5F
        ret                                                    ;#365A: C3

PB_SUPPLY_DRIVE:
        ; PB_FLAGS bit 0: put CURRENT_DRIVE in and note it in PB_DONE
        test    byte [es:bp+PB_FLAGS], 1                       ;#365B: 26 F6 46 51 01
        jz      short PB_STORE_DRIVE_USED                      ;#3660: 74 F4
        or      byte [es:bp+PB_DONE], 1                        ;#3662: 26 80 4E 5B 01
        mov     al, [cs:CURRENT_DRIVE]                         ;#3667: 2E A0 06 47
        inc     al                                             ;#366B: FE C0
        mov     ah, al                                         ;#366D: 8A E0
        add     al, 40h                                        ;#366F: 04 40
        jmp     short PB_EMIT_DRIVE                            ;#3671: EB DB

PB_CHECK_ROOT:
        ; A leading backslash means absolute; otherwise fall to PB_SUPPLY_DIR
        mov     al, [si]                                       ;#3673: 8A 04
        call    near IS_NAME_TERMINATOR                        ;#3675: E8 A0 F8
        jb      short PB_SUPPLY_DIR                            ;#3678: 72 0D
        mov     byte [es:bp+PB_WAS_ABSOLUTE], 0FFh             ;#367A: 26 C6 46 5E FF
        cmp     al, "\"                                        ;#367F: 3C 5C
        jnz     short PB_SUPPLY_DIR                            ;#3681: 75 04
        inc     si                                             ;#3683: 46
        jmp     near APPEND_SLASH                              ;#3684: E9 3D 03

PB_SUPPLY_DIR:
        ; PB_FLAGS bit 1: append the current directory the same way
        test    byte [es:bp+PB_FLAGS], 2                       ;#3687: 26 F6 46 51 02
        jz      short PB_DIR_RETURN                            ;#368C: 74 32
        or      byte [es:bp+PB_DONE], 2                        ;#368E: 26 80 4E 5B 02
        mov     cx, [es:bp+PB_SPACE]                           ;#3693: 26 8B 4E 64
        mov     dl, [es:bp+PB_DRIVE_USED]                      ;#3697: 26 8A 56 5F
        call    near APPEND_CWD_BOUNDED                        ;#369B: E8 27 FE
        mov     [es:bp+PB_SPACE], cx                           ;#369E: 26 89 4E 64
        jb      short PB_DIR_CANNOT_HAPPEN                     ;#36A2: 72 1D
        cmp     byte [es:bp+PB_DRIVE], 0FFh                    ;#36A4: 26 80 7E 50 FF
        jnz     short PB_DIR_CANNOT_HAPPEN                     ;#36A9: 75 16
        cmp     byte [es:di-1], "\"                            ;#36AB: 26 80 7D FF 5C
        jz      short PB_DIR_RETURN                            ;#36B0: 74 0E
        mov     al, [si]                                       ;#36B2: 8A 04
        call    near IS_NAME_TERMINATOR                        ;#36B4: E8 61 F8
        jb      short PB_DIR_RETURN                            ;#36B7: 72 07
        cmp     al, ":"                                        ;#36B9: 3C 3A
        jz      short PB_DIR_RETURN                            ;#36BB: 74 03
        call    near APPEND_SLASH_NO_MARK                      ;#36BD: E8 07 03
PB_DIR_RETURN:
        ; A separator is there, or one was added
        ret                                                    ;#36C0: C3

PB_DIR_CANNOT_HAPPEN:
        ; int 0 -- the caller broke the precondition
        ; The only assertion in COMMAND.COM.  Two branches at the head of this routine
        ; lead here instead of to a message:
        ;
        ; 36A2    jb      short PB_DIR_CANNOT_HAPPEN
        ; 36A4    cmp     byte [es:bp+PB_DRIVE], 0FFh
        ; jnz     short PB_DIR_CANNOT_HAPPEN
        ;
        ; The first fires if the buffer overflowed while a directory was being supplied,
        ; the second if the block has no drive by the time one is needed.  Neither is
        ; something a user can cause; both mean the caller set the block up wrongly.
        ;
        ; `int 0` is the divide-error vector, which under DOS ends the program.  The
        ; `jmp` to itself on the next line is there for the case where a handler returns
        ; anyway -- the same belt-and-braces as RESET_HANG_FOREVER at 1228h, and the
        ; second deliberate hang in the file.  RESET_HANG_FOREVER prints first because
        ; it is a condition the machine can reach; this one prints nothing, because by
        ; the time it runs the state that would say anything useful is already wrong.
        int     0                                              ;#36C1: CD 00
PB_DIR_HANG_FOREVER:
        ; And if the handler returns, stop dead
        jmp     short PB_DIR_HANG_FOREVER                      ;#36C3: EB FE

PB_CHECK_WILDCARD_OK:
        ; PB_FLAGS bit 2 against the BL bits; sets BH bit 3 when it is not allowed
        test    byte [es:bp+PB_FLAGS], 4                       ;#36C5: 26 F6 46 51 04
        jnz     short PB_WILD_ALLOWED                          ;#36CA: 75 0E
        test    bl, 4                                          ;#36CC: F6 C3 04
        jnz     short PB_WILD_RETURN                           ;#36CF: 75 08
        test    bl, 20h                                        ;#36D1: F6 C3 20
        jz      short PB_WILD_RETURN                           ;#36D4: 74 03
        or      bh, 8                                          ;#36D6: 80 CF 08
PB_WILD_RETURN:
        ; Nothing to add
        ret                                                    ;#36D9: C3

PB_WILD_ALLOWED:
        ; The caller does want wildcards filled in
        test    bh, 80h                                        ;#36DA: F6 C7 80
        jnz     short PB_WILD_RETURN                           ;#36DD: 75 FA
        mov     ax, [es:bp+PB_MARK]                            ;#36DF: 26 8B 46 60
        cmp     ax, [es:bp+PB_CUR]                             ;#36E3: 26 3B 46 62
        jnz     short PB_WILD_HAVE_NAME                        ;#36E7: 75 0B
        call    near ENDS_AT_SEPARATOR                         ;#36E9: E8 98 02
        jz      short PB_WILD_AT_SEPARATOR                     ;#36EC: 74 03
PB_WILD_WHOLE_NAME:
        ; Nothing was typed: take the lot
        jmp     near APPEND_WILDCARD                           ;#36EE: E9 4F 01

PB_WILD_AT_SEPARATOR:
        ; A slash is already there, so just *.*
        jmp     near APPEND_WILDCARD_NO_SLASH                  ;#36F1: E9 4F 01

PB_WILD_HAVE_NAME:
        ; Something was typed after the mark
        test    bl, 34h                                        ;#36F4: F6 C3 34
        jz      short PB_WILD_WHOLE_NAME                       ;#36F7: 74 F5
        test    bl, 4                                          ;#36F9: F6 C3 04
        jnz     short PB_WILD_CHECK_EXT                        ;#36FC: 75 0B
        call    near PUT_STAR_AT_MARK                          ;#36FE: E8 92 01
        test    bl, 20h                                        ;#3701: F6 C3 20
        jnz     short PB_WILD_CHECK_EXT                        ;#3704: 75 03
        jmp     near APPEND_DOT_MARK                           ;#3706: E9 74 01

PB_WILD_CHECK_EXT:
        ; Only the extension may still be missing
        test    bl, 8                                          ;#3709: F6 C3 08
        jz      short PB_WILD_RETURN                           ;#370C: 74 CB
        jmp     near APPEND_DOT_STAR_IF_NEEDED                 ;#370E: E9 4B 01

PB_RESOLVE_IF_ASKED:
        ; PB_FLAGS bit 5: set the DTA, then settle what the path names
        ; PB_FLAGS bit 5 gates all 204 bytes of this, not just the DOS call at the top.
        ; Clear, and 3718h returns having done nothing at all:
        ;
        ; 3711    test    byte [es:bp+PB_FLAGS], 20h
        ; jnz     short PB_POINT_DTA_HERE
        ; ret
        ; 3719    push    ds
        ; push    dx
        ; push    ax
        ; push    es
        ; pop     ds
        ; lea     dx, [bp+PB_DTA]
        ; mov     ah, 1Ah
        ; int     21h
        ;
        ; Pointing DOS at the block's own DTA is twelve bytes of it.  The rest settles
        ; what the path that was just built actually names, which is the question the
        ; caller could not answer while building it.
        ;
        ; PB_FIND_ATTR does an AH=4Eh on the finished path, and the answer branches three
        ; ways.  A directory -- `test cl, 10h` -- needs a search pattern, so
        ; APPEND_WILDCARD puts a slash and a '*' on the end and moves PB_MARK to it.  A
        ; plain name may still want APPEND_DOT_STAR_IF_NEEDED.  A find that fails is not
        ; an error here: 375Ah looks at whether the last component starts with '.', and
        ; if it does the path is a relative directory reference rather than a missing
        ; file.
        ;
        ; The arm at 3796h is the interesting one.  It slides the last component down to
        ; the front of the buffer and stops at the first '.', so an extension is dropped
        ; rather than copied:
        ;
        ; 37AE    lodsb
        ; stosb
        ; or      al, al
        ; jz      short PB_RETAKE_POSITIONS
        ; cmp al, "."
        ; jnz     short PB_COPY_NAME
        ; mov     byte [es:di-1], 0
        ;
        ; Every byte it steps over is counted back into PB_SPACE, at 37A8h for the
        ; directory part and 37BEh for the discarded extension, so the block's idea of
        ; its own free room stays right after the path shrinks under it.  PB_MARK and
        ; PB_CUR are then rewritten to the new, shorter path and PB_DRIVE_USED cleared:
        ; what comes out is a bare name in a block that no longer remembers where it
        ; came from.
        test    byte [es:bp+PB_FLAGS], 20h                     ;#3711: 26 F6 46 51 20
        jnz     short PB_POINT_DTA_HERE                        ;#3716: 75 01
        ret                                                    ;#3718: C3

PB_POINT_DTA_HERE:
        ; AH=1Ah at the block's own DTA
        push    ds                                             ;#3719: 1E
        push    dx                                             ;#371A: 52
        push    ax                                             ;#371B: 50
        push    es                                             ;#371C: 06
        pop     ds                                             ;#371D: 1F
        lea     dx, [bp+PB_DTA]                                ;#371E: 8D 56 66
        mov     ah, 1Ah                                        ;#3721: B4 1A
        int     21h                                            ;#3723: CD 21
        pop     ax                                             ;#3725: 58
        pop     dx                                             ;#3726: 5A
        pop     ds                                             ;#3727: 1F
        test    bh, 83h                                        ;#3728: F6 C7 83
        jnz     short PB_MARK_NO_DIRECTORY                     ;#372B: 75 65
        test    bh, 0Ch                                        ;#372D: F6 C7 0C
        jnz     short PB_TEST_EXISTS                           ;#3730: 75 4D
        test    bl, 48h                                        ;#3732: F6 C3 48
        jnz     short PB_TEST_EXISTS                           ;#3735: 75 48
        push    di                                             ;#3737: 57
        call    near PB_FIND_ATTR                              ;#3738: E8 A2 00
        pop     di                                             ;#373B: 5F
        jb      short PB_FIND_FAILED                           ;#373C: 72 1C
        jnz     short PB_COLLAPSE_TO_NAME                      ;#373E: 75 56
        test    cl, 10h                                        ;#3740: F6 C1 10
        jz      short PB_PLAIN_NAME                            ;#3743: 74 0A
        test    byte [es:bp+PB_FLAGS], 4                       ;#3745: 26 F6 46 51 04
        jz      short PB_TAKE_AS_DIRECTORY                     ;#374A: 74 24
        jmp     near APPEND_WILDCARD                           ;#374C: E9 F1 00

PB_PLAIN_NAME:
        ; Not a directory: an extension may still be wanted
        test    byte [es:bp+PB_FLAGS], 4                       ;#374F: 26 F6 46 51 04
        jz      short PB_RESOLVE_RET                           ;#3754: 74 03
        call    near APPEND_DOT_STAR_IF_NEEDED                 ;#3756: E8 03 01
PB_RESOLVE_RET:
        ; Nothing more to do
        ret                                                    ;#3759: C3

PB_FIND_FAILED:
        ; No such name — a leading '.' means a relative directory
