        jcxz    SCAN_NAME_COMPONENT                            ;#39AE: E3 E7
        call    near UPCASE_AL                                 ;#39B0: E8 4D F5
        call    near PUT_BYTE_BOUNDED                          ;#39B3: E8 13 00
        dec     cx                                             ;#39B6: 49
        jmp     short SCAN_NAME_COMPONENT                      ;#39B7: EB DE

NAMECOMP_ENDED:
