        dec     si                                             ;#39BA: 4E
        xor     cx, cx                                         ;#39BB: 33 C9
        test    dh, bl                                         ;#39BD: 84 DE
        jz      short NAMECOMP_RETURN                          ;#39BF: 74 01
        inc     cx                                             ;#39C1: 41
NAMECOMP_RETURN:
        ; Flags as the terminator left them
        popf                                                   ;#39C2: 9D
        ret                                                    ;#39C3: C3

APPEND_SLASH:
