        or      bl, 2                                          ;#39C4: 80 CB 02
APPEND_SLASH_NO_MARK:
        ; APPEND_SLASH without setting bit 1 of BL
        mov     al, "\"                                        ;#39C7: B0 5C
PUT_BYTE_BOUNDED:
        ; stosb while the count at [es:bp+64h] lasts; BH bit 80h when it runs out
        cmp     word [es:bp+PB_SPACE], 0                       ;#39C9: 26 83 7E 64 00
        jz      short PUTBYTE_NO_ROOM                          ;#39CE: 74 06
        stosb                                                  ;#39D0: AA
        dec     word [es:bp+PB_SPACE]                          ;#39D1: 26 FF 4E 64
        ret                                                    ;#39D5: C3

PUTBYTE_NO_ROOM:
        ; Bit 7 of BH records the overflow
        or      bh, 80h                                        ;#39D6: 80 CF 80
        ret                                                    ;#39D9: C3

PRINT_NUL_STDOUT_RAW:
        ; PRINT_NUL_STDOUT with carry clear — no BRASCII bracketing
        ; Six entry points and two shared tails.  Each entry presets AL to the terminator
        ; and BX to the handle, and the last of each group falls through instead of
        ; jumping -- 39EEh into PRINT_WITH_BX1, 39FDh into the stderr tail at 3A00h -- so
        ; the two most common forms cost no jump at all:
        ;
        ; 39DA  al=00h  bx=1  clc      39EE  al=24h  bx=1
        ; 39E4  al=00h  bx=1  stc      39F8  al=00h  bx=2
        ; 39E9  al=0Dh  bx=1           39FD  al=24h  bx=2
        ;
        ; The terminator is a parameter rather than a format.  PRINT_STRING_COMMON finds
        ; the length with `repne scasb` on whatever AL holds, so NUL, CR and '$' strings
        ; share one length calculation and the family differs only in what it puts in two
        ; registers.
        ;
        ; Carry is the other parameter, and it is the only thing between 39DAh and 39E4h
        ; -- same AL, same BX, `clc` against `stc`.  Set, the write is bracketed:
        ;
        ; 3A1B    mov     ax, 180Dh
        ; int     21h
        ; mov     ah, 40h
        ; int     21h
        ; pushf
        ; push    ax
        ; mov     ax, 180Eh
        ; int     21h
        ;
        ; 180Dh and 180Eh are the BRASCII driver calls, so five of the six entries
        ; translate on the way out and one deliberately does not.  The flags and AX are
        ; pushed around the closing call so it cannot disturb what the write returned.
        ;
        ; That bracketing is why the accented Portuguese comes out right: the driver is
        ; switched on around each message write and off again afterwards, on a machine
        ; whose plain code page would not render it.
        ;
        ; That return is then checked at 3A35h: the length written against the length
        ; asked for, with a short write treated as a failure even though DOS reported
        ; success.
        push    ax                                             ;#39DA: 50
        mov     al, 0                                          ;#39DB: B0 00
        push    bx                                             ;#39DD: 53
        mov     bx, 1                                          ;#39DE: BB 01 00
        clc                                                    ;#39E1: F8
        jmp     short PRINT_STRING_COMMON                      ;#39E2: EB 21

PRINT_NUL_STDOUT:
        ; AL=0, BX=1 — print a NUL-terminated string to stdout
        push    ax                                             ;#39E4: 50
        mov     al, 0                                          ;#39E5: B0 00
        jmp     short PRINT_WITH_BX1                           ;#39E7: EB 08

PRINT_CR_STDOUT:
        ; AL=0Dh, BX=1 — CR-terminated
        push    ax                                             ;#39E9: 50
        mov     al, ASCII_CR                                   ;#39EA: B0 0D
        jmp     short PRINT_WITH_BX1                           ;#39EC: EB 03

PRINT_DOLLAR_STDOUT:
        ; AL=24h, BX=1 — the usual "$"-terminated form
        push    ax                                             ;#39EE: 50
        mov     al, "$"                                        ;#39EF: B0 24
PRINT_WITH_BX1:
        ; Handle 1 and carry set, then PRINT_STRING_COMMON
        push    bx                                             ;#39F1: 53
        mov     bx, 1                                          ;#39F2: BB 01 00
        stc                                                    ;#39F5: F9
        jmp     short PRINT_STRING_COMMON                      ;#39F6: EB 0D

PRINT_NUL_STDERR:
        ; AL=0, BX=2
        push    ax                                             ;#39F8: 50
        mov     al, 0                                          ;#39F9: B0 00
        jmp     short STDERR_WRITE                             ;#39FB: EB 03

PRINT_DOLLAR_STDERR:
        ; AL=24h, BX=2 — the stderr twin of PRINT_DOLLAR_STDOUT
        push    ax                                             ;#39FD: 50
        mov     al, "$"                                        ;#39FE: B0 24
STDERR_WRITE:
        ; Handle 2, with AL saying which terminator
        push    bx                                             ;#3A00: 53
        mov     bx, 2                                          ;#3A01: BB 02 00
        stc                                                    ;#3A04: F9
PRINT_STRING_COMMON:
        ; AL=terminator, BX=handle, DX=offset; carry brackets the write in BRASCII
        push    cx                                             ;#3A05: 51
        push    dx                                             ;#3A06: 52
        push    es                                             ;#3A07: 06
        push    di                                             ;#3A08: 57
        pushf                                                  ;#3A09: 9C
        push    ds                                             ;#3A0A: 1E
        pop     es                                             ;#3A0B: 07
        mov     di, dx                                         ;#3A0C: 8B FA
        mov     cx, 0FFFFh                                     ;#3A0E: B9 FF FF
        repne   scasb                                          ;#3A11: F2 AE
        neg     cx                                             ;#3A13: F7 D9
        sub     cx, 2                                          ;#3A15: 83 E9 02
        popf                                                   ;#3A18: 9D
        jnb     short PRINT_WRITE_PLAIN                        ;#3A19: 73 14
        mov     ax, 180Dh                                      ;#3A1B: B8 0D 18
        int     21h                                            ;#3A1E: CD 21
        mov     ah, 40h                                        ;#3A20: B4 40
        int     21h                                            ;#3A22: CD 21
        pushf                                                  ;#3A24: 9C
        push    ax                                             ;#3A25: 50
        mov     ax, 180Eh                                      ;#3A26: B8 0E 18
        int     21h                                            ;#3A29: CD 21
        pop     ax                                             ;#3A2B: 58
        popf                                                   ;#3A2C: 9D
        jmp     short PRINT_CHECK_WRITE                        ;#3A2D: EB 04

PRINT_WRITE_PLAIN:
        ; No 180Dh/180Eh bracket around this one
        mov     ah, 40h                                        ;#3A2F: B4 40
        int     21h                                            ;#3A31: CD 21
PRINT_CHECK_WRITE:
        ; Carry, or a short count, means trouble
        jb      short PRINT_WRITE_FAILED                       ;#3A33: 72 0B
        cmp     cx, ax                                         ;#3A35: 3B C8
        jnz     short PRINT_CLASSIFY_HANDLE                    ;#3A37: 75 09
PRINT_RETURN:
        ; Unwind the six pushes
        pop     di                                             ;#3A39: 5F
        pop     es                                             ;#3A3A: 07
        pop     dx                                             ;#3A3B: 5A
        pop     cx                                             ;#3A3C: 59
        pop     bx                                             ;#3A3D: 5B
        pop     ax                                             ;#3A3E: 58
        ret                                                    ;#3A3F: C3

PRINT_WRITE_FAILED:
        ; The call itself returned carry: count zero
        xor     ax, ax                                         ;#3A40: 33 C0
PRINT_CLASSIFY_HANDLE:
        ; Ask IOCTL whether the handle is a device
        inc     ax                                             ;#3A42: 40
        cmp     cx, ax                                         ;#3A43: 3B C8
        lahf                                                   ;#3A45: 9F
        push    ax                                             ;#3A46: 50
        mov     ax, 4400h                                      ;#3A47: B8 00 44
        int     21h                                            ;#3A4A: CD 21
        pop     ax                                             ;#3A4C: 58
        test    dl, 80h                                        ;#3A4D: F6 C2 80
        jz      short PRINT_ON_A_FILE                          ;#3A50: 74 08
        sahf                                                   ;#3A52: 9E
        jz      short PRINT_RETURN                             ;#3A53: 74 E4
        mov     dx, MSG_ERRO_DE_ESCRITA_NO - TRANSIENT_BIAS    ;#3A55: BA A3 0A
        jmp     short PRINT_REPORT_ERROR                       ;#3A58: EB 14

PRINT_ON_A_FILE:
        ; Disk full, unless it is the temporary file
        push    ds                                             ;#3A5A: 1E
        mov     ds, [cs:LOW_COPY_SEG]                          ;#3A5B: 2E 8E 1E 60 46
        test    byte [SHELL_FLAGS], SHELL_PIPE_ACTIVE          ;#3A60: F6 06 39 03 02
        pop     ds                                             ;#3A65: 1F
        mov     dx, MSG_ERRO_NO_ARQUIVO_TEMPORARIO - TRANSIENT_BIAS ;#3A66: BA E9 02
        jnz     short PRINT_REPORT_ERROR                       ;#3A69: 75 03
        mov     dx, MSG_DISCO_CHEIO - TRANSIENT_BIAS           ;#3A6B: BA 8D 0A
PRINT_REPORT_ERROR:
        ; Clear the echo flags, then print DX
        push    ds                                             ;#3A6E: 1E
        mov     ds, [cs:LOW_COPY_SEG]                          ;#3A6F: 2E 8E 1E 60 46
        and     byte [SHELL_FLAGS], 0FCh                       ;#3A74: 80 26 39 03 FC
        or      byte [SHELL_FLAGS_CLEARED], 3                  ;#3A79: 80 0E 36 03 03
        pop     ds                                             ;#3A7E: 1F
        cmp     bx, 2                                          ;#3A7F: 83 FB 02
        jz      short PRINT_RETURN                             ;#3A82: 74 B5
        jmp     near CMD_ERROR_EXIT                            ;#3A84: E9 62 F4

SHOW_PROMPT:
        ; PROMPT_CR_LF and the prompt string, DS and ES preserved
        push    ds                                             ;#3A87: 1E
        push    es                                             ;#3A88: 06
        call    near PROMPT_CR_LF                              ;#3A89: E8 4A 00
        push    cs                                             ;#3A8C: 0E
        pop     ds                                             ;#3A8D: 1F
        mov     si, ENV_NAME_PROMPT - TRANSIENT_BIAS           ;#3A8E: BE 22 05
        mov     cx, 7                                          ;#3A91: B9 07 00
        call    near SCAN_ENVIRONMENT                          ;#3A94: E8 85 F6
        pushf                                                  ;#3A97: 9C
        add     di, cx                                         ;#3A98: 03 F9
        popf                                                   ;#3A9A: 9D
        push    es                                             ;#3A9B: 06
        pop     ds                                             ;#3A9C: 1F
        mov     si, di                                         ;#3A9D: 8B F7
        push    cs                                             ;#3A9F: 0E
        pop     es                                             ;#3AA0: 07
        jnb     short PROMPT_STR_NEXT_CHAR                     ;#3AA1: 73 0E
        call    near PROMPT_DRIVE                              ;#3AA3: E8 3D 00
        mov     al, [cs:PROMPT_ARROW - TRANSIENT_BIAS]         ;#3AA6: 2E A0 29 05
        call    near PUT_CHAR                                  ;#3AAA: E8 3C 00
PROMPT_STR_RETURN:
        ; End of the string, or nothing after a '$'
        pop     es                                             ;#3AAD: 07
        pop     ds                                             ;#3AAE: 1F
        ret                                                    ;#3AAF: C3

PROMPT_STR_SKIP:
        ; Step over the character the code consumed
        inc     si                                             ;#3AB0: 46
PROMPT_STR_NEXT_CHAR:
        ; One character of the PROMPT value
        lodsb                                                  ;#3AB1: AC
        or      al, al                                         ;#3AB2: 0A C0
        jz      short PROMPT_STR_RETURN                        ;#3AB4: 74 F7
        cmp     al, "$"                                        ;#3AB6: 3C 24
        jz      short PROMPT_STR_ESCAPE                        ;#3AB8: 74 05
        call    near PUT_CHAR                                  ;#3ABA: E8 2C 00
        jmp     short PROMPT_STR_NEXT_CHAR                     ;#3ABD: EB F2

PROMPT_STR_ESCAPE:
        ; '$' -- look the next letter up in the table
        cmp     byte [si], 0                                   ;#3ABF: 80 3C 00
        jz      short PROMPT_STR_RETURN                        ;#3AC2: 74 E9
        mov     di, PROMPT_CHAR_TABLE - TRANSIENT_BIAS         ;#3AC4: BF F8 0B
        call    near LOOKUP_NAME_TABLE                         ;#3AC7: E8 76 F6
        jcxz    PROMPT_STR_SKIP                                ;#3ACA: E3 E4
        push    ds                                             ;#3ACC: 1E
        push    si                                             ;#3ACD: 56
        push    cs                                             ;#3ACE: 0E
        pop     ds                                             ;#3ACF: 1F
        call    cx                                             ;#3AD0: FF D1
        pop     si                                             ;#3AD2: 5E
        pop     ds                                             ;#3AD3: 1F
        jmp     short PROMPT_STR_NEXT_CHAR                     ;#3AD4: EB DB

PROMPT_CR_LF:
        ; PROMPT $_ — start a new line
        push    ds                                             ;#3AD6: 1E
        push    dx                                             ;#3AD7: 52
        push    cs                                             ;#3AD8: 0E
        pop     ds                                             ;#3AD9: 1F
        mov     dx, MSG_CRLF_ONLY - TRANSIENT_BIAS             ;#3ADA: BA 2E 05
        call    near PRINT_DOLLAR_STDOUT                       ;#3ADD: E8 0E FF
        pop     dx                                             ;#3AE0: 5A
        pop     ds                                             ;#3AE1: 1F
        ret                                                    ;#3AE2: C3

PROMPT_DRIVE:
        ; PROMPT $N — current drive letter
        mov     al, [cs:CURRENT_DRIVE]                         ;#3AE3: 2E A0 06 47
        add     al, "A"                                        ;#3AE7: 04 41
PUT_CHAR:
        ; AH=2 bracketed by BRASCII on/off, like PRINT_STRING_COMMON
        push    ax                                             ;#3AE9: 50
        push    dx                                             ;#3AEA: 52
        mov     dl, al                                         ;#3AEB: 8A D0
        mov     ax, 180Dh                                      ;#3AED: B8 0D 18
        int     21h                                            ;#3AF0: CD 21
        mov     ah, 2                                          ;#3AF2: B4 02
        int     21h                                            ;#3AF4: CD 21
        mov     ax, 180Eh                                      ;#3AF6: B8 0E 18
        int     21h                                            ;#3AF9: CD 21
        pop     dx                                             ;#3AFB: 5A
        pop     ax                                             ;#3AFC: 58
        ret                                                    ;#3AFD: C3

PUT_TWO_SPACES:
        ; Two PUT_CHAR calls with AL=20h
        push    ax                                             ;#3AFE: 50
        mov     al, " "                                        ;#3AFF: B0 20
        call    near PUT_CHAR                                  ;#3B01: E8 E5 FF
        call    near PUT_CHAR                                  ;#3B04: E8 E2 FF
        pop     ax                                             ;#3B07: 58
        ret                                                    ;#3B08: C3

PUT_DRIVE_LETTER:
        ; AL + 'A', then PUT_CHAR
        add     al, "A"                                        ;#3B09: 04 41
        call    near PUT_CHAR                                  ;#3B0B: E8 DB FF
        mov     al, ":"                                        ;#3B0E: B0 3A
        jmp     short PUT_CHAR                                 ;#3B10: EB D7

PRINT_ARROW:
        ; MSG_ARROW on stdout with DS and DX preserved
        push    ds                                             ;#3B12: 1E
        push    dx                                             ;#3B13: 52
        push    cs                                             ;#3B14: 0E
        pop     ds                                             ;#3B15: 1F
        mov     dx, MSG_ARROW - TRANSIENT_BIAS                 ;#3B16: BA E0 01
        call    near PRINT_NUL_STDOUT                          ;#3B19: E8 C8 FE
        pop     dx                                             ;#3B1C: 5A
        pop     ds                                             ;#3B1D: 1F
        ret                                                    ;#3B1E: C3

PROMPT_DOLLAR:
        ; PROMPT $$ — a literal '$' (mov al,"$")
        mov     al, "$"                                        ;#3B1F: B0 24
        jmp     short PUT_CHAR                                 ;#3B21: EB C6

PROMPT_ESCAPE:
        ; PROMPT $E — ESC, for ANSI sequences (mov al,ASCII_ESC)
        mov     al, ASCII_ESC                                  ;#3B23: B0 1B
        jmp     short PUT_CHAR                                 ;#3B25: EB C2

PROMPT_LESS:
        ; PROMPT $L — '<' (mov al,"<")
        mov     al, "<"                                        ;#3B27: B0 3C
        jmp     short PUT_CHAR                                 ;#3B29: EB BE

PROMPT_EQUAL:
        ; PROMPT $Q — '=' (mov al,"=")
        mov     al, "="                                        ;#3B2B: B0 3D
        jmp     short PUT_CHAR                                 ;#3B2D: EB BA

PROMPT_GREATER:
        ; PROMPT $G — '>' (mov al,">")
        mov     al, ">"                                        ;#3B2F: B0 3E
        jmp     short PUT_CHAR                                 ;#3B31: EB B6

PROMPT_PIPE:
        ; PROMPT $B — '|' (mov al,"|")
        mov     al, "|"                                        ;#3B33: B0 7C
        jmp     short PUT_CHAR                                 ;#3B35: EB B2

PROMPT_BACKSPACE:
        ; PROMPT $H — erase the previous character
        mov     dx, MSG_RUBOUT - TRANSIENT_BIAS                ;#3B37: BA 2A 05
        jmp     near PRINT_DOLLAR_STDOUT                       ;#3B3A: E9 B1 FE

PROMPT_PATH:
        ; PROMPT $P — drive and current directory
        mov     si, SHARED_DTA                                 ;#3B3D: BE DA 47
        mov     byte [si], 0                                   ;#3B40: C6 04 00
BUILD_CWD_PATH:
        ; PROMPT_PATH past the clear: drive prefix then APPEND_CWD into SHARED_DTA
        mov     di, SHARED_DTA                                 ;#3B43: BF DA 47
        call    near PARSE_DRIVE_PREFIX                        ;#3B46: E8 4A F8
        call    near APPEND_CWD                                ;#3B49: E8 65 F8
        mov     dx, SHARED_DTA                                 ;#3B4C: BA DA 47
        jmp     near PRINT_NUL_STDOUT                          ;#3B4F: E9 92 FE

PROMPT_VERSION:
        ; PROMPT $V — the SISNE version banner
        mov     ds, [LOW_COPY_SEG]                             ;#3B52: 8E 1E 60 46
        mov     dx, MSG_SISNE_PLUS+BANNER_TEXT                 ;#3B56: BA 28 0B
        jmp     near PRINT_DOLLAR_STDOUT                       ;#3B59: E9 92 FE

PROMPT_DATE:
        ; PROMPT $D — date, via INT 21h AH=2Ah
        mov     ah, 2Ah                                        ;#3B5C: B4 2A
        int     21h                                            ;#3B5E: CD 21
        mov     di, FORMAT_SCRATCH                             ;#3B60: BF 0B 47
        mov     si, DAY_ABBREV - TRANSIENT_BIAS                ;#3B63: BE 6C 06
        call    near COPY_3CHAR_ENTRY                          ;#3B66: E8 F7 F6
        mov     al, " "                                        ;#3B69: B0 20
        stosb                                                  ;#3B6B: AA
        mov     bh, 10h                                        ;#3B6C: B7 10
        mov     al, dl                                         ;#3B6E: 8A C2
        call    near PUT_TWO_DIGITS                            ;#3B70: E8 F7 F6
        mov     al, "-"                                        ;#3B73: B0 2D
        stosb                                                  ;#3B75: AA
        mov     al, dh                                         ;#3B76: 8A C6
        dec     al                                             ;#3B78: FE C8
        mov     si, MONTH_ABBREV - TRANSIENT_BIAS              ;#3B7A: BE 48 06
        call    near COPY_3CHAR_ENTRY                          ;#3B7D: E8 E0 F6
        mov     al, "-"                                        ;#3B80: B0 2D
        stosb                                                  ;#3B82: AA
        xchg    ax, cx                                         ;#3B83: 91
        mov     dl, 64h                                        ;#3B84: B2 64
        div     dl                                             ;#3B86: F6 F2
        push    ax                                             ;#3B88: 50
        call    near PUT_TWO_DIGITS                            ;#3B89: E8 DE F6
        pop     ax                                             ;#3B8C: 58
        xchg    ah, al                                         ;#3B8D: 86 C4
        call    near PUT_TWO_DIGITS                            ;#3B8F: E8 D8 F6
PROMPTDATE_TERMINATE:
        ; NUL after whichever order the digits went
        xor     al, al                                         ;#3B92: 32 C0
        stosb                                                  ;#3B94: AA
        mov     dx, FORMAT_SCRATCH                             ;#3B95: BA 0B 47
        jmp     near PRINT_NUL_STDOUT                          ;#3B98: E9 49 FE

PROMPT_TIME:
        ; PROMPT $T — time, via INT 21h AH=2Ch
        mov     ah, 2Ch                                        ;#3B9B: B4 2C
        int     21h                                            ;#3B9D: CD 21
        mov     di, FORMAT_SCRATCH                             ;#3B9F: BF 0B 47
        mov     bh, 10h                                        ;#3BA2: B7 10
        mov     al, ch                                         ;#3BA4: 8A C5
        call    near PUT_TWO_DIGITS                            ;#3BA6: E8 C1 F6
        mov     al, ":"                                        ;#3BA9: B0 3A
        stosb                                                  ;#3BAB: AA
        mov     al, cl                                         ;#3BAC: 8A C1
        call    near PUT_TWO_DIGITS                            ;#3BAE: E8 B9 F6
        mov     al, ":"                                        ;#3BB1: B0 3A
        stosb                                                  ;#3BB3: AA
        mov     al, dh                                         ;#3BB4: 8A C6
        call    near PUT_TWO_DIGITS                            ;#3BB6: E8 B1 F6
        mov     al, "."                                        ;#3BB9: B0 2E
        stosb                                                  ;#3BBB: AA
        mov     al, dl                                         ;#3BBC: 8A C2
        call    near PUT_TWO_DIGITS                            ;#3BBE: E8 A9 F6
        jmp     short PROMPTDATE_TERMINATE                     ;#3BC1: EB CF

SCAN_LINE_QUOTED:
        ; Walk LINE_BUF in place through NEXT_CHAR_QUOTED
        mov     si, LINE_BUF                                   ;#3BC3: BE 64 46
        mov     di, si                                         ;#3BC6: 8B FE
        xor     ch, ch                                         ;#3BC8: 32 ED
        call    near NEXT_CHAR_QUOTED                          ;#3BCA: E8 56 00
        mov     si, di                                         ;#3BCD: 8B F7
SCAN_TAIL_SPECIALS:
        ; Copy the tail, taking out < and > and leaving | where it is
        ; The tail is copied one byte at a time and four characters never reach the copy
        ; unchanged.  IS_REDIR_CHAR picks them out, and what happens next differs for
        ; each:
        ;
        ; 3BDD    cmp al, '"'
        ; jnz     short TAIL_CHECK_GT
        ; call    near COPY_QUOTED
        ; 3BE6    cmp al, ">"
        ; jnz     short TAIL_CHECK_LT
        ; call    near PARSE_REDIR_OUT
        ; 3BF1    cmp al, "<"
        ; jnz     short TAIL_IS_PIPE
        ; call    near PARSE_REDIR_IN
        ; 3BFC    or      byte [es:SHELL_FLAGS], SHELL_PIPE_ACTIVE
        ;
        ; '<' and '>' are consumed: their filenames go to REDIR_IN_NAME and
        ; REDIR_OUT_NAME and nothing of them is left in the line.  '|' is the opposite --
        ; it sets the pipe bit and then writes itself back out at 3C12h, because
        ; TAKE_NEXT_CHAINED_COMMAND has to find it again later to know where one stage
        ; ends.  So the same pass that removes two kinds of syntax deliberately preserves
        ; the third.
        ;
        ; A quote suspends all of it.  COPY_QUOTED runs a depth count in CH and copies
        ; everything between the quotes, so a '>' inside them is a character rather than
        ; a redirection.
        ;
        ; Three things make a pipe a syntax error, and the third is the one worth
        ; noticing:
        ;
        ; 3C02    call    near SKIP_SEPARATORS_AT_SI
        ; jz      short TAIL_PIPE_SYNTAX
        ; cmp al, "|"
        ; jz      short TAIL_PIPE_SYNTAX
        ; mov al, "|"
        ; cmp     [di-1], al
        ; jz      short TAIL_PIPE_SYNTAX
        ;
        ; Nothing after it, another pipe straight after it, or -- the third check -- the
        ; byte already written being a pipe.  Separators were skipped before the second
        ; test, so "a | | b" gets past it; the check against the output is what catches
        ; that, by asking what was emitted rather than what was read.
        ;
        ; ">>" is found by looking one character ahead and incrementing the byte just
        ; below the name buffer, which is REDIR_APPEND_FLAG.  Append is not a separate
        ; path, only a counter that started at zero.
        lodsb                                                  ;#3BCF: AC
        call    near IS_REDIR_CHAR                             ;#3BD0: E8 14 F4
        jz      short TAIL_CHECK_QUOTE                         ;#3BD3: 74 08
        mov     [di], al                                       ;#3BD5: 88 05
        inc     di                                             ;#3BD7: 47
        cmp     al, ASCII_CR                                   ;#3BD8: 3C 0D
        jnz     short SCAN_TAIL_SPECIALS                       ;#3BDA: 75 F3
        ret                                                    ;#3BDC: C3

TAIL_CHECK_QUOTE:
        ; A quote takes the run verbatim
        cmp     al, '"'                                        ;#3BDD: 3C 22
        jnz     short TAIL_CHECK_GT                            ;#3BDF: 75 05
        call    near COPY_QUOTED                               ;#3BE1: E8 4D 00
        jmp     short SCAN_TAIL_SPECIALS                       ;#3BE4: EB E9

TAIL_CHECK_GT:
        ; '>' starts an output redirection
        cmp     al, ">"                                        ;#3BE6: 3C 3E
        jnz     short TAIL_CHECK_LT                            ;#3BE8: 75 07
        call    near PARSE_REDIR_OUT                           ;#3BEA: E8 5C 00
        jb      short TAIL_REDIR_SYNTAX                        ;#3BED: 72 28
        jmp     short SCAN_TAIL_SPECIALS                       ;#3BEF: EB DE

TAIL_CHECK_LT:
        ; '<' starts an input one
        cmp     al, "<"                                        ;#3BF1: 3C 3C
        jnz     short TAIL_IS_PIPE                             ;#3BF3: 75 07
        call    near PARSE_REDIR_IN                            ;#3BF5: E8 4B 00
        jb      short TAIL_REDIR_SYNTAX                        ;#3BF8: 72 1D
        jmp     short SCAN_TAIL_SPECIALS                       ;#3BFA: EB D3

