        ; STORE_LINE_BYTE sits between the two halves and belongs to neither: it appends
        ; one byte to the line being built and refuses past 7Fh with "Linha do FOR muito
        ; longa", which is the only limit the substitution has.
        test    byte [SHELL_FLAGS], SHELL_FOR_ACTIVE           ;#3E95: F6 06 39 03 01
        jnz     short FOR_FIND_NEXT                            ;#3E9A: 75 01
        ret                                                    ;#3E9C: C3

FOR_FIND_NEXT:
        ; AH=4Fh for whatever else the pattern matches
        push    ds                                             ;#3E9D: 1E
        pop     es                                             ;#3E9E: 07
        mov     ah, 4Fh                                        ;#3E9F: B4 4F
        cmp     byte [FOR_ITER_ACTIVE], 0                      ;#3EA1: 80 3E F5 05 00
        jnz     short FOR_DO_FIND                              ;#3EA6: 75 4A
        mov     si, [FOR_LIST_START]                           ;#3EA8: 8B 36 F0 05
        mov     [FOR_LIST_CURSOR], si                          ;#3EAC: 89 36 F2 05
        mov     al, [si]                                       ;#3EB0: 8A 04
        or      al, al                                         ;#3EB2: 0A C0
        jnz     short FOR_TAKE_LIST_ITEM                       ;#3EB4: 75 1A
        and     byte [SHELL_FLAGS], 0FEh                       ;#3EB6: 80 26 39 03 FE
        jmp     near RETURN_TO_PROMPT                          ;#3EBB: E9 81 11

STORE_LINE_BYTE:
