        or      al, al                                         ;#3EBE: 0A C0
        jz      short STORELINE_RETURN                         ;#3EC0: 74 07
        cmp     cl, 7Fh                                        ;#3EC2: 80 F9 7F
        jnb     short STORELINE_TOO_LONG                       ;#3EC5: 73 03
        stosb                                                  ;#3EC7: AA
        inc     cx                                             ;#3EC8: 41
STORELINE_RETURN:
        ; Stored, and CX counts what the line holds
        ret                                                    ;#3EC9: C3

STORELINE_TOO_LONG:
