        mov     dx, MSG_LINHA_DO_FOR_MUITO - TRANSIENT_BIAS    ;#3ECA: BA C5 07
        jmp     near CMD_ERROR_EXIT                            ;#3ECD: E9 19 F0

FOR_TAKE_LIST_ITEM:
