        lodsb                                                  ;#3ED0: AC
        call    near IS_WILDCARD                               ;#3ED1: E8 0C F1
        jnz     short FORITEM_NEXT_CHAR                        ;#3ED4: 75 05
        mov     byte [FOR_ITER_ACTIVE], 1                      ;#3ED6: C6 06 F5 05 01
