        ; The trap that made them hard is still real and is the reason to keep this note:
        ; DS was set to LOW_COPY_SEG by a caller, not in the routine itself, so any sweep
        ; that tracks the segment within a straight-line walk will read them as transient
        ; addresses.  The rule is at 05EFh.
        mov     dx, FOR_DTA                                    ;#3EF3: BA F6 05
        mov     ah, 1Ah                                        ;#3EF6: B4 1A
        int     21h                                            ;#3EF8: CD 21
        pop     ax                                             ;#3EFA: 58
FORFIND_CALL_INT21:
        ; AH is 4Eh the first time, 4Fh after
        mov     dx, [FOR_LIST_CURSOR]                          ;#3EFB: 8B 16 F2 05
        int     21h                                            ;#3EFF: CD 21
        jnb     short FORFIND_CHECK_ENTRY                      ;#3F01: 73 07
FORFIND_LIST_EXHAUSTED:
        ; No more matches: the iteration is over
        mov     byte [FOR_ITER_ACTIVE], 0                      ;#3F03: C6 06 F5 05 00
        jmp     short FOR_FIND_NEXT                            ;#3F08: EB 93

FORFIND_CHECK_ENTRY:
        ; 0FFFFh in the entry number means none
        cmp     word [FOR_DTA_ENTRY_NUM], 0FFFFh               ;#3F0A: 83 3E 03 06 FF
        jz      short FORFIND_LIST_EXHAUSTED                   ;#3F0F: 74 F2
        cmp     byte [FOR_SEARCH_ATTR], 10h                    ;#3F11: 80 3E F4 05 10
        jnz     short FORFIND_USE_NAME                         ;#3F16: 75 0A
        mov     si, FOR_DTA                                    ;#3F18: BE F6 05
        call    near IS_DOT_ENTRY                              ;#3F1B: E8 16 F1
        mov     ah, 4Fh                                        ;#3F1E: B4 4F
        jnb     short FORFIND_CALL_INT21                       ;#3F20: 73 D9
FORFIND_USE_NAME:
        ; Look the match up along the PATH
        mov     di, [FOR_LIST_CURSOR]                          ;#3F22: 8B 3E F2 05
        call    near FIND_NAME_IN_PATH                         ;#3F26: E8 E0 F2
        xor     al, al                                         ;#3F29: 32 C0
        stosb                                                  ;#3F2B: AA
FOR_BUILD_BODY_LINE:
        ; Read the body down from FOR_BODY_END, substituting the variable
        ; The body was stored backwards so it could be read backwards.
        ;
        ; #1136 has FOR's header parser setting DI to FOR_BODY_END and STD before copying
        ; the body, filling that half of the buffer downward.  This is the other end:
        ;
        ; 3F2C    mov     si, FOR_BODY_END
        ; push    cs
        ; pop     es
        ; mov     di, LINE_BUF
        ; xor     cx, cx
        ; 3F36    mov     al, [si]
        ; dec     si
        ;
        ; SI walks down and DI walks up, so a body written from the top down comes out in
        ; order.  Neither end has to know the body's length, which is the point of
        ; putting it at the far end of the buffer in the first place -- the list grows up
        ; from FOR_LIST_BUF and the body down from FOR_BODY_END, and whichever runs out
        ; of room first is the one that fails.
        ;
        ; The substitution is a single character compare:
        ;
        ; 3F63    mov     al, [si]
        ; cmp     [FOR_VARIABLE_CHAR], al
        ; mov al, "%"
        ; jnz     short FORBODY_STORE_CHAR
        ;
        ; `mov al, "%"` sits between the compare and the branch, so the '%' is already
        ; back in AL for the not-matched path to store -- the flags carry the answer
        ; across an instruction that would otherwise have to be duplicated on both sides.
        ; A match instead copies from FOR_LIST_CURSOR until its NUL.
