        ; The line is then echoed unless a pipe is running or ECHO is off, and 3F45h
        ; checks the pipe first: a stage of a pipeline should not print the command that
        ; made it.
        mov     si, FOR_BODY_END                               ;#3F2C: BE EE 05
        push    cs                                             ;#3F2F: 0E
        pop     es                                             ;#3F30: 07
        mov     di, LINE_BUF                                   ;#3F31: BF 64 46
        xor     cx, cx                                         ;#3F34: 33 C9
FORBODY_NEXT_CHAR:
        ; Reading the body backwards from its end
        mov     al, [si]                                       ;#3F36: 8A 04
        dec     si                                             ;#3F38: 4E
        cmp     al, "%"                                        ;#3F39: 3C 25
        jz      short FOR_SUBSTITUTE_VARIABLE                  ;#3F3B: 74 26
FORBODY_STORE_CHAR:
        ; Anything that is not the variable
        call    near STORE_LINE_BYTE                           ;#3F3D: E8 7E FF
        jnz     short FORBODY_NEXT_CHAR                        ;#3F40: 75 F4
        mov     al, ASCII_CR                                   ;#3F42: B0 0D
        stosb                                                  ;#3F44: AA
        test    byte [SHELL_FLAGS], SHELL_PIPE_ACTIVE          ;#3F45: F6 06 39 03 02
        jnz     short ECHOLINE_RETURN                          ;#3F4A: 75 15
ECHO_BATCH_LINE:
        ; Print LINE_BUF, gated on ECHO_STATE
        cmp     byte [ECHO_STATE], 0                           ;#3F4C: 80 3E 79 02 00
        jz      short ECHOLINE_RETURN                          ;#3F51: 74 0E
        call    near SHOW_PROMPT                               ;#3F53: E8 31 FB
        push    cs                                             ;#3F56: 0E
        pop     ds                                             ;#3F57: 1F
        mov     dx, LINE_BUF                                   ;#3F58: BA 64 46
        call    near PRINT_CR_STDOUT                           ;#3F5B: E8 8B FA
        call    near PROMPT_CR_LF                              ;#3F5E: E8 75 FB
ECHOLINE_RETURN:
        ; Carry, whether or not anything was printed
        stc                                                    ;#3F61: F9
        ret                                                    ;#3F62: C3

FOR_SUBSTITUTE_VARIABLE:
        ; The character after '%' matched — copy the current list item
        mov     al, [si]                                       ;#3F63: 8A 04
        cmp     [FOR_VARIABLE_CHAR], al                        ;#3F65: 38 06 EF 05
        mov     al, "%"                                        ;#3F69: B0 25
        jnz     short FORBODY_STORE_CHAR                       ;#3F6B: 75 D0
        dec     si                                             ;#3F6D: 4E
        mov     bx, [FOR_LIST_CURSOR]                          ;#3F6E: 8B 1E F2 05
FORSUB_COPY_ITEM:
        ; The list entry goes in where the '%' was
        mov     al, [bx]                                       ;#3F72: 8A 07
        inc     bx                                             ;#3F74: 43
        call    near STORE_LINE_BYTE                           ;#3F75: E8 46 FF
        jnz     short FORSUB_COPY_ITEM                         ;#3F78: 75 F8
        cmp     byte [FOR_ITER_ACTIVE], 0                      ;#3F7A: 80 3E F5 05 00
        jz      short FORBODY_NEXT_CHAR                        ;#3F7F: 74 B5
        mov     bx, FOR_DTA+DTA_NAME                           ;#3F81: BB 14 06
FORSUB_COPY_TAIL:
        ; ...and the found name after it, if searching
        mov     al, [bx]                                       ;#3F84: 8A 07
        inc     bx                                             ;#3F86: 43
        call    near STORE_LINE_BYTE                           ;#3F87: E8 34 FF
        jnz     short FORSUB_COPY_TAIL                         ;#3F8A: 75 F8
        jmp     short FORBODY_NEXT_CHAR                        ;#3F8C: EB A8

TAKE_NEXT_CHAINED_COMMAND:
        ; Swap the pipe names and load the next stage into LINE_BUF
        ; The test is the first three instructions; the rest takes the next stage and
        ; sets it up.
        ;
        ; 3FB1    mov     ax, [PIPE_NAME_PTRS]
        ; xchg    [PIPE_NAME_PTRS+2], ax
        ; mov     [PIPE_NAME_PTRS], ax
        ;
        ; Two words holding two temporary names, rotated once per stage, so the file the
        ; previous command wrote is the one this command reads.  A pipeline of any length
        ; needs only the two, because only two are ever live at once.
        ;
        ; Then the command itself:
        ;
        ; 3FBB    mov     di, LINE_BUF
        ; lodsb
        ; stosb
        ; cmp al, "|"
        ; jz      short CHAIN_END_COMMAND
        ; cmp al, ASCII_CR
        ; jnz     short CHAIN_COPY_CHAR
        ; dec     si
        ; or      byte [REDIR_FLAGS], 0Ah
        ;
        ; Copied out of CHAIN_LINE_COPY until '|' or CR.  Which one stopped it is the
        ; whole distinction between a middle stage and the last: CR means nothing follows,
        ; so REDIR_OUT_TAKEN and REDIR_OUT_TAKEN_FOR go on and the output side stops
        ; being a temporary file.  3FCEh writes a CR over whichever terminator it was,
        ; so the command line handed on looks like any other, and CHAIN_CURSOR keeps the
        ; place for next time.
        ;
        ; Carry says whether there was anything to take.  Running out clears
        ; SHELL_PIPE_ACTIVE and goes back to the prompt; two '|' in a row is
        ; MSG_ERRO_SINTATICO_NO_ENCADEAMENTO, since 3FADh sees the second one where a
        ; command should start.
        test    byte [SHELL_FLAGS], SHELL_PIPE_ACTIVE          ;#3F8E: F6 06 39 03 02
        jnz     short CHAIN_TAKE_NEXT                          ;#3F93: 75 07
        ret                                                    ;#3F95: C3

CHAIN_SYNTAX_ERROR:
        ; Two bars in a row, or one with nothing after
        mov     dx, MSG_ERRO_SINTATICO_NO_ENCADEAMENTO - TRANSIENT_BIAS ;#3F96: BA B4 02
        jmp     near CMD_ERROR_EXIT                            ;#3F99: E9 4D EF

CHAIN_TAKE_NEXT:
