        mov     si, [CHAIN_CURSOR]                             ;#3F9C: 8B 36 EC 04
        call    near SKIP_SEPARATORS_AT_SI                     ;#3FA0: E8 87 F0
        jnz     short CHAIN_CHECK_PIPE                         ;#3FA3: 75 08
        and     byte [SHELL_FLAGS], 0FDh                       ;#3FA5: 80 26 39 03 FD
        jmp     near RETURN_TO_PROMPT                          ;#3FAA: E9 92 10

CHAIN_CHECK_PIPE:
