        mov     byte [es:di-1], ASCII_CR                       ;#3FCE: 26 C6 45 FF 0D
        mov     [CHAIN_CURSOR], si                             ;#3FD3: 89 36 EC 04
        stc                                                    ;#3FD7: F9
        ret                                                    ;#3FD8: C3

BATCH_NEXT_LINE:
        ; Read and dispatch the next batch line; needs SHELL_BATCH_ACTIVE
        ; Three kinds of line never reach the command dispatcher, and none of them costs
        ; a decision later on.
        ;
        ; 3FEB    call    near SCAN_LINE_END
        ; cmp al, ":"
        ; jz      short BATCH_READ_LINE
        ; cmp al, ASCII_CR
        ; jz      short BATCH_READ_LINE
        ; cmp al, "@"
        ; jnz     short SCAN_FOR_PERCENT
        ; mov     byte [ECHO_THIS_LINE], 0
        ; call    near DELETE_ONE_CHAR
        ;
        ; SCAN_LINE_END leaves AL on the first non-blank character, having already
        ; advanced BAT_POS past the line -- so a ':' or a bare CR goes straight back to
        ; 3FE1h for another line, read and discarded without echo or execution.  That is
        ; why GOTO's labels are inert: nothing skips them at execution time because they
        ; never get that far.
