        ; SHELL_BATCH_ACTIVE before going back to the prompt -- the same bit
        ; START_BATCH_FILE set in #1131 and CMD_GOTO clears on a missing label in #1138.
        ; Three places set or clear it and all three are ways a batch file can stop.
        test    byte [SHELL_FLAGS], SHELL_BATCH_ACTIVE         ;#3FD9: F6 06 39 03 04
        jnz     short BATCH_READ_LINE                          ;#3FDE: 75 01
        ret                                                    ;#3FE0: C3

BATCH_READ_LINE:
