        ; 4030    mov     dl, [es:di]
        ; sub dl, "0"
        ; cmp     dl, 9
        ; jnbe    short PCT_TRY_ENV_NAME             ; not a digit -- try %NAME%
        ; call    near DELETE_ONE_CHAR
        ; shl     ax, 1
        ; mov     si, BATCH_PARAM_PTRS
        ; add     si, ax                  ; %0..%9
        ; mov     si, [si]
        ; or      si, si
        ; jz      short SCAN_FOR_PERCENT  ; unset -- it just disappears
