        ; 4061    mov     si, di                  ; scan on for the closing '%'
        ; lodsb
        ; cmp al, ASCII_CR
        ; jz      short PCT_LINE_DONE
        ; cmp al, "%"
        ; jnz     short PCT_SCAN_NAME
