READ_BATCH_LINE:
        ; Open AUTOEXEC_PATH, seek to BAT_POS_LO/HI, read 80h into LINE_BUF, close
        ; Every line costs an open, a seek, a read and a close.  Nothing is kept between
        ; calls but the position:
        ;
        ; 40F3    mov     ax, 3D00h
        ; mov     dx, AUTOEXEC_PATH
        ; int     21h
        ; ...
        ; mov     ax, 4200h
        ; mov     cx, [BAT_POS_HI]
        ; mov     dx, [BAT_POS_LO]
        ; int     21h
        ; ...
        ; mov     ah, 3Fh
        ; mov     cx, 80h
        ; mov     dx, LINE_BUF
        ;
        ; A command run from a batch file may be a program that uses every handle DOS
        ; will give it, or one that overwrites the transient outright, so holding a
        ; handle across the line would be holding it across anything.  This is the third
        ; place the shell pays that price deliberately -- COPY replays its directory
        ; search in #1128 and GOTO rewinds to the top in #1138.
        ;
        ; The end of the file is marked by a position of 0FFFFFFFFh, and testing for it
        ; takes four instructions and no comparison:
        ;
        ; 40E1    mov     dx, [BAT_POS_LO]
        ; add     dx, [BAT_POS_HI]
        ; rcr     dx, 1
        ; inc     dx
        ; jz      short BATREAD_RETURN
        ;
        ; The sum of two words can only reach 1FFFEh when both are 0FFFFh, and that is
        ; the one case where rotating the carry back in gives 0FFFFh, which `inc` turns
        ; to zero.  Any other pair lands somewhere else.
        ;
        ; Failing to read is not simply an error.  4128h asks
        ; VEC_DRIVE_REMOVABLE first, and on a floppy adds "Coloque o disco com o arquivo"
        ; and waits for a key -- the batch file may be on a disk somebody took out, which
        ; is worth telling apart from a batch file that is broken.
        mov     dx, [BAT_POS_LO]                               ;#40E1: 8B 16 DF 03
        add     dx, [BAT_POS_HI]                               ;#40E5: 03 16 E1 03
        rcr     dx, 1                                          ;#40E9: D1 DA
        inc     dx                                             ;#40EB: 42
        jz      short BATREAD_RETURN                           ;#40EC: 74 39
        mov     byte [BAT_READING], 1                          ;#40EE: C6 06 88 02 01
        mov     ax, 3D00h                                      ;#40F3: B8 00 3D
        mov     dx, AUTOEXEC_PATH                              ;#40F6: BA E3 03
        int     21h                                            ;#40F9: CD 21
        jb      short BATREAD_DISK_CHANGED                     ;#40FB: 72 2B
        mov     bx, ax                                         ;#40FD: 8B D8
        mov     ax, 4200h                                      ;#40FF: B8 00 42
        mov     cx, [BAT_POS_HI]                               ;#4102: 8B 0E E1 03
        mov     dx, [BAT_POS_LO]                               ;#4106: 8B 16 DF 03
        int     21h                                            ;#410A: CD 21
        push    ds                                             ;#410C: 1E
        push    es                                             ;#410D: 06
        pop     ds                                             ;#410E: 1F
        mov     ah, 3Fh                                        ;#410F: B4 3F
        mov     cx, 80h                                        ;#4111: B9 80 00
        mov     dx, LINE_BUF                                   ;#4114: BA 64 46
        int     21h                                            ;#4117: CD 21
        pop     ds                                             ;#4119: 1F
        push    ax                                             ;#411A: 50
        mov     ah, 3Eh                                        ;#411B: B4 3E
        int     21h                                            ;#411D: CD 21
        pop     dx                                             ;#411F: 5A
        or      dx, dx                                         ;#4120: 0B D2
        mov     byte [BAT_READING], 0                          ;#4122: C6 06 88 02 00
BATREAD_RETURN:
        ; Read what there was to read
        ret                                                    ;#4127: C3

BATREAD_DISK_CHANGED:
        ; Ask whether the batch disk is still there
        mov     byte [BAT_READING], 0                          ;#4128: C6 06 88 02 00
        call    far word [VEC_DRIVE_REMOVABLE]                 ;#412D: FF 1E 99 02
        pushf                                                  ;#4131: 9C
        push    cs                                             ;#4132: 0E
        pop     ds                                             ;#4133: 1F
        mov     dx, MSG_ARQUIVO_DE_COMANDOS_DEFEITUOSO - TRANSIENT_BIAS ;#4134: BA DC 08
        call    near PRINT_DOLLAR_STDERR                       ;#4137: E8 C3 F8
        popf                                                   ;#413A: 9D
        jnb     short BATLONG_STOP_BATCH                       ;#413B: 73 14
        mov     dx, MSG_COLOQUE_DISCO_COM_ARQUIVO - TRANSIENT_BIAS ;#413D: BA 4A 09
        call    near PRINT_DOLLAR_STDERR                       ;#4140: E8 BA F8
        call    near WAIT_FOR_KEY                              ;#4143: E8 2B 0F
        jmp     near RETURN_TO_PROMPT                          ;#4146: E9 F6 0E

REPORT_BATCH_LINE_LONG:
