        cmp     di, dx                                         ;#41A0: 3B FA
        jnbe    short LINE_ADVANCE_POS                         ;#41A2: 77 1F
        mov     al, [es:di]                                    ;#41A4: 26 8A 05
        cmp     al, ASCII_LF                                   ;#41A7: 3C 0A
