        cmp     al, ASCII_CR                                   ;#41AB: 3C 0D
        jz      short LINE_SKIP_TO_END                         ;#41AD: 74 F0
        cmp     al, ASCII_CTRL_Z                               ;#41AF: 3C 1A
        jz      short LINE_MARK_EOF                            ;#41B1: 74 05
        jmp     short LINE_ADVANCE_POS                         ;#41B3: EB 0E

LINE_AT_EOF:
