        mov     [BAT_POS_LO], ax                               ;#41BB: A3 DF 03
        mov     [BAT_POS_HI], ax                               ;#41BE: A3 E1 03
        jmp     short LINE_FIND_FIRST_WORD                     ;#41C1: EB 0D

LINE_ADVANCE_POS:
