        inc     di                                             ;#41D3: 47
        mov     al, [es:di]                                    ;#41D4: 26 8A 05
        call    near IS_BLANK                                  ;#41D7: E8 2A EE
        jz      short LINE_SKIP_BLANK                          ;#41DA: 74 F7
        ret                                                    ;#41DC: C3

DELETE_ONE_CHAR:
