        sub     bp, si                                         ;#41F8: 2B EE
        push    si                                             ;#41FA: 56
        add     si, bx                                         ;#41FB: 03 F3
        xchg    si, bx                                         ;#41FD: 87 DE
        mov     ax, di                                         ;#41FF: 8B C7
        mov     di, bx                                         ;#4201: 8B FB
        mov     cx, si                                         ;#4203: 8B CE
        sub     cx, ax                                         ;#4205: 2B C8
        inc     cx                                             ;#4207: 41
        push    ds                                             ;#4208: 1E
        push    es                                             ;#4209: 06
        pop     ds                                             ;#420A: 1F
        std                                                    ;#420B: FD
        rep     movsb                                          ;#420C: F3 A4
        cld                                                    ;#420E: FC
        pop     ds                                             ;#420F: 1F
        pop     cx                                             ;#4210: 59
        clc                                                    ;#4211: F8
