        cmp     word [CMD_TAIL_PTR], 80h                       ;#421F: 81 3E 89 02 80 00
        jnz     short STARTCMD_SET_FLAG                        ;#4225: 75 02
        mov     al, 40h                                        ;#4227: B0 40
