        ; 4291    jnz     short INTERNAL_RETURN   ; not a terminator -- not our command
        ; mov     dx, cx
        ; mov     di, PSP_TAIL
        ; call    near COPY_TO_CR_COUNTED          ; re-copy the tail
        ; mov     [PSP_TAIL_LEN], cl
        ; mov     si, PSP_TAIL
        ; mov     bp, si
        ; call    dx                  ; <- the handler
        ; jmp     near RETURN_TO_PROMPT
        ;
