        ; INTERNAL_COMMAND_TABLE (#950), read by LOOKUP_NAME_TABLE (#976), called here.
        ; Note that it is a NEAR call in the transient frame, which is why those table
        ; words needed +2020h to make sense as file addresses in #948.
        mov     di, INTERNAL_COMMAND_TABLE - TRANSIENT_BIAS    ;#4284: BF 83 0C
        call    near LOOKUP_NAME_TABLE                         ;#4287: E8 B6 EE
