        mov     di, PARSED_NAME_BUF                            ;#42AE: BF 3A 47
        call    near ARG_PARSE_INIT                            ;#42B1: E8 56 F0
        jb      short NOT_INTERNAL_COMMAND                     ;#42B4: 72 F4
        test    byte [ARG_FLAGS], ARG_HAS_WILDCARD             ;#42B6: F6 06 2D 47 08
        jnz     short NOT_INTERNAL_COMMAND                     ;#42BB: 75 ED
