        jz      short MAKE_EXTENSION_WILDCARD                  ;#42D0: 74 10
        push    si                                             ;#42D2: 56
        dec     si                                             ;#42D3: 4E
        mov     di, EXTENSION_TABLE - TRANSIENT_BIAS           ;#42D4: BF 3D 0C
        call    near LOOKUP_NAME_TABLE                         ;#42D7: E8 66 EE
        pop     si                                             ;#42DA: 5E
