        push    es                                             ;#42F6: 06
        mov     word [PATH_VALUE_OFF], 0                       ;#42F7: C7 06 36 47 00 00
        test    byte [ARG_FLAGS], ARG_HAS_SEPARATOR            ;#42FD: F6 06 2D 47 02
        jnz     short EXT_START_SEARCH                         ;#4302: 75 15
        mov     si, ENV_NAME_PATH - TRANSIENT_BIAS             ;#4304: BE 1D 05
        mov     cx, 5                                          ;#4307: B9 05 00
        call    near SCAN_ENVIRONMENT                          ;#430A: E8 0F EE
        jb      short EXT_START_SEARCH                         ;#430D: 72 0A
        add     di, cx                                         ;#430F: 03 F9
        mov     [PATH_VALUE_OFF], di                           ;#4311: 89 3E 36 47
        mov     [PATH_VALUE_SEG], es                           ;#4315: 8C 06 38 47
EXT_START_SEARCH:
