        call    near SET_SHARED_DTA                            ;#431A: E8 3F ED
        mov     si, PARSED_NAME_BUF                            ;#431D: BE 3A 47
        mov     di, SEARCH_PATTERN_BUF                         ;#4320: BF 8A 47
        call    near COPY_TO_NUL                               ;#4323: E8 87 EC
