        add     si, SEARCH_PATTERN_BUF                         ;#432E: 81 C6 8A 47
        mov     [PATH_NAME_START], si                          ;#4332: 89 36 31 47
        test    byte [ARG_FLAGS], 3                            ;#4336: F6 06 2D 47 03
