        pop     si                                             ;#43A5: 5E
        jcxz    EXT_FIND_NEXT                                  ;#43A6: E3 E1
        cmp     [BEST_EXT_INDEX], cl                           ;#43A8: 38 0E 35 47
        jbe     short EXT_FIND_NEXT                            ;#43AC: 76 DB
        mov     [BEST_EXT_INDEX], cl                           ;#43AE: 88 0E 35 47
        mov     di, [BEST_EXT_NAME_POS]                        ;#43B2: 8B 3E 33 47
        call    near COPY_TO_NUL                               ;#43B6: E8 F4 EB
        cmp     byte [BEST_EXT_INDEX], 0                       ;#43B9: 80 3E 35 47 00
        jnz     short EXT_FIND_NEXT                            ;#43BE: 75 C9
EXT_BUILD_RESULT:
