        mov     si, SEARCH_PATTERN_BUF                         ;#43C0: BE 8A 47
        mov     di, PARSED_NAME_BUF                            ;#43C3: BF 3A 47
        call    near BUILD_FULL_PATH                           ;#43C6: E8 1E F0
        mov     si, [PATH_NAME_START]                          ;#43C9: 8B 36 31 47
        mov     di, si                                         ;#43CD: 8B FE
        call    near COPY_UPCASE_COUNTED                       ;#43CF: E8 B4 EB
        cmp     byte [BEST_EXT_INDEX], 2                       ;#43D2: 80 3E 35 47 02
        jb      short SETUP_CMD_TAIL                           ;#43D7: 72 03
        jmp     near START_BATCH_FILE                          ;#43D9: E9 1D FA

SETUP_CMD_TAIL:
        ; Build PSP_TAIL and PSP_TAIL_LEN, then the default FCBs at 5Ch
        ; Everything a child needs to be told, assembled in the order DOS expects to find
        ; it.
        ;
        ; The tail goes to 81h with its length at 80h, then the first two arguments are
        ; turned into FCBs at 5Ch and 6Ch by AX=2901h -- twice, with a hand-rolled walk
        ; to the second argument in between, because AH=29h parses one name and does not
        ; advance past a separator on its own.
        ;
        ; Then the whole lot is moved to where the child will actually look:
        ;
        ; 442B    mov     di, PSP_FCB1
        ; mov     si, di
        ; mov     cx, 52h
        ; rep     movsw
        ;
        ; 52h words is 0A4h bytes, and 100h minus 5Ch is 0A4h -- so the copy is exactly
        ; 5Ch to the end of the PSP: the two FCBs and the tail, and nothing above or
        ; below them.  The count is not a chosen size but the distance between two fixed
        ; offsets, which is why it needs no comment in the original and no adjustment
        ; ever.
        ;
        ; Before the jump, two things are given up and one is armed.  FREE_TRANSIENT_BLOCK
        ; hands the memory back -- the same posture #1184 found at the prompt --
        ; FOR_NEST_GUARD is cleared, and RELOAD_PENDING is incremented so that whatever
        ; returns knows the transient will need checking.  `inc` rather than `mov`,
        ; because all the reader asks is whether it is non-zero.
        ;
        ; The environment segment is written into EXEC_PARAM_BLOCK's first word at the
        ; last moment, and control leaves through VEC_EXEC_CHILD as a far jump: nothing
        ; returns here.
        mov     di, PSP_TAIL                                   ;#43DC: BF 81 00
        call    near COPY_TO_CR_AT_BP                          ;#43DF: E8 BD EB
        mov     [PSP_TAIL_LEN], cl                             ;#43E2: 88 0E 80 00
        mov     bp, PSP_TAIL                                   ;#43E6: BD 81 00
        call    near SKIP_BLANKS_AT_BP                         ;#43E9: E8 33 EC
        call    near PARSE_NO_SWITCHES                         ;#43EC: E8 01 EE
        mov     di, PSP_FCB1                                   ;#43EF: BF 5C 00
        xchg    bp, si                                         ;#43F2: 87 F5
        mov     ax, 2901h                                      ;#43F4: B8 01 29
        int     21h                                            ;#43F7: CD 21
        xchg    si, bp                                         ;#43F9: 87 EE
CMDTAIL_SCAN_NAME:
        ; Run to the separator that ends the command
        mov     al, [bp]                                       ;#43FB: 8A 46 00
        inc     bp                                             ;#43FE: 45
        call    near IS_SEPARATOR                              ;#43FF: E8 09 EC
        jz      short CMDTAIL_BUILD_FCBS                       ;#4402: 74 06
        call    near IS_CR_OR_SWITCH                           ;#4404: E8 EF EB
        jnz     short CMDTAIL_SCAN_NAME                        ;#4407: 75 F2
        dec     bp                                             ;#4409: 4D
CMDTAIL_BUILD_FCBS:
        ; What is left becomes the tail and the two FCBs
        call    near PARSE_NO_SWITCHES                         ;#440A: E8 E3 ED
        mov     di, PSP_FCB2                                   ;#440D: BF 6C 00
        xchg    bp, si                                         ;#4410: 87 F5
        mov     ax, 2901h                                      ;#4412: B8 01 29
        int     21h                                            ;#4415: CD 21
        xchg    si, bp                                         ;#4417: 87 EE
        call    near FREE_TRANSIENT_BLOCK                      ;#4419: E8 48 EC
        mov     es, [LOW_COPY_SEG]                             ;#441C: 8E 06 60 46
        mov     byte [es:FOR_NEST_GUARD], 0                    ;#4420: 26 C6 06 35 03 00
        inc     byte [es:RELOAD_PENDING]                       ;#4426: 26 FE 06 78 02
        mov     di, PSP_FCB1                                   ;#442B: BF 5C 00
        mov     si, di                                         ;#442E: 8B F7
        mov     cx, 52h                                        ;#4430: B9 52 00
        rep     movsw                                          ;#4433: F3 A5
        mov     dx, PARSED_NAME_BUF                            ;#4435: BA 3A 47
        mov     bx, EXEC_PARAM_BLOCK                           ;#4438: BB A5 02
        mov     ax, [es:PSP_ENV_SEG]                           ;#443B: 26 A1 2C 00
        mov     [es:bx], ax                                    ;#443F: 26 89 07
        jmp     far word [es:VEC_EXEC_CHILD]                   ;#4442: 26 FF 2E A1 02

FIND_FIRST_ENTRY:
        ; AH=4Eh with CX=2 (hidden+system) on SEARCH_PATTERN_BUF
        mov     dx, SEARCH_PATTERN_BUF                         ;#4447: BA 8A 47
        mov     cx, 2                                          ;#444A: B9 02 00
        mov     ah, 4Eh                                        ;#444D: B4 4E
        int     21h                                            ;#444F: CD 21
        jmp     short FINDNEXT_CHECK                           ;#4451: EB 04

FIND_NEXT_ENTRY:
        ; INT 21h AH=4Fh — the continuation half of the directory walk
        mov     ah, 4Fh                                        ;#4453: B4 4F
        int     21h                                            ;#4455: CD 21
FINDNEXT_CHECK:
        ; Carry, or 0FFFFh in the entry, means no more
        jb      short FINDNEXT_RETURN                          ;#4457: 72 09
        cmp     word [SHARED_DTA+DTA_ENTRY_NUM], 0FFFFh        ;#4459: 83 3E E7 47 FF
        stc                                                    ;#445E: F9
        jz      short FINDNEXT_RETURN                          ;#445F: 74 01
        clc                                                    ;#4461: F8
FINDNEXT_RETURN:
        ; Carry says there was nothing
        ret                                                    ;#4462: C3

CMD_ICC:
        ; Run a nested COMMAND.COM — STUB_NAME_BUF straight to SETUP_CMD_TAIL
        ; Five instructions, and what they do depends entirely on what is already in
        ; STUB_NAME_BUF:
        ;
        ; 4463    push    ds
        ; mov     ds, [LOW_COPY_SEG]
        ; mov     si, STUB_NAME_BUF
        ; mov     di, PARSED_NAME_BUF
        ; call    near COPY_TO_NUL
        ; pop     ds
        ; jmp     near SETUP_CMD_TAIL
        ;
        ; That buffer holds COMMAND.COM's own path.  16DCh puts "\COMMAND.COM" there as
        ; the default and 0E37h overwrites it from the environment when COMSPEC names
        ; something else, and 118Bh is the reload path opening exactly that file.  So ICC
        ; copies the shell's path into the buffer the external-command machinery reads
        ; from and jumps straight into it.
        ;
        ; The effect is a nested COMMAND.COM, started the same way any external program
        ; is.  Nothing here execs anything: SETUP_CMD_TAIL builds the PSP tail and the
        ; default FCBs, and the ordinary path takes it from there, which is why the
        ; command needs no code of its own beyond the copy.
        ;
        ; It also skips the search entirely.  A typed name goes through
        ; PARSE_EXTERNAL_NAME, the ".???" trick and the PATH walk; ICC has an absolute
        ; path in hand and hands it over already resolved, so the one command guaranteed
        ; to be findable is the one that never looks.
        push    ds                                             ;#4463: 1E
        mov     ds, [LOW_COPY_SEG]                             ;#4464: 8E 1E 60 46
        mov     si, STUB_NAME_BUF                              ;#4468: BE 00 02
        mov     di, PARSED_NAME_BUF                            ;#446B: BF 3A 47
        call    near COPY_TO_NUL                               ;#446E: E8 3C EB
        pop     ds                                             ;#4471: 1F
        jmp     near SETUP_CMD_TAIL                            ;#4472: E9 67 FF

CMD_DIRET:
        ; The DIRET command (alias DIR) — 80 bytes that delegate everything
        ; Eighty bytes, and the loop that does the listing is five of them:
        ;
        ; 44B1    mov     ah, 4Eh
        ; int     21h
        ; jb      short DIRET_FINISH
        ; 44B7    call    near DIR_PRINT_NAME
        ; mov     ah, 4Fh
        ; int     21h
        ; jnb     short DIRET_PRINT_AND_NEXT
        ;
        ; Everything else is decisions about what to ask for.  The interesting one is the
        ; attribute mask:
        ;
        ; 44A1    mov     dx, PATHBLK_DIR
        ; mov     cx, 10h
        ; test    word [DIR_OPTION_FLAGS], SWITCH_A
        ; jz      short DIRET_FIND_FIRST
        ; xor     cx, cx
        ;
        ; CX is what AH=4Eh treats as "also return these", and 10h is the directory bit --
        ; so a plain DIR asks for files *and* directories, and bit 0 of the switch word
        ; takes the directories away.  Bit 0 is /A by CMD_SWITCH_LETTERS, and DIR's mask
        ; of 4C5h admits /A /C /P /S /W.
        ;
        ; That is not MS-DOS's /A.  Here it selects files only, which is what "arquivos"
        ; would mean to whoever wrote the table, and REPORT_FREE_SPACE agrees with it
        ; from the far end -- 4762h skips the directory count on the same bit, because
        ; with /A there are no directories to have counted.
        ;
        ; /C takes out the header rather than the body: bit 2 skips SHOW_VOLUME_LABEL, the
        ; AH=1Ah that points DOS at DIR_DTA, and SPLIT_PATH_AT_MARK, jumping straight to
        ; the page-size setup.  So the two switches that change what appears are on
        ; opposite halves of the output, and neither touches the loop.
        mov     si, bp                                         ;#4475: 8B F5
        call    near DIR_PARSE_SWITCHES                        ;#4477: E8 4F 00
        jb      short DIRET_ARG_ERROR                          ;#447A: 72 4A
        test    word [DIR_OPTION_FLAGS], SWITCH_C              ;#447C: F7 06 63 48 04 00
        jnz     short DIRET_START_SEARCH                       ;#4482: 75 13
        mov     al, [PATHBLK_DIR+PB_DRIVE_USED]                ;#4484: A0 F2 48
        call    near SHOW_VOLUME_LABEL                         ;#4487: E8 58 08
        mov     dx, DIR_DTA                                    ;#448A: BA F9 48
        mov     ah, 1Ah                                        ;#448D: B4 1A
        int     21h                                            ;#448F: CD 21
        mov     di, PATHBLK_DIR                                ;#4491: BF 93 48
        call    near SPLIT_PATH_AT_MARK                        ;#4494: E8 C5 00
DIRET_START_SEARCH:
        ; Page size settled; now the first entry
        call    near DIR_SET_PAGE_SIZE                         ;#4497: E8 89 00
        test    byte [PATHBLK_DIR+PB_DONE], 80h                ;#449A: F6 06 EE 48 80
        jnz     short DIRET_FINISH                             ;#449F: 75 1F
        mov     dx, PATHBLK_DIR                                ;#44A1: BA 93 48
        mov     cx, 10h                                        ;#44A4: B9 10 00
        test    word [DIR_OPTION_FLAGS], SWITCH_A              ;#44A7: F7 06 63 48 01 00
        jz      short DIRET_FIND_FIRST                         ;#44AD: 74 02
        xor     cx, cx                                         ;#44AF: 33 C9
DIRET_FIND_FIRST:
        ; AH=4Eh with the attributes /A chose
        mov     ah, 4Eh                                        ;#44B1: B4 4E
        int     21h                                            ;#44B3: CD 21
        jb      short DIRET_FINISH                             ;#44B5: 72 09
DIRET_PRINT_AND_NEXT:
        ; Print this one, then AH=4Fh for the next
        call    near DIR_PRINT_NAME                            ;#44B7: E8 CE 00
        mov     ah, 4Fh                                        ;#44BA: B4 4F
        int     21h                                            ;#44BC: CD 21
        jnb     short DIRET_PRINT_AND_NEXT                     ;#44BE: 73 F7
DIRET_FINISH:
        ; Close the line and add the totals
        call    near DIR_END_LINE                              ;#44C0: E8 37 02
        jmp     near DIR_MAYBE_FREE_SPACE                      ;#44C3: E9 45 02

DIRET_ARG_ERROR:
        ; The message the parser left in DX
        jmp     near CMD_ERROR_EXIT                            ;#44C6: E9 20 EA

DIR_PARSE_SWITCHES:
        ; Mask 4C5h through PARSE_SWITCHES into DIR_OPTION_FLAGS
        mov     di, CMD_SWITCH_LETTERS - TRANSIENT_BIAS        ;#44C9: BF 2D 0C
        mov     ax, 4C5h                                       ;#44CC: B8 C5 04
        call    near PARSE_SWITCHES                            ;#44CF: E8 D2 EC
        jb      short DIRSW_BAD_PARAM                          ;#44D2: 72 28
        mov     [DIR_OPTION_FLAGS], ax                         ;#44D4: A3 63 48
        mov     di, PATHBLK_DIR                                ;#44D7: BF 93 48
        mov     ah, 0Fh                                        ;#44DA: B4 0F
        add     ah, 0F0h                                       ;#44DC: 80 C4 F0
        call    near INIT_PATH_BLOCK                           ;#44DF: E8 14 F0
        jnb     short DIRSW_PARSE_LETTERS                      ;#44E2: 73 05
        and     bh, 0FBh                                       ;#44E4: 80 E7 FB
        jnz     short DIRSW_PATH_ERROR                         ;#44E7: 75 1D
DIRSW_PARSE_LETTERS:
        ; W, P, A, B and the rest of CMD_SWITCH_LETTERS
        mov     di, CMD_SWITCH_LETTERS - TRANSIENT_BIAS        ;#44E9: BF 2D 0C
        mov     ax, 4C5h                                       ;#44EC: B8 C5 04
        call    near PARSE_SWITCHES                            ;#44EF: E8 B2 EC
        jb      short DIRSW_BAD_PARAM                          ;#44F2: 72 08
        jnz     short DIRSW_TOO_MANY                           ;#44F4: 75 0B
        or      [DIR_OPTION_FLAGS], ax                         ;#44F6: 09 06 63 48
        clc                                                    ;#44FA: F8
        ret                                                    ;#44FB: C3

DIRSW_BAD_PARAM:
        ; A letter DIR does not take
        mov     dx, MSG_PARAMETRO_INVALIDO - TRANSIENT_BIAS    ;#44FC: BA 84 01
        stc                                                    ;#44FF: F9
        ret                                                    ;#4500: C3

DIRSW_TOO_MANY:
        ; More names than DIR accepts
        mov     dx, MSG_NUMERO_DE_PARAMETROS_INVALIDO - TRANSIENT_BIAS ;#4501: BA 5C 01
        stc                                                    ;#4504: F9
        ret                                                    ;#4505: C3

DIRSW_PATH_ERROR:
        ; Pick the message BH's bits ask for
        mov     dx, MSG_UNIDADE_INVALIDA - TRANSIENT_BIAS      ;#4506: BA 41 01
        test    bh, 1                                          ;#4509: F6 C7 01
        jnz     short DIRSW_FAIL                               ;#450C: 75 13
        mov     dx, MSG_CAMINHO_MUITO_LONGO - TRANSIENT_BIAS   ;#450E: BA C2 01
        test    bh, 80h                                        ;#4511: F6 C7 80
        jnz     short DIRSW_FAIL                               ;#4514: 75 0B
        mov     dx, MSG_DIRETORIO_INVALIDO - TRANSIENT_BIAS    ;#4516: BA 59 05
        test    bh, 40h                                        ;#4519: F6 C7 40
        jnz     short DIRSW_FAIL                               ;#451C: 75 03
        mov     dx, MSG_CAMINHO_INVALIDO_OU_ARQUIVO - TRANSIENT_BIAS ;#451E: BA E9 09
DIRSW_FAIL:
        ; Carry, with DX already set
        stc                                                    ;#4521: F9
        ret                                                    ;#4522: C3

DIR_SET_PAGE_SIZE:
        ; GET_VIDEO_STATE_BDA, then 17h or the wide count into DIR_PER_PAGE
        call    near GET_VIDEO_STATE_BDA                       ;#4523: E8 83 02
        test    al, 80h                                        ;#4526: A8 80
        mov     al, 17h                                        ;#4528: B0 17
        jz      short PAGESIZE_STORE_ROWS                      ;#452A: 74 02
        mov     al, 30h                                        ;#452C: B0 30
PAGESIZE_STORE_ROWS:
        ; 17h or 30h, from the video mode
        mov     [DIR_PER_PAGE], al                             ;#452E: A2 67 48
        mov     [DIR_LINES_LEFT], al                           ;#4531: A2 68 48
        mov     al, 1                                          ;#4534: B0 01
        test    word [DIR_OPTION_FLAGS], SWITCH_W              ;#4536: F7 06 63 48 00 04
        jz      short PAGESIZE_STORE_COLUMNS                   ;#453C: 74 09
        mov     al, 5                                          ;#453E: B0 05
        cmp     ah, 50h                                        ;#4540: 80 FC 50
        jz      short PAGESIZE_STORE_COLUMNS                   ;#4543: 74 02
        mov     al, 2                                          ;#4545: B0 02
PAGESIZE_STORE_COLUMNS:
        ; One name a line, or five, or two
        mov     [DIR_PER_LINE], al                             ;#4547: A2 65 48
        mov     [DIR_COL_LEFT], al                             ;#454A: A2 66 48
        xor     ax, ax                                         ;#454D: 33 C0
        mov     [DIR_FILE_COUNT], ax                           ;#454F: A3 69 48
        mov     [DIR_DIR_COUNT], ax                            ;#4552: A3 6B 48
        mov     [DIR_BYTES_LO], ax                             ;#4555: A3 6D 48
        mov     [DIR_BYTES_HI], ax                             ;#4558: A3 6F 48
        ret                                                    ;#455B: C3

SPLIT_PATH_AT_MARK:
        ; Cut the path at PB_MARK, keeping the displaced byte
        push    ds                                             ;#455C: 1E
        push    es                                             ;#455D: 06
        pop     ds                                             ;#455E: 1F
        mov     dx, di                                         ;#455F: 8B D7
        mov     di, [di+PB_MARK]                               ;#4561: 8B 7D 60
        cmp     byte [di-2], ":"                               ;#4564: 80 7D FE 3A
        jz      short SPLITPATH_CUT                            ;#4568: 74 01
        dec     di                                             ;#456A: 4F
SPLITPATH_CUT:
