        xor     al, al                                         ;#456B: 32 C0
        xchg    [di], al                                       ;#456D: 86 05
        push    ds                                             ;#456F: 1E
        push    dx                                             ;#4570: 52
        push    cs                                             ;#4571: 0E
        pop     ds                                             ;#4572: 1F
        mov     dx, MSG_DIRETORIO_DE - TRANSIENT_BIAS          ;#4573: BA 5A 03
        call    near PRINT_DOLLAR_STDOUT                       ;#4576: E8 75 F4
        pop     dx                                             ;#4579: 5A
        pop     ds                                             ;#457A: 1F
        call    near PRINT_NUL_STDOUT                          ;#457B: E8 66 F4
        call    near PROMPT_CR_LF                              ;#457E: E8 55 F5
        call    near PROMPT_CR_LF                              ;#4581: E8 52 F5
        xchg    [di], al                                       ;#4584: 86 05
        pop     ds                                             ;#4586: 1F
        ret                                                    ;#4587: C3

DIR_PRINT_NAME:
        ; The found name, padded, or the directory form when DTA_ATTR says so
        ; One entry, and which of three things it is decides both what gets counted and
        ; what gets printed.
        ;
        ; A file adds to two totals at once:
        ;
        ; 459D    mov     ax, [si+PB_DTA+DTA_SIZE_LO]
        ; add     [DIR_BYTES_LO], ax
        ; mov     ax, [si+PB_DTA+DTA_SIZE_HI]
        ; adc     [DIR_BYTES_HI], ax
        ;
        ; `add` then `adc` is the 32-bit sum REPORT_FREE_SPACE prints at the end, and
        ; directories never reach it.  A directory's size field means nothing, so the
        ; branch at 458Bh keeps it out of the arithmetic rather than adding a zero.
        ;
        ; "." and ".." are the third case, and they are printed but not counted.
        ; IS_DOT_ENTRY returns carry only for a directory that is not one of them, so
        ; `jb` at 45BDh is what reaches DIR_DIR_COUNT.  Falling past it still prints.
        ; That is why the count at the bottom of a listing is two lower than the number
        ; of directory lines above it.
        ;
        ; The switches then take away columns rather than adding them.  /A drops
        ; directories at 45AFh, as #1153 found from the search mask.  /W -- bit 400h --
        ; jumps over both DIR_PRINT_SIZE_OR_TAG and DIR_PRINT_DATE_TIME, so wide mode is
        ; not a different formatter but the same one with two calls skipped.  /P only
        ; matters after the line is out, at 45E8h.
        mov     si, PATHBLK_DIR                                ;#4588: BE 93 48
        test    byte [si+PB_DTA+DTA_ATTR], 10h                 ;#458B: F6 44 7B 10
        jnz     short DIR_ENTRY_IS_DIR                         ;#458F: 75 1E
        test    word [DIR_OPTION_FLAGS], SWITCH_S              ;#4591: F7 06 63 48 80 00
        jnz     short DIR_ENTRY_SKIPPED                        ;#4597: 75 2E
        inc     word [DIR_FILE_COUNT]                          ;#4599: FF 06 69 48
        mov     ax, [si+PB_DTA+DTA_SIZE_LO]                    ;#459D: 8B 84 80 00
        add     [DIR_BYTES_LO], ax                             ;#45A1: 01 06 6D 48
        mov     ax, [si+PB_DTA+DTA_SIZE_HI]                    ;#45A5: 8B 84 82 00
        adc     [DIR_BYTES_HI], ax                             ;#45A9: 11 06 6F 48
        jmp     short DIR_EMIT_ENTRY                           ;#45AD: EB 1D

DIR_ENTRY_IS_DIR:
        ; A subdirectory, and /A may exclude it
        test    word [DIR_OPTION_FLAGS], SWITCH_A              ;#45AF: F7 06 63 48 01 00
        jnz     short DIR_ENTRY_SKIPPED                        ;#45B5: 75 10
        add     si, PB_DTA                                     ;#45B7: 83 C6 66
        call    near IS_DOT_ENTRY                              ;#45BA: E8 77 EA
        jb      short DIR_COUNT_SUBDIR                         ;#45BD: 72 09
        test    word [DIR_OPTION_FLAGS], SWITCH_S              ;#45BF: F7 06 63 48 80 00
        jz      short DIR_EMIT_ENTRY                           ;#45C5: 74 05
DIR_ENTRY_SKIPPED:
        ; Filtered out: nothing printed, nothing counted
        ret                                                    ;#45C7: C3

DIR_COUNT_SUBDIR:
        ; Counted apart from the files
        inc     word [DIR_DIR_COUNT]                           ;#45C8: FF 06 6B 48
DIR_EMIT_ENTRY:
        ; Column gap, then size and date unless /W
        call    near DIR_COLUMN_GAP                            ;#45CC: E8 1D 00
        test    word [DIR_OPTION_FLAGS], SWITCH_W              ;#45CF: F7 06 63 48 00 04
        jnz     short DIR_AFTER_DETAILS                        ;#45D5: 75 06
        call    near DIR_PRINT_SIZE_OR_TAG                     ;#45D7: E8 72 00
        call    near DIR_PRINT_DATE_TIME                       ;#45DA: E8 8B 00
DIR_AFTER_DETAILS:
        ; Move to the next column
        call    near DIR_COLUMN_STEP                           ;#45DD: E8 F5 00
        test    word [DIR_OPTION_FLAGS], SWITCH_P              ;#45E0: F7 06 63 48 40 00
        jz      short DIR_ENTRY_DONE                           ;#45E6: 74 03
        call    near DIR_PAGE_CHECK                            ;#45E8: E8 FE 00
DIR_ENTRY_DONE:
        ; Printed, and the page counter is up to date
        ret                                                    ;#45EB: C3

DIR_COLUMN_GAP:
        ; Two spaces, unless this entry is starting a fresh line
        mov     dx, MSG_TWO_SPACES - TRANSIENT_BIAS            ;#45EC: BA 31 05
        mov     al, [DIR_PER_LINE]                             ;#45EF: A0 65 48
        cmp     [DIR_COL_LEFT], al                             ;#45F2: 38 06 66 48
        jz      short DIRCOL_PRINT_GAP                         ;#45F6: 74 03
        mov     dx, MSG_4_SPACES - TRANSIENT_BIAS              ;#45F8: BA 87 03
DIRCOL_PRINT_GAP:
        ; Two spaces mid-line, four at the start
        call    near PRINT_DOLLAR_STDOUT                       ;#45FB: E8 F0 F3
        lea     si, [DIR_DTA+DTA_NAME]                         ;#45FE: 8D 36 17 49
        mov     di, DIR_NAME_FIELD                             ;#4602: BF 71 48
        cmp     byte [si], "."                                 ;#4605: 80 3C 2E
        jnz     short DIRCOL_NAME_AND_EXT                      ;#4608: 75 0A
        mov     cx, 0Ch                                        ;#460A: B9 0C 00
        xor     ax, ax                                         ;#460D: 33 C0
        call    near COPY_PADDED_FIELD                         ;#460F: E8 23 00
        jmp     short DIRCOL_EMIT_FIELD                        ;#4612: EB 1B

DIRCOL_NAME_AND_EXT:
        ; Eight characters, then three
        mov     cx, 8                                          ;#4614: B9 08 00
        mov     ah, 2Eh                                        ;#4617: B4 2E
        mov     al, 0                                          ;#4619: B0 00
        call    near COPY_PADDED_FIELD                         ;#461B: E8 17 00
        lodsb                                                  ;#461E: AC
        cmp     al, ah                                         ;#461F: 3A C4
        jz      short DIRCOL_SPACE_BEFORE_EXT                  ;#4621: 74 01
        dec     si                                             ;#4623: 4E
DIRCOL_SPACE_BEFORE_EXT:
        ; One space where the dot would be
        mov     al, " "                                        ;#4624: B0 20
        stosb                                                  ;#4626: AA
        xor     ax, ax                                         ;#4627: 33 C0
        mov     cx, 3                                          ;#4629: B9 03 00
        call    near COPY_PADDED_FIELD                         ;#462C: E8 06 00
DIRCOL_EMIT_FIELD:
        ; The whole twelve-character field at once
        mov     dx, DIR_NAME_FIELD                             ;#462F: BA 71 48
        jmp     near PRINT_NUL_STDOUT_RAW                      ;#4632: E9 A5 F3

COPY_PADDED_FIELD:
        ; Copy until AH or AL, then pad with spaces — a DIR column
        cmp     [si], ah                                       ;#4635: 38 24
        jz      short PADDED_FILL_REST                         ;#4637: 74 09
        cmp     [si], al                                       ;#4639: 38 04
        jz      short PADDED_FILL_REST                         ;#463B: 74 05
        movsb                                                  ;#463D: A4
        loop    COPY_PADDED_FIELD                              ;#463E: E2 F5
        jmp     short PADDED_WRITE_TERMINATOR                  ;#4640: EB 06

PADDED_FILL_REST:
        ; Nothing left to copy: blanks to the end
        push    ax                                             ;#4642: 50
        mov     al, " "                                        ;#4643: B0 20
        rep     stosb                                          ;#4645: F3 AA
        pop     ax                                             ;#4647: 58
PADDED_WRITE_TERMINATOR:
        ; AL closes the field, and it may be a NUL
        mov     [es:di], al                                    ;#4648: 26 88 05
        ret                                                    ;#464B: C3

DIR_PRINT_SIZE_OR_TAG:
        ; The size, or MSG_DIR when the entry is a directory
        mov     si, PATHBLK_DIR                                ;#464C: BE 93 48
        test    byte [si+PB_DTA+DTA_ATTR], 10h                 ;#464F: F6 44 7B 10
        jz      short DIRSIZE_PRINT_BYTES                      ;#4653: 74 06
        mov     dx, MSG_DIR - TRANSIENT_BIAS                   ;#4655: BA 6B 03
        jmp     near PRINT_DOLLAR_STDOUT                       ;#4658: E9 93 F3

DIRSIZE_PRINT_BYTES:
        ; Not a directory, so the size in decimal
        mov     di, [si+PB_DTA+DTA_SIZE_HI]                    ;#465B: 8B BC 82 00
        mov     si, [si+PB_DTA+DTA_SIZE_LO]                    ;#465F: 8B B4 80 00
        mov     ah, 9                                          ;#4663: B4 09
        jmp     near PUT_DECIMAL                               ;#4665: E9 13 EC

DIR_PRINT_DATE_TIME:
        ; PATHBLK_DIR's DTA_DATE, skipped when it is zero
        ; Unpacking the two words DOS packs a timestamp into, straight into the text
        ; buffer.
        ;
        ; The year is the tidy part.  DOS counts from 1980 and the field wants two
        ; digits:
        ;
        ; 469A    mov     al, dh
        ; shr     al, 1
        ; add     al, 50h
        ; cmp     al, 64h
        ; jb      short DATETIME_PUT_YEAR
        ; sub     al, 64h
        ;
        ; The date word keeps the year in its top seven bits, so DH shifted once is
        ; years-since-1980.  50h is 80 and 64h is 100, both decimal quantities living in
        ; a binary register: add 80 to get years-since-1900, and take 100 off again if
        ; that reached three digits.  1999 prints 99 and 2000 prints 00, without anything
        ; knowing what century it is.
        ;
        ; The time is unpacked without a single mask:
        ;
        ; 46B3    shr     bx, 1
        ; shr     bx, 1
        ; shr     bx, 1
        ; shr     bl, 1
        ; shr     bl, 1
        ;
        ; Three shifts of the pair put the hours -- the top five bits -- into BH on their
        ; own, and two more of BL alone leave the minutes there.  Two fields out of one
        ; word in five instructions, because the field widths happen to let the register
        ; boundary do the masking.
        ;
        ; Seconds are never printed, which is why the five bits below the minutes are
        ; simply shifted away rather than extracted.  A zero date returns at 4672h before
        ; any of this, so an entry with no timestamp gets no columns rather than
        ; "00-Jan-80".
        mov     si, PATHBLK_DIR                                ;#4668: BE 93 48
        mov     dx, [si+PB_DTA+DTA_DATE]                       ;#466B: 8B 54 7E
        or      dx, dx                                         ;#466E: 0B D2
        jnz     short DATETIME_BUILD_DATE                      ;#4670: 75 01
        ret                                                    ;#4672: C3

DATETIME_BUILD_DATE:
        ; Day, month abbreviation, then the year
        mov     di, DIR_SIZE_FIELD                             ;#4673: BF 7E 48
        mov     al, " "                                        ;#4676: B0 20
        stosb                                                  ;#4678: AA
        mov     ax, dx                                         ;#4679: 8B C2
        mov     bh, 10h                                        ;#467B: B7 10
        and     al, 1Fh                                        ;#467D: 24 1F
        call    near PUT_TWO_DIGITS                            ;#467F: E8 E8 EB
        mov     al, "-"                                        ;#4682: B0 2D
        stosb                                                  ;#4684: AA
        mov     ax, dx                                         ;#4685: 8B C2
        mov     cl, 5                                          ;#4687: B1 05
        shr     ax, cl                                         ;#4689: D3 E8
        and     al, 0Fh                                        ;#468B: 24 0F
        dec     al                                             ;#468D: FE C8
        push    si                                             ;#468F: 56
        mov     si, MONTH_ABBREV - TRANSIENT_BIAS              ;#4690: BE 48 06
        call    near COPY_3CHAR_ENTRY                          ;#4693: E8 CA EB
        pop     si                                             ;#4696: 5E
        mov     al, "-"                                        ;#4697: B0 2D
        stosb                                                  ;#4699: AA
        mov     al, dh                                         ;#469A: 8A C6
        shr     al, 1                                          ;#469C: D0 E8
        add     al, 50h                                        ;#469E: 04 50
        cmp     al, 64h                                        ;#46A0: 3C 64
        jb      short DATETIME_PUT_YEAR                        ;#46A2: 72 02
        sub     al, 64h                                        ;#46A4: 2C 64
DATETIME_PUT_YEAR:
        ; Two digits, wrapped past 2000
        call    near PUT_TWO_DIGITS                            ;#46A6: E8 C1 EB
        mov     bx, [si+PB_DTA+DTA_TIME]                       ;#46A9: 8B 5C 7C
        or      bx, bx                                         ;#46AC: 0B DB
        jz      short DATETIME_TERMINATE                       ;#46AE: 74 1C
        mov     al, " "                                        ;#46B0: B0 20
        stosb                                                  ;#46B2: AA
        shr     bx, 1                                          ;#46B3: D1 EB
        shr     bx, 1                                          ;#46B5: D1 EB
        shr     bx, 1                                          ;#46B7: D1 EB
        shr     bl, 1                                          ;#46B9: D0 EB
        shr     bl, 1                                          ;#46BB: D0 EB
        mov     al, bh                                         ;#46BD: 8A C7
        mov     bh, 10h                                        ;#46BF: B7 10
        call    near PUT_TWO_DIGITS                            ;#46C1: E8 A6 EB
        mov     al, ":"                                        ;#46C4: B0 3A
        stosb                                                  ;#46C6: AA
        mov     al, bl                                         ;#46C7: 8A C3
        call    near PUT_TWO_DIGITS                            ;#46C9: E8 9E EB
DATETIME_TERMINATE:
        ; No time recorded, or it is written
        xor     al, al                                         ;#46CC: 32 C0
        stosb                                                  ;#46CE: AA
        mov     dx, DIR_SIZE_FIELD                             ;#46CF: BA 7E 48
        jmp     near PRINT_NUL_STDOUT                          ;#46D2: E9 0F F3

DIR_COLUMN_STEP:
        ; Step DIR_COL_LEFT; at zero reload it, newline, and step the page
        dec     byte [DIR_COL_LEFT]                            ;#46D5: FE 0E 66 48
        jnz     short COLUMNSTEP_RETURN                        ;#46D9: 75 0D
        mov     al, [DIR_PER_LINE]                             ;#46DB: A0 65 48
        mov     [DIR_COL_LEFT], al                             ;#46DE: A2 66 48
        call    near PROMPT_CR_LF                              ;#46E1: E8 F2 F3
        dec     byte [DIR_LINES_LEFT]                          ;#46E4: FE 0E 68 48
COLUMNSTEP_RETURN:
        ; Room in this line, or a new one started
        ret                                                    ;#46E8: C3

DIR_PAGE_CHECK:
        ; At DIR_LINES_LEFT zero, reload and go to WAIT_FOR_KEY
        cmp     byte [DIR_LINES_LEFT], 0                       ;#46E9: 80 3E 68 48 00
        jz      short PAGECHECK_WAIT                           ;#46EE: 74 01
        ret                                                    ;#46F0: C3

PAGECHECK_WAIT:
        ; Page full: reset the count and wait for a key
        mov     al, [DIR_PER_PAGE]                             ;#46F1: A0 67 48
        mov     [DIR_LINES_LEFT], al                           ;#46F4: A2 68 48
        jmp     near WAIT_FOR_KEY                              ;#46F7: E9 77 09

DIR_END_LINE:
        ; Newline unless the column is already the first, then step the page
        mov     al, [DIR_COL_LEFT]                             ;#46FA: A0 66 48
        cmp     al, [DIR_PER_LINE]                             ;#46FD: 3A 06 65 48
        jz      short ENDLINE_RETURN                           ;#4701: 74 07
        dec     byte [DIR_LINES_LEFT]                          ;#4703: FE 0E 68 48
        call    near PROMPT_CR_LF                              ;#4707: E8 CC F3
ENDLINE_RETURN:
        ; The line was empty, or it has been closed
        ret                                                    ;#470A: C3

DIR_MAYBE_FREE_SPACE:
        ; REPORT_FREE_SPACE unless a DIR_OPTION_FLAGS bit says not to
        test    word [DIR_OPTION_FLAGS], SWITCH_C              ;#470B: F7 06 63 48 04 00
        jz      short REPORT_FREE_SPACE                        ;#4711: 74 01
        ret                                                    ;#4713: C3

REPORT_FREE_SPACE:
        ; DIR's summary: counts, then AH=36h turned into Kbytes
        ; The three lines DIR ends with, and each is gated separately.
        ;
        ; /P pauses first, but only if the pause would otherwise be wasted:
        ;
        ; 4714    test    word [DIR_OPTION_FLAGS], SWITCH_P
        ; jz      short TOTALS_COUNT_FILES
        ; cmp     byte [DIR_LINES_LEFT], 2
        ; jnbe    short TOTALS_COUNT_FILES
        ; call    near WAIT_FOR_KEY
        ;
        ; With three or more lines still on the page the summary fits and nothing stops.
        ; The check is for the page ending mid-summary, not for the summary itself.
        ;
        ; Singular and plural are two separate messages, chosen by comparing the count
        ; with 1 -- MSG_ARQUIVO_SINGULAR against MSG_ARQUIVOS, and the same pair for
        ; directories.  No suffix logic, no conditional 's': the text that reads properly
        ; is simply stored twice.
        ;
        ; The free space is three multiplies deep and drops a word on purpose:
        ;
        ; 4785    mov     ah, 36h
        ; mov     dl, [PATHBLK_DIR+PB_DRIVE_USED]
        ; int     21h
        ; mul     cx
        ; mul     bx
        ;
        ; AH=36h hands back sectors per cluster in AX, bytes per sector in CX and free
        ; clusters in BX.  The first `mul` makes bytes per cluster and the second
        ; multiplies that by the free count -- but `mul bx` reads only AX, so the high
        ; word of the first product is discarded.  Losing it only matters if a
        ; cluster reached 10000h bytes, which no volume this DOS can format does, so the
        ; word thrown away is always zero.
        ;
        ; Kbytes then come from ten shifts rather than a divide, and PUT_DECIMAL is
        ; called with three different widths -- 6 for the counts, 0Ah for the byte total,
        ; 8 for the Kbytes -- which is the only thing that lines the three lines up.
        test    word [DIR_OPTION_FLAGS], SWITCH_P              ;#4714: F7 06 63 48 40 00
        jz      short TOTALS_COUNT_FILES                       ;#471A: 74 0A
        cmp     byte [DIR_LINES_LEFT], 2                       ;#471C: 80 3E 68 48 02
        jnbe    short TOTALS_COUNT_FILES                       ;#4721: 77 03
        call    near WAIT_FOR_KEY                              ;#4723: E8 4B 09
TOTALS_COUNT_FILES:
        ; Unless /B, print how many files and bytes
        test    word [DIR_OPTION_FLAGS], SWITCH_S              ;#4726: F7 06 63 48 80 00
        jnz     short TOTALS_COUNT_DIRS                        ;#472C: 75 31
        mov     si, [DIR_FILE_COUNT]                           ;#472E: 8B 36 69 48
        xor     di, di                                         ;#4732: 33 FF
        mov     ah, 6                                          ;#4734: B4 06
        call    near PUT_DECIMAL                               ;#4736: E8 42 EB
        mov     dx, MSG_ARQUIVOS - TRANSIENT_BIAS              ;#4739: BA 96 03
        cmp     word [DIR_FILE_COUNT], 1                       ;#473C: 83 3E 69 48 01
        jnz     short TOTALS_PRINT_FILE_WORD                   ;#4741: 75 03
        mov     dx, MSG_ARQUIVO_SINGULAR - TRANSIENT_BIAS      ;#4743: BA 8C 03
TOTALS_PRINT_FILE_WORD:
        ; Singular or plural, whichever DX now holds
        call    near PRINT_DOLLAR_STDOUT                       ;#4746: E8 A5 F2
        mov     si, [DIR_BYTES_LO]                             ;#4749: 8B 36 6D 48
        mov     di, [DIR_BYTES_HI]                             ;#474D: 8B 3E 6F 48
        mov     ah, 0Ah                                        ;#4751: B4 0A
        call    near PUT_DECIMAL                               ;#4753: E8 25 EB
        mov     dx, MSG_BYTES - TRANSIENT_BIAS                 ;#4756: BA C9 03
        call    near PRINT_DOLLAR_STDOUT                       ;#4759: E8 92 F2
        call    near PROMPT_CR_LF                              ;#475C: E8 77 F3
TOTALS_COUNT_DIRS:
        ; And how many subdirectories, unless /W
        mov     dx, MSG_17_SPACES - TRANSIENT_BIAS             ;#475F: BA 75 03
        test    word [DIR_OPTION_FLAGS], SWITCH_A              ;#4762: F7 06 63 48 01 00
        jnz     short TOTALS_PRINT_DIR_WORD                    ;#4768: 75 18
        mov     si, [DIR_DIR_COUNT]                            ;#476A: 8B 36 6B 48
        xor     di, di                                         ;#476E: 33 FF
        mov     ah, 6                                          ;#4770: B4 06
        call    near PUT_DECIMAL                               ;#4772: E8 06 EB
        mov     dx, MSG_DIRETORIOS - TRANSIENT_BIAS            ;#4775: BA AC 03
        cmp     word [DIR_DIR_COUNT], 1                        ;#4778: 83 3E 6B 48 01
        jnz     short TOTALS_PRINT_DIR_WORD                    ;#477D: 75 03
        mov     dx, MSG_DIRETORIO_SINGULAR - TRANSIENT_BIAS    ;#477F: BA A0 03
TOTALS_PRINT_DIR_WORD:
        ; Then AH=36h for the free space
        call    near PRINT_DOLLAR_STDOUT                       ;#4782: E8 69 F2
        mov     ah, 36h                                        ;#4785: B4 36
        mov     dl, [PATHBLK_DIR+PB_DRIVE_USED]                ;#4787: 8A 16 F2 48
        int     21h                                            ;#478B: CD 21
        mul     cx                                             ;#478D: F7 E1
        mul     bx                                             ;#478F: F7 E3
        mov     di, dx                                         ;#4791: 8B FA
        mov     si, ax                                         ;#4793: 8B F0
        mov     cx, 0Ah                                        ;#4795: B9 0A 00
TOTALS_DIVIDE_BY_1K:
        ; Ten shifts turn the byte count into kilobytes
        shr     di, 1                                          ;#4798: D1 EF
        rcr     si, 1                                          ;#479A: D1 DE
        loop    TOTALS_DIVIDE_BY_1K                            ;#479C: E2 FA
        mov     ah, 8                                          ;#479E: B4 08
        call    near PUT_DECIMAL                               ;#47A0: E8 D8 EA
        mov     dx, MSG_KBYTES_LIVRES - TRANSIENT_BIAS         ;#47A3: BA B8 03
        jmp     near PRINT_DOLLAR_STDOUT                       ;#47A6: E9 45 F2

GET_VIDEO_STATE_BDA:
