        push    es                                             ;#47A9: 06
        mov     ax, 40h                                        ;#47AA: B8 40 00
        mov     es, ax                                         ;#47AD: 8E C0
        mov     ah, [es:BDA_CRT_COLS]                          ;#47AF: 26 8A 26 4A 00
        mov     al, [es:BDA_CRT_MODE]                          ;#47B4: 26 A0 49 00
        mov     bh, [es:BDA_ACTIVE_PAGE]                       ;#47B8: 26 8A 3E 62 00
        pop     es                                             ;#47BD: 07
        ret                                                    ;#47BE: C3

CMD_SUPRIME:
        ; The ERASE command (aliases ERA, SUPRIME, SUP, DEL)
        ; The mask is 0D0h -- bits 4, 6 and 7, so /L /P /S -- and PARSE_SWITCHES runs
        ; twice, at 47C7h and again at 47F6h with `or [ERASE_OPTION_FLAGS], ax`, so a
        ; switch is taken on either side of the name.
        ;
        ; There are two ways to delete, and 4850h picks between them:
        ;
        ; 4850    test    word [ERASE_OPTION_FLAGS], 50h
        ; jnz     short ERASE_ONE_AT_A_TIME   ; /L or /P: per-file work
        ; mov     bl, [PATHBLK_DIR+PB_DRIVE_USED]
        ; mov     ax, 4409h
        ; int     21h
        ; test    dx, 1000h
        ; jnz     short ERASE_ONE_AT_A_TIME   ; remote drive
        ;
        ; 4867    mov     dx, PATHBLK_DIR
        ; mov     cx, 20h
        ; mov     ax, 41AAh
        ; int     21h
        ;
        ; The fast path hands the wildcard straight to AH=41h and lets the file system
        ; expand it; /L has to print each name and /P has to ask about each, so both
        ; force the loop at 487Ch, which finds with AH=4Eh/4Fh and deletes one name at a
        ; time with AX=4100h.
        ;
        ; The AL bytes differ -- AAh here, 00h at 48CDh -- but they mean nothing.
        ; DOS_FN_41_DELETE_FILE in SISNE.SIS takes only DS:DX (compiled/, and the C reads
        ; rec->r_ds and rec->r_dx and nothing else), so AL and the CX=20h are both inert.
        ; The two calls are the same call; what differs is that one is given a wildcard
        ; and the other a single name that COPY_TO_NUL just built at PB_MARK.
        ;
        ; That also explains the 4409h test.  Wildcard expansion inside AH=41h is the
        ; file system's own work, and a redirector serving a network drive does not do
        ; it, so a remote drive falls back to the loop that only ever asks for one name.
        ;
        ; Two smaller things.  The slow path checks the read-only bit itself at 48C3h and
        ; prints MSG_ACESSO_NAO_PERMITIDO rather than letting the delete fail, while the
        ; fast path can only map error 5 back to the same message afterwards at 4874h.
        ; And ERASE_PATH_ERROR reads four different messages out of the BH bits the path
        ; block returned: bit 0 invalid drive, bit 7 path too long, bit 6 invalid path,
        ; and none of them set means invalid path or file name.
        mov     si, bp                                         ;#47BF: 8B F5
        mov     di, CMD_SWITCH_LETTERS - TRANSIENT_BIAS        ;#47C1: BF 2D 0C
        mov     ax, 0D0h                                       ;#47C4: B8 D0 00
        call    near PARSE_SWITCHES                            ;#47C7: E8 DA E9
        jb      short ERASE_BAD_PARAM                          ;#47CA: 72 6F
        jz      short ERASE_TOO_MANY                           ;#47CC: 74 72
        mov     [ERASE_OPTION_FLAGS], ax                       ;#47CE: A3 91 48
        mov     di, PATHBLK_DIR                                ;#47D1: BF 93 48
        mov     ah, 24h                                        ;#47D4: B4 24
        call    near INIT_PATH_BLOCK                           ;#47D6: E8 1D ED
        jb      short ERASE_PATH_ERROR                         ;#47D9: 72 43
        mov     bh, [PATHBLK_DIR+PB_DONE]                      ;#47DB: 8A 3E EE 48
        test    bh, 80h                                        ;#47DF: F6 C7 80
        jnz     short ERASE_NOT_FOUND                          ;#47E2: 75 61
        test    bl, 80h                                        ;#47E4: F6 C3 80
        jnz     short ERASE_NOT_FOUND                          ;#47E7: 75 5C
        cmp     byte [PATHBLK_DIR+PB_WAS_ABSOLUTE], 0          ;#47E9: 80 3E F1 48 00
        jz      short ERASE_TOO_MANY                           ;#47EE: 74 50
        mov     di, CMD_SWITCH_LETTERS - TRANSIENT_BIAS        ;#47F0: BF 2D 0C
        mov     ax, 0D0h                                       ;#47F3: B8 D0 00
        call    near PARSE_SWITCHES                            ;#47F6: E8 AB E9
        jb      short ERASE_BAD_PARAM                          ;#47F9: 72 40
        jnz     short ERASE_TOO_MANY                           ;#47FB: 75 43
        or      [ERASE_OPTION_FLAGS], ax                       ;#47FD: 09 06 91 48
        test    bh, 48h                                        ;#4801: F6 C7 48
        jz      short ERASE_PICK_METHOD                        ;#4804: 74 4A
        test    word [ERASE_OPTION_FLAGS], SWITCH_P            ;#4806: F7 06 91 48 40 00
        jnz     short ERASE_PICK_METHOD                        ;#480C: 75 42
        mov     di, [PATHBLK_DIR+PB_MARK]                      ;#480E: 8B 3E F3 48
        mov     ax, [ERASE_OPTION_FLAGS]                       ;#4812: A1 91 48
        and     ax, 80h                                        ;#4815: 25 80 00
        call    near CONFIRM_ERASE_ALL                         ;#4818: E8 C6 00
        jnb     short ERASE_PICK_METHOD                        ;#481B: 73 33
        ret                                                    ;#481D: C3

ERASE_PATH_ERROR:
        ; Decode the path-block error bits in BH into one of four messages
        mov     dx, MSG_UNIDADE_INVALIDA - TRANSIENT_BIAS      ;#481E: BA 41 01
        test    bh, 1                                          ;#4821: F6 C7 01
        jnz     short ERASE_REPORT                             ;#4824: 75 27
        mov     dx, MSG_CAMINHO_MUITO_LONGO - TRANSIENT_BIAS   ;#4826: BA C2 01
        test    bh, 80h                                        ;#4829: F6 C7 80
        jnz     short ERASE_REPORT                             ;#482C: 75 1F
        mov     dx, MSG_CAMINHO_INVALIDO - TRANSIENT_BIAS      ;#482E: BA A1 06
        test    bh, 40h                                        ;#4831: F6 C7 40
        jnz     short ERASE_REPORT                             ;#4834: 75 17
        mov     dx, MSG_CAMINHO_INVALIDO_OU_ARQUIVO - TRANSIENT_BIAS ;#4836: BA E9 09
        jmp     short ERASE_REPORT                             ;#4839: EB 12

ERASE_BAD_PARAM:
        ; A letter ERASE does not take
        mov     dx, MSG_PARAMETRO_INVALIDO - TRANSIENT_BIAS    ;#483B: BA 84 01
        jmp     short ERASE_REPORT                             ;#483E: EB 0D

ERASE_TOO_MANY:
        ; More names than ERASE accepts
        mov     dx, MSG_NUMERO_DE_PARAMETROS_INVALIDO - TRANSIENT_BIAS ;#4840: BA 5C 01
        jmp     short ERASE_REPORT                             ;#4843: EB 08

ERASE_NOT_FOUND:
        ; Nothing matched, or the search ran out
        mov     dx, MSG_ARQUIVO_NAO_ENCONTRADO - TRANSIENT_BIAS ;#4845: BA A1 01
        jmp     short ERASE_REPORT                             ;#4848: EB 03

ERASE_ACCESS_DENIED:
        ; Read-only, or the path is a directory
        mov     dx, MSG_ACESSO_NAO_PERMITIDO - TRANSIENT_BIAS  ;#484A: BA 06 02
ERASE_REPORT:
        ; Whatever DX was set to, on the way out
        jmp     near CMD_ERROR_EXIT                            ;#484D: E9 99 E6

ERASE_PICK_METHOD:
        ; /L or /P, or a remote drive, forces the one-at-a-time loop
        test    word [ERASE_OPTION_FLAGS], 50h                 ;#4850: F7 06 91 48 50 00
        jnz     short ERASE_ONE_AT_A_TIME                      ;#4856: 75 24
        mov     bl, [PATHBLK_DIR+PB_DRIVE_USED]                ;#4858: 8A 1E F2 48
        mov     ax, 4409h                                      ;#485C: B8 09 44
        int     21h                                            ;#485F: CD 21
        test    dx, 1000h                                      ;#4861: F7 C2 00 10
        jnz     short ERASE_ONE_AT_A_TIME                      ;#4865: 75 15
ERASE_DELETE_ALL_AT_ONCE:
        ; One AH=41h with the wildcard still in it — SISNE.SIS walks the matches
        mov     dx, PATHBLK_DIR                                ;#4867: BA 93 48
        mov     cx, 20h                                        ;#486A: B9 20 00
        mov     ax, 41AAh                                      ;#486D: B8 AA 41
        int     21h                                            ;#4870: CD 21
        jnb     short ERASEALL_RETURN                          ;#4872: 73 07
        cmp     ax, 5                                          ;#4874: 3D 05 00
        jz      short ERASE_ACCESS_DENIED                      ;#4877: 74 D1
        jmp     short ERASE_NOT_FOUND                          ;#4879: EB CA

ERASEALL_RETURN:
        ; Deleted, or DX says why not
        ret                                                    ;#487B: C3

ERASE_ONE_AT_A_TIME:
        ; AH=4Eh/4Fh loop, deleting each match on its own with AX=4100h
        mov     dx, PATHBLK_DIR                                ;#487C: BA 93 48
        mov     cx, 20h                                        ;#487F: B9 20 00
        mov     ah, 4Eh                                        ;#4882: B4 4E
        int     21h                                            ;#4884: CD 21
        jb      short ERASE_NOT_FOUND                          ;#4886: 72 BD
ERASE_TAKE_MATCH:
        ; Splice the found name onto the path
        lea     si, [DIR_DTA+DTA_NAME]                         ;#4888: 8D 36 17 49
        mov     di, [PATHBLK_DIR+PB_MARK]                      ;#488C: 8B 3E F3 48
        call    near COPY_TO_NUL                               ;#4890: E8 1A E7
        test    word [ERASE_OPTION_FLAGS], SWITCH_P            ;#4893: F7 06 91 48 40 00
        jz      short ERASE_MAYBE_ECHO                         ;#4899: 74 14
        call    near PUT_TWO_SPACES                            ;#489B: E8 60 F2
        mov     dx, PATHBLK_DIR                                ;#489E: BA 93 48
        call    near PRINT_NUL_STDOUT                          ;#48A1: E8 40 F1
        mov     dx, MSG_ASK_NS - TRANSIENT_BIAS                ;#48A4: BA E5 01
        call    near PRINT_NUL_STDOUT                          ;#48A7: E8 3A F1
        call    near ASK_YES_NO                                ;#48AA: E8 63 02
        jb      short ERASE_NEXT_MATCH                         ;#48AD: 72 2B
ERASE_MAYBE_ECHO:
        ; /L prints each name as it goes
        test    word [ERASE_OPTION_FLAGS], SWITCH_L            ;#48AF: F7 06 91 48 10 00
        jz      short ERASE_DO_DELETE                          ;#48B5: 74 0C
        call    near PUT_TWO_SPACES                            ;#48B7: E8 44 F2
        mov     dx, PATHBLK_DIR                                ;#48BA: BA 93 48
        call    near PRINT_NUL_STDOUT                          ;#48BD: E8 24 F1
        call    near PROMPT_CR_LF                              ;#48C0: E8 13 F2
ERASE_DO_DELETE:
        ; AH=41h, unless the read-only bit is set
        test    byte [DIR_DTA+DTA_ATTR], 1                     ;#48C3: F6 06 0E 49 01
        jnz     short ERASE_READ_ONLY                          ;#48C8: 75 0A
        mov     dx, PATHBLK_DIR                                ;#48CA: BA 93 48
        mov     ax, 4100h                                      ;#48CD: B8 00 41
        int     21h                                            ;#48D0: CD 21
        jnb     short ERASE_NEXT_MATCH                         ;#48D2: 73 06
ERASE_READ_ONLY:
        ; Say so and carry on with the next
        mov     dx, MSG_ACESSO_NAO_PERMITIDO - TRANSIENT_BIAS  ;#48D4: BA 06 02
        call    near PRINT_DOLLAR_STDERR                       ;#48D7: E8 23 F1
ERASE_NEXT_MATCH:
        ; AH=4Fh for whatever else matches
        mov     ah, 4Fh                                        ;#48DA: B4 4F
        int     21h                                            ;#48DC: CD 21
        jnb     short ERASE_TAKE_MATCH                         ;#48DE: 73 A8
        ret                                                    ;#48E0: C3

CONFIRM_ERASE_ALL:
        ; "*.*" always asks; anything else asks only if 1817h says to
        ; Whether ERASE asks before it deletes.
        ;
        ; 48E1    cmp     word [di], 2E2Ah        ; "*." ...
        ; jnz     short CONFIRM_CHECK_OPTION
        ; cmp     word [di+2], 2Ah        ; ..."*" and its NUL
        ; jz      short CONFIRM_ASK             ; "*.*" always asks
        ; 48ED    or      ax, ax
        ; jnz     short CONFIRM_RETURN             ; /S given: never asks
        ; mov     dl, 0
        ; mov     ax, 1817h
        ; int     21h
        ; or      al, al
        ; jz      short CONFIRM_RETURN
        ;
        ; So there are three answers and only the middle one is a setting: "*.*" asks
        ; whatever the setting says, /S suppresses the question outright, and everything
        ; else defers to the byte AX=1817h reports.
        ;
        ; That byte is worth being careful about.  Its name here and in SISNE.SIS says
        ; FCBS per file, and nothing supports it.  Every reader found so far is about
        ; interaction: this prompt, COPY's "destruir?" at 5E19h, and the CMD_OPTIONS
        ; command that turns it on and off.  SISNE.SIS keeps it at 1BFh, sets it from the
        ; OPTIONS= line in CONFIG, and its compiled routines consult it for whether a
        ; live cursor is showing -- backspace_last_char and process_typed_char both
        ; branch on it.  A file-control-block count is the one thing it is not.
        ;
        ; This label is renamed, since command_com used it once.  The shared symbol took
        ; a cycle of its own: it is CFG_OPTIONS_ON now, along with three more that were
        ; named after the wrong CONFIG directive, and the handler SISNE.SIS reaches it
        ; through is GET_SET_OPTIONS_FLAG.
        cmp     word [di], 2E2Ah                               ;#48E1: 81 3D 2A 2E
        jnz     short CONFIRM_CHECK_OPTION                     ;#48E5: 75 06
        cmp     word [di+2], 2Ah                               ;#48E7: 83 7D 02 2A
        jz      short CONFIRM_ASK                              ;#48EB: 74 0F
CONFIRM_CHECK_OPTION:
        ; Not *.*, so only ask if 1817h says to
        or      ax, ax                                         ;#48ED: 0B C0
        jnz     short CONFIRM_RETURN                           ;#48EF: 75 14
        mov     dl, 0                                          ;#48F1: B2 00
        mov     ax, 1817h                                      ;#48F3: B8 17 18
        int     21h                                            ;#48F6: CD 21
        or      al, al                                         ;#48F8: 0A C0
        jz      short CONFIRM_RETURN                           ;#48FA: 74 09
CONFIRM_ASK:
        ; 'Todos os arquivos...' and wait for N or S
        mov     dx, MSG_TODOS_OS_ARQUIVOS_DEVEM - TRANSIENT_BIAS ;#48FC: BA 25 02
        call    near PRINT_DOLLAR_STDOUT                       ;#48FF: E8 EC F0
        call    near ASK_YES_NO                                ;#4902: E8 0B 02
CONFIRM_RETURN:
        ; Zero flag carries the answer up
        ret                                                    ;#4905: C3

CMD_RENOMEIA:
        ; The RENAME command — the destination inherits the source's path
        ; The destination is built from the source and then edited, not parsed fresh:
        ;
        ; 4920    mov     di, DEST_NAME_BUF
        ; push    di
        ; mov     si, CURRENT_NAME_BUF
        ; call    near COPY_NUL_KEEP_SI
        ; pop     di
        ; call    near FIND_NAME_IN_PATH
        ; mov     [FILEOP_DEST_POS], di
        ;
        ; The whole source path is copied over, then FIND_NAME_IN_PATH walks to where its
        ; last component starts and parks FILEOP_DEST_POS there.  Everything the second
        ; argument supplies lands on that offset, so the directory comes from the source
        ; and only the name is replaced -- which is what makes `REN A:\SUB\OLD.TXT
        ; NEW.TXT` put NEW.TXT in A:\SUB and not in the current directory.
        ;
        ; Drives are then compared, but only after making them agree when they can:
        ;
        ; 4972    test    byte [ARG_FLAGS], ARG_HAS_DRIVE
        ; jnz     short RENOMEIA_COMPARE_DRIVE
        ; mov     al, [si]
        ; mov     [di], al
        ; 497D    mov     al, [si]
        ; cmp     al, [di]
        ; mov     dx, MSG_UNIDADE_INVALIDA - TRANSIENT_BIAS
        ; jnz     short FILEOP_FAIL
        ;
        ; A new name with no drive of its own gets the source's copied in, so the
        ; comparison it then fails is only reachable when the user named a different
        ; drive on purpose.  AH=56h cannot move a file between drives, and this is where
        ; that becomes "Unidade inválida" rather than a DOS error code.
        ;
        ; The new name is parsed into SRC_TRUENAME, which is COPY's buffer for the
        ; canonical source.  The two commands never run at once, so the four name buffers
        ; from CURRENT_NAME_BUF onwards serve both, meaning something different in each.
        call    near FILEOP_RESET_STATE                        ;#4906: E8 3E 02
        mov     word [FILEOP_OPTION_FLAGS], SWITCH_A           ;#4909: C7 06 F0 4D 01 00
        mov     ax, 0F0h                                       ;#490F: B8 F0 00
        call    near PARSE_SWITCHES_OR_FAIL                    ;#4912: E8 06 03
        jb      short RENOMEIA_RETURN                          ;#4915: 72 38
        jz      short RENOMEIA_RETURN                          ;#4917: 74 36
        mov     al, 1                                          ;#4919: B0 01
        call    near PARSE_FILE_ARGUMENT                       ;#491B: E8 3B 02
        jb      short RENOMEIA_RETURN                          ;#491E: 72 2F
        mov     di, DEST_NAME_BUF                              ;#4920: BF 09 4C
        push    di                                             ;#4923: 57
        mov     si, CURRENT_NAME_BUF                           ;#4924: BE 89 4B
        call    near COPY_NUL_KEEP_SI                          ;#4927: E8 02 17
        pop     di                                             ;#492A: 5F
        call    near FIND_NAME_IN_PATH                         ;#492B: E8 DB E8
        mov     [FILEOP_DEST_POS], di                          ;#492E: 89 3E D1 4D
        call    near SKIP_BLANKS_AT_BP                         ;#4932: E8 EA E6
        jz      short RENOMEIA_TOO_MANY                        ;#4935: 74 19
        mov     al, [SWITCHAR_CHAR]                            ;#4937: A0 62 46
        cmp     al, [bp]                                       ;#493A: 3A 46 00
        jz      short RENAME_BAD_PARAM                         ;#493D: 74 52
        mov     al, [ARG_FLAGS]                                ;#493F: A0 2D 47
        mov     [FILEOP_ARG_FLAGS], al                         ;#4942: A2 F2 4D
        mov     di, SRC_TRUENAME                               ;#4945: BF 89 4C
        mov     al, 1                                          ;#4948: B0 01
        call    near PARSE_FILE_ARGUMENT                       ;#494A: E8 0C 02
        jnb     short RENOMEIA_PARSE_SWITCHES                  ;#494D: 73 09
RENOMEIA_RETURN:
        ; The parser has already said what went wrong
        ret                                                    ;#494F: C3

RENOMEIA_TOO_MANY:
        ; More than the two names RENAME takes
        mov     dx, MSG_NUMERO_DE_PARAMETROS_INVALIDO - TRANSIENT_BIAS ;#4950: BA 5C 01
        call    near PRINT_ERROR_AND_MARK                      ;#4953: E8 B1 02
        stc                                                    ;#4956: F9
        ret                                                    ;#4957: C3

RENOMEIA_PARSE_SWITCHES:
        ; Four letters, and exactly one more argument
        mov     ax, 0F0h                                       ;#4958: B8 F0 00
        call    near PARSE_SWITCHES_OR_FAIL                    ;#495B: E8 BD 02
        jb      short RENOMEIA_RETURN                          ;#495E: 72 EF
        jnz     short RENOMEIA_TOO_MANY                        ;#4960: 75 EE
        mov     di, SAVED_SEARCH_NAME                          ;#4962: BF B6 4D
        mov     si, [FILEOP_NAME_POS]                          ;#4965: 8B 36 CF 4D
        call    near COPY_NUL_KEEP_SI                          ;#4969: E8 C0 16
        mov     di, CURRENT_NAME_BUF                           ;#496C: BF 89 4B
        mov     si, DEST_NAME_BUF                              ;#496F: BE 09 4C
        test    byte [ARG_FLAGS], ARG_HAS_DRIVE                ;#4972: F6 06 2D 47 01
        jnz     short RENOMEIA_COMPARE_DRIVE                   ;#4977: 75 04
        mov     al, [si]                                       ;#4979: 8A 04
        mov     [di], al                                       ;#497B: 88 05
RENOMEIA_COMPARE_DRIVE:
        ; Both names have to be on the same drive
        mov     al, [si]                                       ;#497D: 8A 04
        cmp     al, [di]                                       ;#497F: 3A 05
        mov     dx, MSG_UNIDADE_INVALIDA - TRANSIENT_BIAS      ;#4981: BA 41 01
        jnz     short FILEOP_FAIL                              ;#4984: 75 0E
        mov     ax, [FILEOP_OPTION_FLAGS]                      ;#4986: A1 F0 4D
        and     ax, 0A0h                                       ;#4989: 25 A0 00
        cmp     ax, 0A0h                                       ;#498C: 3D A0 00
        jnz     short RENAME_MAKE_TARGET                       ;#498F: 75 08
RENAME_BAD_PARAM:
        ; MSG_PARAMETRO_INVALIDO then carry — RENAME's shared refusal
        mov     dx, MSG_PARAMETRO_INVALIDO - TRANSIENT_BIAS    ;#4991: BA 84 01
FILEOP_FAIL:
        ; PRINT_ERROR_AND_MARK then stc — the shared failure tail
        call    near PRINT_ERROR_AND_MARK                      ;#4994: E8 70 02
        stc                                                    ;#4997: F9
        ret                                                    ;#4998: C3

RENAME_MAKE_TARGET:
        ; Source directory plus the new name, once per match
        test    word [FILEOP_OPTION_FLAGS], SWITCH_S           ;#4999: F7 06 F0 4D 80 00
        jz      short RENTARGET_CHECK_ARGS                     ;#499F: 74 03
        jmp     near RENAME_MAKE_WILDCARDS                     ;#49A1: E9 9E 00

RENTARGET_CHECK_ARGS:
        ; Neither name may carry a path
        test    byte [ARG_FLAGS], ARG_HAS_SEPARATOR            ;#49A4: F6 06 2D 47 02
        jnz     short RENAME_BAD_PARAM                         ;#49A9: 75 E6
        test    byte [FILEOP_ARG_FLAGS], ARG_HAS_SEPARATOR     ;#49AB: F6 06 F2 4D 02
        jz      short RENAME_CHECK_WILDCARDS                   ;#49B0: 74 16
        inc     di                                             ;#49B2: 47
        inc     di                                             ;#49B3: 47
        inc     si                                             ;#49B4: 46
        inc     si                                             ;#49B5: 46
RENTARGET_COPY_CHAR:
        ; The old name's drive kept, the rest replaced
        lodsb                                                  ;#49B6: AC
        stosb                                                  ;#49B7: AA
        cmp     [FILEOP_DEST_POS], si                          ;#49B8: 39 36 D1 4D
        jnz     short RENTARGET_COPY_CHAR                      ;#49BC: 75 F8
        mov     si, SAVED_SEARCH_NAME                          ;#49BE: BE B6 4D
        mov     [FILEOP_NAME_POS], di                          ;#49C1: 89 3E CF 4D
        call    near COPY_TO_NUL                               ;#49C5: E8 E5 E5
RENAME_CHECK_WILDCARDS:
        ; SWITCH_N against ARG_HAS_WILDCARD in both flag bytes
        test    word [FILEOP_OPTION_FLAGS], SWITCH_N           ;#49C8: F7 06 F0 4D 20 00
        jz      short RENAME_FIND_FIRST                        ;#49CE: 74 14
        test    byte [FILEOP_ARG_FLAGS], ARG_HAS_WILDCARD      ;#49D0: F6 06 F2 4D 08
        jnz     short RENAME_BAD_PARAM                         ;#49D5: 75 BA
        test    byte [ARG_FLAGS], ARG_HAS_WILDCARD             ;#49D7: F6 06 2D 47 08
        jnz     short RENAME_BAD_PARAM                         ;#49DC: 75 B3
        and     word [FILEOP_OPTION_FLAGS], 0FFFEh             ;#49DE: 81 26 F0 4D FE FF
RENAME_FIND_FIRST:
        ; Look the destination pattern up
        mov     dx, DEST_NAME_BUF                              ;#49E4: BA 09 4C
        call    near FIND_FIRST_OR_FAIL                        ;#49E7: E8 C2 01
        jb      short REN_RETURN                               ;#49EA: 72 41
RENAME_ONE_MATCH:
        ; DTA_ENTRY_NUM 0FFFFh means nothing matched: "Arquivo não encontrado"
        cmp     word [FILEOP_DTA+DTA_ENTRY_NUM], 0FFFFh        ;#49EC: 83 3E 96 4D FF
        jnz     short RENAME_DO_INT21                          ;#49F1: 75 05
        mov     dx, MSG_ARQUIVO_NAO_ENCONTRADO - TRANSIENT_BIAS ;#49F3: BA A1 01
        jmp     short FILEOP_FAIL                              ;#49F6: EB 9C

RENAME_DO_INT21:
        ; The REN command: build the two names, then INT 21h AH=56h
        mov     si, FILEOP_DTA+DTA_NAME                        ;#49F8: BE A7 4D
        mov     di, [FILEOP_DEST_POS]                          ;#49FB: 8B 3E D1 4D
        call    near COPY_NUL_KEEP_SI                          ;#49FF: E8 2A 16
        mov     di, CURRENT_NAME_BUF                           ;#4A02: BF 89 4B
        call    near RENAME_SPLIT_TARGET                       ;#4A05: E8 C8 00
        test    word [FILEOP_OPTION_FLAGS], SWITCH_P           ;#4A08: F7 06 F0 4D 40 00
        jz      short REN_CALL_AH56                            ;#4A0E: 74 05
        call    near PRINT_DEST_NAME                           ;#4A10: E8 DD 00
        jb      short REN_AFTER_RENAME                         ;#4A13: 72 19
REN_CALL_AH56:
        ; The rename itself
        mov     ah, 56h                                        ;#4A15: B4 56
        int     21h                                            ;#4A17: CD 21
        jnb     short REN_AFTER_RENAME                         ;#4A19: 73 13
REN_ALREADY_EXISTS:
        ; Name, bell, and carry to the caller
        mov     dx, MSG_JA_EXISTE - TRANSIENT_BIAS             ;#4A1B: BA F1 01
        call    near PRINT_ERROR_AND_MARK                      ;#4A1E: E8 E6 01
        mov     dx, di                                         ;#4A21: 8B D7
        call    near PRINT_NUL_STDERR                          ;#4A23: E8 D2 EF
        mov     dx, MSG_BELL_CRLF - TRANSIENT_BIAS             ;#4A26: BA 02 02
        call    near PRINT_DOLLAR_STDERR                       ;#4A29: E8 D1 EF
        stc                                                    ;#4A2C: F9
REN_RETURN:
        ; Carry says whether this one worked
        ret                                                    ;#4A2D: C3

REN_AFTER_RENAME:
        ; /L prints the pair that was renamed
        jb      short REN_NEXT_MATCH                           ;#4A2E: 72 0B
        test    word [FILEOP_OPTION_FLAGS], SWITCH_L           ;#4A30: F7 06 F0 4D 10 00
        jz      short REN_NEXT_MATCH                           ;#4A36: 74 03
        call    near PRINT_RENAME_PAIR                         ;#4A38: E8 F8 00
REN_NEXT_MATCH:
        ; AH=4Fh for whatever else matches
        mov     ah, 4Fh                                        ;#4A3B: B4 4F
        int     21h                                            ;#4A3D: CD 21
