        ; The destination gets one extra case at 4A80h: `cmp al, 1` -- a drive letter and
        ; nothing else -- which takes RENAME_NEW_NAME rather than DEST_NAME_BUF, because
        ; there is no path to append to.
        ;
        ; And the separator is checked before appending:
        ;
        ; 4A9B    call    near SKIP_TO_NUL_AT_DI
        ; mov     al, [PATH_SEP_CHAR]
        ; cmp     [di-1], al
        ; jnz     short REN_APPEND_STAR_DOT_STAR
        ; dec     di
        ;
        ; APPEND_SLASH_STAR_DOT_STAR writes its own separator, so an argument that
        ; already ended in one has to give it back first.  That is the same "add it only
        ; if it is missing" as TAKE_NEXT_PATH_ENTRY in #1145, arranged the other way
        ; round -- there the separator was added when absent, here the existing one is
        ; removed so the appender can supply it unconditionally.
        mov     al, [ARG_FLAGS]                                ;#4A42: A0 2D 47
        test    al, 8                                          ;#4A45: A8 08
        jnz     short REN_CHECK_DEST                           ;#4A47: 75 2B
        test    al, 4                                          ;#4A49: A8 04
        jz      short REN_SOURCE_IS_DIR                        ;#4A4B: 74 17
        mov     dx, CURRENT_NAME_BUF                           ;#4A4D: BA 89 4B
        call    near IS_NAME_A_DIRECTORY                       ;#4A50: E8 63 00
        jb      short REN_CHECK_DEST                           ;#4A53: 72 1F
        jnz     short REN_SOURCE_IS_DIR                        ;#4A55: 75 0D
        cmp     word [FILEOP_DTA+DTA_ENTRY_NUM], 0FFFFh        ;#4A57: 83 3E 96 4D FF
        jnz     short REN_ALREADY_EXISTS                       ;#4A5C: 75 BD
        mov     dx, MSG_ARQUIVO_NAO_ENCONTRADO - TRANSIENT_BIAS ;#4A5E: BA A1 01
        jmp     near FILEOP_FAIL                               ;#4A61: E9 30 FF

REN_SOURCE_IS_DIR:
        ; Rename the contents: search it with *.*
        call    near MAKE_WILDCARD_SEARCH                      ;#4A64: E8 6D 01
        or      byte [ARG_FLAGS], ARG_HAS_WILDCARD             ;#4A67: 80 0E 2D 47 08
        mov     si, di                                         ;#4A6C: 8B F7
        mov     di, SAVED_SEARCH_NAME                          ;#4A6E: BF B6 4D
        call    near COPY_NUL_KEEP_SI                          ;#4A71: E8 B8 15
REN_CHECK_DEST:
        ; Now what the new name has to say
        mov     al, [FILEOP_ARG_FLAGS]                         ;#4A74: A0 F2 4D
        test    al, 8                                          ;#4A77: A8 08
        jz      short REN_DEST_DRIVE_ONLY                      ;#4A79: 74 03
        jmp     near RENAME_CHECK_WILDCARDS                    ;#4A7B: E9 4A FF

REN_DEST_DRIVE_ONLY:
