        jnz     short REN_DEST_NAMED                           ;#4A80: 75 05
        mov     di, RENAME_NEW_NAME                            ;#4A82: BF 8B 4B
        jmp     short REN_APPEND_STAR_DOT_STAR                 ;#4A85: EB 20

REN_DEST_NAMED:
