        pop     word [FILEOP_OPTION_FLAGS]                     ;#4AC3: 8F 06 F0 4D
        jb      short ISDIR_RETURN                             ;#4AC7: 72 06
        test    byte [FILEOP_DTA+DTA_ATTR], 10h                ;#4AC9: F6 06 9E 4D 10
        clc                                                    ;#4ACE: F8
