SHOW_VOLUME_LABEL:
        ; Build VOL_SEARCH_FCB, AH=11h, and print what it finds
        ; The label is found with the old FCB call, not AH=4Eh, because a volume label is
        ; a directory entry with attribute 8 and AH=11h is what searches on attributes
        ; without a path.  #1124 has the FCB it builds; this is what happens to the
        ; answer.
        ;
        ; 4D20    or      al, al
        ; pushf
        ; mov     dx, MSG_VOLUME_NA_UNIDADE - TRANSIENT_BIAS
        ; call    near PRINT_DOLLAR_STDOUT
        ; mov     al, bl
        ; dec     al
        ; call    near PUT_DRIVE_LETTER
        ; popf
        ; jnz     short VOLUME_NO_LABEL
        ;
        ; The one bit that matters -- found or not -- is pushed and the drive line is
        ; printed either way, because "Volume na unidade C" is the start of both
        ; sentences.  Only after it does the flag come back to choose between the name
        ; and "não tem nome".  Printing the common part first is what makes one saved bit
        ; enough.
        ;
        ; That is the third place in this file where `pushf` stands in for a variable:
        ; SCAN_NAME_COMPONENT keeps the terminator's flags across its own bookkeeping in
        ; #1140, COPY_READ_BLOCK holds FIND_CTRL_Z's carry across a pointer update in
        ; #1194, and here it spans two calls.  All three save exactly one bit for exactly
        ; as long as it is needed.
        ;
        ; The name itself is terminated where it sits:
        ;
        ; 4D39    mov     byte [FILEOP_DTA+FCBDIR_NAME_END], 0
        ; mov     dx, FILEOP_DTA+FCBDIR_NAME
        ;
        ; An FCB search result puts the eleven-character name at +8, and 13h is one past
        ; its end -- so a fixed-width field becomes a NUL-terminated string by writing a
        ; single byte into the DTA, with nothing copied anywhere.  #1223 gave the two
        ; offsets names.
        push    ax                                             ;#4CE2: 50
        push    cx                                             ;#4CE3: 51
        push    es                                             ;#4CE4: 06
        push    di                                             ;#4CE5: 57
        push    ds                                             ;#4CE6: 1E
        pop     es                                             ;#4CE7: 07
        mov     di, VOL_SEARCH_FCB                             ;#4CE8: BF F4 4D
        mov     al, 0FFh                                       ;#4CEB: B0 FF
        stosb                                                  ;#4CED: AA
        mov     cx, 5                                          ;#4CEE: B9 05 00
        xor     al, al                                         ;#4CF1: 32 C0
        rep     stosb                                          ;#4CF3: F3 AA
        mov     al, 8                                          ;#4CF5: B0 08
        stosb                                                  ;#4CF7: AA
        mov     al, 0                                          ;#4CF8: B0 00
        stosb                                                  ;#4CFA: AA
        mov     cx, 0Bh                                        ;#4CFB: B9 0B 00
        mov     al, "?"                                        ;#4CFE: B0 3F
        rep     stosb                                          ;#4D00: F3 AA
        mov     cx, 14h                                        ;#4D02: B9 14 00
        mov     al, 0                                          ;#4D05: B0 00
        rep     stosb                                          ;#4D07: F3 AA
        pop     di                                             ;#4D09: 5F
        pop     es                                             ;#4D0A: 07
        pop     cx                                             ;#4D0B: 59
        pop     ax                                             ;#4D0C: 58
        mov     [VOL_SEARCH_FCB+7], al                         ;#4D0D: A2 FB 4D
        mov     bl, al                                         ;#4D10: 8A D8
        mov     dx, FILEOP_DTA                                 ;#4D12: BA 89 4D
        mov     ah, 1Ah                                        ;#4D15: B4 1A
        int     21h                                            ;#4D17: CD 21
        mov     dx, VOL_SEARCH_FCB                             ;#4D19: BA F4 4D
        mov     ah, 11h                                        ;#4D1C: B4 11
        int     21h                                            ;#4D1E: CD 21
        or      al, al                                         ;#4D20: 0A C0
        pushf                                                  ;#4D22: 9C
        mov     dx, MSG_VOLUME_NA_UNIDADE - TRANSIENT_BIAS     ;#4D23: BA 2C 03
        call    near PRINT_DOLLAR_STDOUT                       ;#4D26: E8 C5 EC
        mov     al, bl                                         ;#4D29: 8A C3
        dec     al                                             ;#4D2B: FE C8
        call    near PUT_DRIVE_LETTER                          ;#4D2D: E8 D9 ED
        popf                                                   ;#4D30: 9D
        jnz     short VOLUME_NO_LABEL                          ;#4D31: 75 14
        mov     dx, MSG_IS - TRANSIENT_BIAS                    ;#4D33: BA 46 03
        call    near PRINT_DOLLAR_STDOUT                       ;#4D36: E8 B5 EC
        mov     byte [FILEOP_DTA+FCBDIR_NAME_END], 0           ;#4D39: C6 06 9C 4D 00
        mov     dx, FILEOP_DTA+FCBDIR_NAME                     ;#4D3E: BA 91 4D
        call    near PRINT_NUL_STDOUT                          ;#4D41: E8 A0 EC
        jmp     near PROMPT_CR_LF                              ;#4D44: E9 8F ED

VOLUME_NO_LABEL:
        ; The disk has none: say so instead
        mov     dx, MSG_NAO_TEM_NOME - TRANSIENT_BIAS          ;#4D47: BA 4A 03
        jmp     near PRINT_DOLLAR_STDOUT                       ;#4D4A: E9 A1 EC

