        jnz     short SET_COPY_VALUE                           ;#4F7F: 75 EF
        xor     ax, ax                                         ;#4F81: 33 C0
        dec     di                                             ;#4F83: 4F
        stosw                                                  ;#4F84: AB
SET_SHRINK_IF_ASKED:
