        call    near PRINT_NUL_STDOUT                          ;#4FCA: E8 17 EA
        call    near PROMPT_CR_LF                              ;#4FCD: E8 06 EB
        call    near SKIP_TO_NUL                               ;#4FD0: E8 62 E1
        jmp     short SETLIST_AT_END                           ;#4FD3: EB EE

