CLS_PICK_PATH:
        ; IOCTL AX=4400h then the INT 29h owner: stock kernel means BIOS, else ANSI
        ; Who actually interprets the escape sequences is decided here, and the answer
        ; is "not COMMAND.COM and not the kernel".
        ;
        ; 5118    mov     bx, 1           ; stdout
        ; mov     ax, 4400h       ; IOCTL, get device info
        ; int     21h
        ; not     dl
        ; test    dl, 82h         ; a character device, and the console?
        ; jnz     short CLS_VIA_ANSI     ; no -> ANSI
        ; mov     ax, 3529h       ; whose INT 29h is it?
        ; int     21h
        ; mov     ax, es          ; ...the segment it points at
        ; cmp     ax, 70h
        ; jnbe    short CLS_VIA_ANSI     ; not the kernel's -> ANSI
        ;
        ; INT 29h is fast console output and SISNE.SIS runs at CS=0070h, so a vector
        ; at or below segment 70h means the stock kernel still owns the console.  In
        ; that case COMMAND.COM does not emit escapes at all -- it clears the screen
        ; itself with INT 10h AH=6 and packs the colour into BH.  Only when something
        ; at a higher segment has hooked INT 29h does it write the sequences and let
        ; that driver deal with them.
        ;
        ; The kernel confirms it from the other side: sisne_sis.asm contains no
        ; comparison against 1Bh anywhere.  All 21 occurrences of that constant are
        ; structure offsets (fcb+1Bh, driver record +1Bh).  So the ANSI interpreter is
        ; neither COMMAND.COM, nor SISNE.SIS, nor the BIOS -- it is an installable
        ; driver, and this probe is COMMAND.COM asking whether one is present.
        mov     bx, 1                                          ;#5118: BB 01 00
        mov     ax, 4400h                                      ;#511B: B8 00 44
        int     21h                                            ;#511E: CD 21
        not     dl                                             ;#5120: F6 D2
        test    dl, 82h                                        ;#5122: F6 C2 82
        jnz     short CLS_VIA_ANSI                             ;#5125: 75 70
        push    es                                             ;#5127: 06
        mov     ax, 3529h                                      ;#5128: B8 29 35
        int     21h                                            ;#512B: CD 21
        mov     ax, es                                         ;#512D: 8C C0
        pop     es                                             ;#512F: 07
        cmp     ax, 70h                                        ;#5130: 3D 70 00
        jnbe    short CLS_VIA_ANSI                             ;#5133: 77 62
CLS_VIA_BIOS:
        ; Direct screen clear — INT 10h AH=6 with the colour packed into BH
        mov     ah, 0Fh                                        ;#5135: B4 0F
        int     10h                                            ;#5137: CD 10
        push    ax                                             ;#5139: 50
        xor     dx, dx                                         ;#513A: 33 D2
        mov     ah, 2                                          ;#513C: B4 02
        int     10h                                            ;#513E: CD 10
        pop     ax                                             ;#5140: 58
        mov     dl, ah                                         ;#5141: 8A D4
        dec     dl                                             ;#5143: FE CA
        mov     bl, [CLS_FG_COLOUR]                            ;#5145: 8A 1E C0 49
        test    word [CLS_OPTION_FLAGS], SWITCH_L              ;#5149: F7 06 BE 49 10 00
        jz      short CLSBIOS_BACKGROUND                       ;#514F: 74 08
        mov     byte [CLS_NEEDS_INTENSITY], 1                  ;#5151: C6 06 63 4E 01
        or      bl, 8                                          ;#5156: 80 CB 08
CLSBIOS_BACKGROUND:
        ; And the background, with its own intensity
        mov     bh, [CLS_BG_COLOUR]                            ;#5159: 8A 3E C1 49
        test    word [CLS_OPTION_FLAGS], SWITCH_P              ;#515D: F7 06 BE 49 40 00
        jz      short CLSBIOS_CHECK_MODE                       ;#5163: 74 08
        mov     byte [CLS_NEEDS_INTENSITY], 1                  ;#5165: C6 06 63 4E 01
        or      bh, 8                                          ;#516A: 80 CF 08
CLSBIOS_CHECK_MODE:
        ; Modes 0 to 3 and 7 are the text ones
        cmp     al, 3                                          ;#516D: 3C 03
        jbe     short CLSBIOS_LAST_ROW_24                      ;#516F: 76 14
        cmp     al, 7                                          ;#5171: 3C 07
        jz      short CLSBIOS_LAST_ROW_24                      ;#5173: 74 10
        cmp     byte [CLS_NEEDS_INTENSITY], 1                  ;#5175: 80 3E 63 4E 01
        jz      short CLSBIOS_LAST_ROW_50                      ;#517A: 74 05
        mov     ah, 0                                          ;#517C: B4 00
        int     10h                                            ;#517E: CD 10
        ret                                                    ;#5180: C3

CLSBIOS_LAST_ROW_50:
        ; A tall screen: scroll down to row 32h
        mov     dh, 32h                                        ;#5181: B6 32
        jmp     short CLSBIOS_PACK_ATTRIBUTE                   ;#5183: EB 02

CLSBIOS_LAST_ROW_24:
        ; The ordinary screen: row 18h
        mov     dh, 18h                                        ;#5185: B6 18
CLSBIOS_PACK_ATTRIBUTE:
        ; Background into the high nibble, then scroll
        mov     cl, 4                                          ;#5187: B1 04
        shl     bh, cl                                         ;#5189: D2 E7
        or      bh, bl                                         ;#518B: 0A FB
        xor     ax, ax                                         ;#518D: 33 C0
        mov     cx, ax                                         ;#518F: 8B C8
        mov     ah, 6                                          ;#5191: B4 06
        int     10h                                            ;#5193: CD 10
        jmp     short CLSANSI_CHECK_MODE                       ;#5195: EB 5B

CLS_VIA_ANSI:
        ; Emit SGR and clear as escape sequences for whatever hooked INT 29h
        ; Seven writes and one table.  The escape sequence is not stored anywhere whole:
        ; ANSI_ATTR_NORMAL goes out first, then ANSI_ATTR_BOLD and ANSI_ATTR_BLINK if
        ; /L or /P asked for them, then a foreground prefix, a digit, a background
        ; prefix, a digit, the terminator, and finally ANSI_CLEAR_SCREEN.  Nine possible
        ; sequences out of seven fragments and two conditionals.
        ;
        ; The digits come from CGA_TO_ANSI_COLOUR, eight bytes reading "04261537":
        ;
        ; 51C5    mov     bl, [CLS_FG_COLOUR]
        ; mov     dl, [bx+CGA_TABLE_IN_TRANSIENT]
        ;
        ; CGA counts blue before red and ANSI counts red before blue, so 1 becomes 4 and
        ; 4 becomes 1; green, magenta, black and white sit still; 3 and 6 swap for the
        ; same reason.  Every pair that moves swaps *with each other*, which makes the
        ; table its own inverse -- the same eight bytes would convert ANSI back to CGA,
        ; and nothing here has to know which direction it is going.
        ;
        ; The border is set afterwards and only sometimes:
        ;
        ; 51F2    mov     ah, 0Fh
        ; int     10h
        ; cmp     al, 4
        ; jb      short CLSANSI_SET_BORDER
        ; cmp     al, 7
        ; jnz     short CLSANSI_RETURN
        ;
        ; Modes below 4 and mode 7 get AH=0Bh with CLS_COLOUR; the graphics modes in
        ; between do not, because a border colour there means something else.  The escape
        ; sequence has already cleared the screen either way -- this is the one part of
        ; CLS that the terminal cannot be asked to do.
        mov     dx, ANSI_ATTR_NORMAL - TRANSIENT_BIAS          ;#5197: BA 4A 05
        mov     ah, 9                                          ;#519A: B4 09
        int     21h                                            ;#519C: CD 21
        test    word [CLS_OPTION_FLAGS], SWITCH_L              ;#519E: F7 06 BE 49 10 00
        jz      short CLSANSI_CHECK_BLINK                      ;#51A4: 74 07
        mov     dx, ANSI_ATTR_BOLD - TRANSIENT_BIAS            ;#51A6: BA 4F 05
        mov     ah, 9                                          ;#51A9: B4 09
        int     21h                                            ;#51AB: CD 21
CLSANSI_CHECK_BLINK:
        ; The blink attribute, if /P asked for it
        test    word [CLS_OPTION_FLAGS], SWITCH_P              ;#51AD: F7 06 BE 49 40 00
        jz      short CLSANSI_SET_COLOURS                      ;#51B3: 74 07
        mov     dx, ANSI_ATTR_BLINK - TRANSIENT_BIAS           ;#51B5: BA 54 05
        mov     ah, 9                                          ;#51B8: B4 09
        int     21h                                            ;#51BA: CD 21
CLSANSI_SET_COLOURS:
        ; Foreground and background through CGA_TABLE_IN_TRANSIENT
        mov     dx, ANSI_FG_PREFIX - TRANSIENT_BIAS            ;#51BC: BA 41 05
        mov     ah, 9                                          ;#51BF: B4 09
        int     21h                                            ;#51C1: CD 21
        xor     bh, bh                                         ;#51C3: 32 FF
        mov     bl, [CLS_FG_COLOUR]                            ;#51C5: 8A 1E C0 49
        mov     dl, [bx+CGA_TABLE_IN_TRANSIENT]                ;#51C9: 8A 97 34 05
        mov     ah, 2                                          ;#51CD: B4 02
        int     21h                                            ;#51CF: CD 21
        mov     dx, ANSI_BG_PREFIX - TRANSIENT_BIAS            ;#51D1: BA 45 05
        mov     ah, 9                                          ;#51D4: B4 09
        int     21h                                            ;#51D6: CD 21
        mov     bl, [CLS_BG_COLOUR]                            ;#51D8: 8A 1E C1 49
        mov     dl, [bx+CGA_TABLE_IN_TRANSIENT]                ;#51DC: 8A 97 34 05
        mov     ah, 2                                          ;#51E0: B4 02
        int     21h                                            ;#51E2: CD 21
        mov     dx, ANSI_COLOUR_END - TRANSIENT_BIAS           ;#51E4: BA 48 05
        mov     ah, 9                                          ;#51E7: B4 09
        int     21h                                            ;#51E9: CD 21
        mov     dx, ANSI_CLEAR_SCREEN - TRANSIENT_BIAS         ;#51EB: BA 3C 05
        mov     ah, 9                                          ;#51EE: B4 09
        int     21h                                            ;#51F0: CD 21
CLSANSI_CHECK_MODE:
        ; ANSI cannot set the border, so ask AH=0Fh
        mov     ah, 0Fh                                        ;#51F2: B4 0F
        int     10h                                            ;#51F4: CD 10
        cmp     al, 4                                          ;#51F6: 3C 04
        jb      short CLSANSI_SET_BORDER                       ;#51F8: 72 04
        cmp     al, 7                                          ;#51FA: 3C 07
        jnz     short CLSANSI_RETURN                           ;#51FC: 75 0A
CLSANSI_SET_BORDER:
        ; AH=0Bh does what ANSI will not
        mov     ah, 0Bh                                        ;#51FE: B4 0B
        xor     bh, bh                                         ;#5200: 32 FF
        mov     bl, [CLS_COLOUR]                               ;#5202: 8A 1E C2 49
        int     10h                                            ;#5206: CD 10
CLSANSI_RETURN:
        ; Screen cleared, colours set
        ret                                                    ;#5208: C3

PARSE_COLOUR_NUMBER:
        ; Up to four digits at BP, masked to 0..7 in BX
        call    near SKIP_WHITESPACE                           ;#5209: E8 FF DC
        jz      short COLOUR_NONE_GIVEN                        ;#520C: 74 29
        cmp     [cs:SWITCHAR_CHAR], al                         ;#520E: 2E 38 06 62 46
        jz      short COLOUR_NONE_GIVEN                        ;#5213: 74 22
        cmp     al, ","                                        ;#5215: 3C 2C
        jz      short COLOUR_SKIP_COMMA                        ;#5217: 74 1D
        xchg    si, bp                                         ;#5219: 87 EE
        mov     ah, 4                                          ;#521B: B4 04
        call    near PARSE_DECIMAL_AT_BP                       ;#521D: E8 0B E0
        xchg    bp, si                                         ;#5220: 87 F5
        jb      short COLOUR_RETURN                            ;#5222: 72 14
        mov     bx, dx                                         ;#5224: 8B DA
        and     bx, 7                                          ;#5226: 81 E3 07 00
        mov     byte [CLS_NEEDS_INTENSITY], 1                  ;#522A: C6 06 63 4E 01
        call    near SKIP_WHITESPACE                           ;#522F: E8 D9 DC
        cmp     al, ","                                        ;#5232: 3C 2C
        jnz     short COLOUR_NONE_GIVEN                        ;#5234: 75 01
COLOUR_SKIP_COMMA:
        ; Step over the separator before the next one
        inc     si                                             ;#5236: 46
COLOUR_NONE_GIVEN:
        ; No number here, and that is not an error
        clc                                                    ;#5237: F8
COLOUR_RETURN:
        ; Carry says the number would not parse
        ret                                                    ;#5238: C3

CMD_DATETIME:
PARSE_DATETIME_ARGS:
        ; Loop over the tail: classify each field, then SET_DATE_OR_TIME
        ; The handler never asks which of its six names was typed.  It reads the
        ; argument:
        ;
        ; 531B    call    near PARSE_2_DIGITS
        ; call    near ACCEPT_DASH_OR_SLASH
        ; mov     al, 1
        ; jnb     short CLASSIFY_CHECK_REPEAT
        ; mov     al, 2
        ; test    [DATETIME_GIVEN], al
        ;
        ; Two digits, then a '-' or '/' means a date and anything else a time.  So the
        ; name is decoration: `DATE 10:30` sets the clock and `TIME 25/12/90` sets the
        ; calendar, and neither is an error.
        ;
        ; What is an error is saying the same thing twice.  DATETIME_GIVEN accumulates
        ; bit 0 for a date and bit 1 for a time, and `test` before `or` turns a repeat
        ; into MSG_NUMERO_DE_PARAMETROS_INVALIDO.  The loop at 52AFh comes back for
        ; another field, so one command carries both -- `DATE 25/12/90 10:30` sets the
        ; pair in one go, with SET_DATE_OR_TIME applying whichever bits are set.
        ;
        ; Two-digit years are taken as 19xx: 5263h adds 76Ch to anything below 64h, so
        ; 90 becomes 1990 while a four-digit year passes through untouched.
        call    near ASK_DATE_AND_TIME                         ;#5239: E8 89 00
        jz      short DT_NOTHING_TO_DO                         ;#523C: 74 7B
DT_CLASSIFY_FIELD:
        ; Digits then '-' or '/' means a date, anything else a time
        call    near CLASSIFY_DATE_OR_TIME                     ;#523E: E8 DA 00
        jb      short DT_ERROR_EXIT                            ;#5241: 72 7F
        jnz     short DT_PARSE_TIME                            ;#5243: 75 30
        mov     [DATE_DAY], dl                                 ;#5245: 88 16 5B 48
        call    near PARSE_2_DIGITS                            ;#5249: E8 DD DF
        jb      short DT_BAD_DATE                              ;#524C: 72 6C
        mov     [DATE_MONTH], dl                               ;#524E: 88 16 5C 48
        call    near ACCEPT_DASH_OR_SLASH                      ;#5252: E8 2A 01
        jb      short DT_BAD_DATE                              ;#5255: 72 63
        mov     ah, 4                                          ;#5257: B4 04
        call    near PARSE_DECIMAL_AT_BP                       ;#5259: E8 CF DF
        jb      short DT_BAD_DATE                              ;#525C: 72 5C
        cmp     dx, 64h                                        ;#525E: 83 FA 64
        jnb     short DT_YEAR_TAKEN                            ;#5261: 73 04
        add     dx, 76Ch                                       ;#5263: 81 C2 6C 07
DT_YEAR_TAKEN:
        ; The year is in; the field should end here
        mov     [DATE_YEAR], dx                                ;#5267: 89 16 5D 48
        mov     al, [bp]                                       ;#526B: 8A 46 00
        call    near IS_CR_OR_BLANK                            ;#526E: E8 8F DD
        jnz     short DT_BAD_DATE                              ;#5271: 75 47
        jmp     short DT_NEXT_FIELD                            ;#5273: EB 3A

DT_PARSE_TIME:
        ; Hours, then ':' minutes, ':' seconds, '.' hundredths
        xchg    [TIME_HOUR], dl                                ;#5275: 86 16 5F 48
        mov     bl, ":"                                        ;#5279: B3 3A
        call    near ACCEPT_CHAR_BL                            ;#527B: E8 11 01
        jb      short DT_TIME_TAKEN                            ;#527E: 72 27
        call    near PARSE_2_DIGITS                            ;#5280: E8 A6 DF
        jb      short DT_BAD_TIME                              ;#5283: 72 3A
        xchg    [TIME_MINUTE], dl                              ;#5285: 86 16 60 48
        call    near ACCEPT_CHAR_BL                            ;#5289: E8 03 01
        jb      short DT_TIME_TAKEN                            ;#528C: 72 19
        call    near PARSE_2_DIGITS                            ;#528E: E8 98 DF
        jb      short DT_BAD_TIME                              ;#5291: 72 2C
        xchg    [TIME_SECOND], dl                              ;#5293: 86 16 61 48
        mov     bl, "."                                        ;#5297: B3 2E
        call    near ACCEPT_CHAR_BL                            ;#5299: E8 F3 00
        jb      short DT_TIME_TAKEN                            ;#529C: 72 09
        call    near PARSE_2_DIGITS                            ;#529E: E8 88 DF
        jb      short DT_BAD_TIME                              ;#52A1: 72 1C
        mov     [TIME_HUNDREDTHS], dl                          ;#52A3: 88 16 62 48
DT_TIME_TAKEN:
        ; However many parts were given, the field ends
        mov     al, [bp]                                       ;#52A7: 8A 46 00
        call    near IS_CR_OR_BLANK                            ;#52AA: E8 53 DD
        jnz     short DT_BAD_TIME                              ;#52AD: 75 10
DT_NEXT_FIELD:
        ; Another field on the line, or set what was gathered
        call    near SKIP_BLANKS_AT_BP                         ;#52AF: E8 6D DD
        jnz     short DT_CLASSIFY_FIELD                        ;#52B2: 75 8A
        call    near SET_DATE_OR_TIME                          ;#52B4: E8 89 00
        jnz     short DT_ERROR_EXIT                            ;#52B7: 75 09
DT_NOTHING_TO_DO:
        ; The prompt was answered with a bare Enter
        ret                                                    ;#52B9: C3

DT_BAD_DATE:
        ; MSG_DATA_INVALIDA
        mov     dx, MSG_DATA_INVALIDA - TRANSIENT_BIAS         ;#52BA: BA 09 06
        jmp     short DT_ERROR_EXIT                            ;#52BD: EB 03

DT_BAD_TIME:
        ; MSG_HORA_INVALIDA
        mov     dx, MSG_HORA_INVALIDA - TRANSIENT_BIAS         ;#52BF: BA 21 06
DT_ERROR_EXIT:
        ; Both arrive here
        jmp     near CMD_ERROR_EXIT                            ;#52C2: E9 24 DC

ASK_DATE_AND_TIME:
        ; Clear the eight fields, show the current pair, read a replacement line
        xor     ax, ax                                         ;#52C5: 33 C0
        mov     [DATETIME_GIVEN], al                           ;#52C7: A2 5A 48
        mov     [DATE_DAY], al                                 ;#52CA: A2 5B 48
        mov     [DATE_MONTH], al                               ;#52CD: A2 5C 48
        mov     [DATE_YEAR], ax                                ;#52D0: A3 5D 48
        mov     [TIME_HOUR], al                                ;#52D3: A2 5F 48
        mov     [TIME_MINUTE], al                              ;#52D6: A2 60 48
        mov     [TIME_SECOND], al                              ;#52D9: A2 61 48
        mov     [TIME_HUNDREDTHS], al                          ;#52DC: A2 62 48
        call    near SKIP_BLANKS_AT_BP                         ;#52DF: E8 3D DD
        jz      short DT_SHOW_TIME                             ;#52E2: 74 09
        cmp     al, "="                                        ;#52E4: 3C 3D
        jnz     short DT_ASK_RET                               ;#52E6: 75 32
        call    near SKIP_BLANKS_BP_NEXT                       ;#52E8: E8 33 DD
        jnz     short DT_ASK_RET                               ;#52EB: 75 2D
DT_SHOW_TIME:
        ; The time line under the date
        call    near PUT_TWO_SPACES                            ;#52ED: E8 0E E8
        call    near PROMPT_DATE                               ;#52F0: E8 69 E8
        call    near PUT_TWO_SPACES                            ;#52F3: E8 08 E8
        call    near PROMPT_TIME                               ;#52F6: E8 A2 E8
        mov     byte [DATETIME_INPUT_BUF], " "                 ;#52F9: C6 06 E4 46 20
        mov     word [DATETIME_INPUT_BUF+1], 0D00h             ;#52FE: C7 06 E5 46 00 0D
        mov     dx, MSG_ATUALIZE - TRANSIENT_BIAS              ;#5304: BA 39 06
        call    near PRINT_DOLLAR_STDOUT                       ;#5307: E8 E4 E6
        mov     dx, DATETIME_INPUT_BUF                         ;#530A: BA E4 46
        mov     ah, 0Ah                                        ;#530D: B4 0A
        int     21h                                            ;#530F: CD 21
        call    near PROMPT_CR_LF                              ;#5311: E8 C2 E7
        mov     bp, DATETIME_INPUT_BUF+2                       ;#5314: BD E6 46
        call    near SKIP_BLANKS_AT_BP                         ;#5317: E8 05 DD
DT_ASK_RET:
        ; Return from the prompt-and-read
        ret                                                    ;#531A: C3

CLASSIFY_DATE_OR_TIME:
        ; Parse a number; a '-' or '/' after it means date, anything else time
        call    near PARSE_2_DIGITS                            ;#531B: E8 0B DF
        jb      short CLASSIFY_BAD_SYNTAX                      ;#531E: 72 17
        call    near ACCEPT_DASH_OR_SLASH                      ;#5320: E8 5C 00
        mov     al, 1                                          ;#5323: B0 01
        jnb     short CLASSIFY_CHECK_REPEAT                    ;#5325: 73 02
        mov     al, 2                                          ;#5327: B0 02
CLASSIFY_CHECK_REPEAT:
        ; Bit already set means the same field twice
        test    [DATETIME_GIVEN], al                           ;#5329: 84 06 5A 48
        jnz     short CLASSIFY_ALREADY_GIVEN                   ;#532D: 75 0C
        or      [DATETIME_GIVEN], al                           ;#532F: 08 06 5A 48
        dec     al                                             ;#5333: FE C8
        clc                                                    ;#5335: F8
        ret                                                    ;#5336: C3

CLASSIFY_BAD_SYNTAX:
        ; Not two digits and a separator
        mov     dx, MSG_ERRO_SINTATICO_NO_COMANDO - TRANSIENT_BIAS ;#5337: BA B7 04
        ret                                                    ;#533A: C3

CLASSIFY_ALREADY_GIVEN:
        ; A date and a time, or two of one
        mov     dx, MSG_NUMERO_DE_PARAMETROS_INVALIDO - TRANSIENT_BIAS ;#533B: BA 5C 01
        stc                                                    ;#533E: F9
        ret                                                    ;#533F: C3

SET_DATE_OR_TIME:
        ; One routine for both: AH=2Bh to set the date, AH=2Dh to set the time
        test    byte [DATETIME_GIVEN], DATETIME_HAVE_DATE      ;#5340: F6 06 5A 48 01
        jz      short SETDT_MAYBE_TIME                         ;#5345: 74 17
        mov     dl, [DATE_DAY]                                 ;#5347: 8A 16 5B 48
        mov     dh, [DATE_MONTH]                               ;#534B: 8A 36 5C 48
        mov     cx, [DATE_YEAR]                                ;#534F: 8B 0E 5D 48
        mov     ah, 2Bh                                        ;#5353: B4 2B
        int     21h                                            ;#5355: CD 21
        mov     dx, MSG_DATA_INVALIDA - TRANSIENT_BIAS         ;#5357: BA 09 06
        or      al, al                                         ;#535A: 0A C0
        jnz     short SETDT_RETURN                             ;#535C: 75 20
SETDT_MAYBE_TIME:
        ; A date was set; a time may follow
        test    byte [DATETIME_GIVEN], DATETIME_HAVE_TIME      ;#535E: F6 06 5A 48 02
        jz      short SETDT_RETURN                             ;#5363: 74 19
        mov     ch, [TIME_HOUR]                                ;#5365: 8A 2E 5F 48
        mov     cl, [TIME_MINUTE]                              ;#5369: 8A 0E 60 48
        mov     dh, [TIME_SECOND]                              ;#536D: 8A 36 61 48
        mov     dl, [TIME_HUNDREDTHS]                          ;#5371: 8A 16 62 48
        mov     ah, 2Dh                                        ;#5375: B4 2D
        int     21h                                            ;#5377: CD 21
        mov     dx, MSG_HORA_INVALIDA - TRANSIENT_BIAS         ;#5379: BA 21 06
        or      al, al                                         ;#537C: 0A C0
SETDT_RETURN:
        ; AL zero and DX naming which one failed
        ret                                                    ;#537E: C3

ACCEPT_DASH_OR_SLASH:
        ; Take a '-' or '/' at BP, else leave BP alone and set carry
        inc     bp                                             ;#537F: 45
        cmp     byte [bp-1], "-"                               ;#5380: 80 7E FF 2D
        jz      short DASHSLASH_RETURN                         ;#5384: 74 08
        cmp     byte [bp-1], "/"                               ;#5386: 80 7E FF 2F
        jz      short DASHSLASH_RETURN                         ;#538A: 74 02
        dec     bp                                             ;#538C: 4D
        stc                                                    ;#538D: F9
DASHSLASH_RETURN:
        ; Carry when it was neither
        ret                                                    ;#538E: C3

ACCEPT_CHAR_BL:
        ; The same for whatever character is in BL
        inc     bp                                             ;#538F: 45
        cmp     [bp-1], bl                                     ;#5390: 38 5E FF
        jz      short CHARBL_RETURN                            ;#5393: 74 02
        dec     bp                                             ;#5395: 4D
        stc                                                    ;#5396: F9
CHARBL_RETURN:
        ; Carry when it did not match BL
        ret                                                    ;#5397: C3

CMD_CHDIR:
        ; The CHDIR command (aliases CD)
        mov     dx, MSG_DIRETORIO_INVALIDO - TRANSIENT_BIAS    ;#5398: BA 59 05
        mov     ah, 3Bh                                        ;#539B: B4 3B
        jmp     short DIR_COMMAND_BODY                         ;#539D: EB 19

CMD_MKDIR:
        ; The MKDIR command (aliases MD)
        mov     dx, MSG_IMPOSSIVEL_CRIAR_DIRETORIO - TRANSIENT_BIAS ;#539F: BA A0 05
        mov     ah, 39h                                        ;#53A2: B4 39
        jmp     short DIR_COMMAND_BODY                         ;#53A4: EB 12

CMD_RMDIR:
        ; The RMDIR command (aliases RD)
        mov     dx, MSG_DIRETORIO_INVALIDO_OU_NAO - TRANSIENT_BIAS ;#53A6: BA 76 05
        mov     ah, 3Ah                                        ;#53A9: B4 3A
        jmp     short DIR_COMMAND_BODY                         ;#53AB: EB 0B

DIRCMD_TOO_MANY:
        ; MKDIR, RMDIR and CHDIR all take one name
        mov     dx, MSG_NUMERO_DE_PARAMETROS_INVALIDO - TRANSIENT_BIAS ;#53AD: BA 5C 01
        jmp     short DIRCMD_REPORT                            ;#53B0: EB 03

DIRCMD_INVALID_DRIVE:
        ; No such drive letter
        mov     dx, MSG_UNIDADE_INVALIDA - TRANSIENT_BIAS      ;#53B2: BA 41 01
DIRCMD_REPORT:
        ; Out through the usual error exit
        jmp     near CMD_ERROR_EXIT                            ;#53B5: E9 31 DB

DIR_COMMAND_BODY:
