CMD_APPEND:
        ; Front end for the INT 2Fh AH=B7h TSR; /E moves the list to the environment
        ; APPEND is a front end for a TSR, reached through the INT 2Fh multiplex at
        ; AH=B7h, and most of the routine is about which of two places the path list
        ; lives in.
        ;
        ; The install check comes first and an absent TSR is not an error -- 53FCh drops
        ; a word from the stack and returns, so the command simply says nothing.  Then
        ; the version has to match exactly:
        ;
        ; 540E    cmp     bx, 31Eh
        ; jnz     short APPEND_VERSION_CONFLICT         ; MSG_CONFLITO_DE_VERSAO
        ; dec     cl
        ; cmp     cx, 0
        ; jb      short APPEND_VERSION_CONFLICT
        ;
        ; That second guard cannot fire.  `cmp` against zero always clears CF, so `jb` is
        ; never taken -- and `dec` would not have set it either, since INC and DEC leave
        ; CF alone.  Whatever CL was meant to rule out, it is not ruled out.
        ;
        ; SISNE.SIS has the other half of the family at E9A5h, where an `and` between an
        ; `add` and its `jnb` costs a real carry and leaves a 64K fix-up unreachable.
        ; Two instances in four images, each dead in the opposite direction.
        ;
        ; The mask is 181Dh, so /A /C /D /L /E /X, and /E is the one that matters:
        ;
        ; 548F    test    byte [APPEND_STATE], 80h
        ; jnz     short APPEND_STORE_IN_ENV         ; ...the environment instead
        ; mov     si, PSP_TAIL
        ; cmp byte [si], ";"
        ; jnz     short APPEND_SET_VIA_TSR
        ; mov     byte [si], 0        ; a lone ';' clears the list
        ; 54A1    mov     ax, 0B702h
        ; int     2Fh
        ;
        ; With bit 7 clear the list is handed to the TSR with B702h and read back with
        ; B705h.  With it set, every one of those becomes environment work instead --
        ; DELETE_ENV_VARIABLE and STORE_ENV_VARIABLE with MSG_APPEND and CX=7 for
        ; "APPEND=", and SCAN_ENVIRONMENT to read it.  One command, two backing stores,
        ; and the bit that chooses is kept by the TSR rather than by COMMAND.COM, which
        ; is why /E on one invocation still governs the next one.
        ;
        ; Separators are normalised on the way in.  547Fh writes a ';' over whatever
        ; separator was typed, so "APPEND A:\ B:\" reaches either store as the single
        ; semicolon-separated string both sides expect.
        mov     ax, 0B700h                                     ;#53F3: B8 00 B7
        int     2Fh                                            ;#53F6: CD 2F
        or      al, al                                         ;#53F8: 0A C0
        jnz     short APPEND_CHECK_VERSION                     ;#53FA: 75 12
        pop     ax                                             ;#53FC: 58
        ret                                                    ;#53FD: C3

APPEND_VERSION_CONFLICT:
        ; The TSR is not the version this expects
        mov     dx, MSG_CONFLITO_DE_VERSAO - TRANSIENT_BIAS    ;#53FE: BA 19 07
        jmp     short APPEND_ERROR_EXIT                        ;#5401: EB 08

APPEND_BAD_PARAM:
        ; MSG_PARAMETRO_INVALIDO
        mov     dx, MSG_PARAMETRO_INVALIDO - TRANSIENT_BIAS    ;#5403: BA 84 01
        jmp     short APPEND_ERROR_EXIT                        ;#5406: EB 03

APPEND_BAD_COUNT:
        ; MSG_NUMERO_DE_PARAMETROS_INVALIDO
        mov     dx, MSG_NUMERO_DE_PARAMETROS_INVALIDO - TRANSIENT_BIAS ;#5408: BA 5C 01
APPEND_ERROR_EXIT:
        ; The stubs above all arrive here
        jmp     near CMD_ERROR_EXIT                            ;#540B: E9 DB DA

APPEND_CHECK_VERSION:
