        jnz     short APPEND_VERSION_CONFLICT                  ;#5412: 75 EA
        dec     cl                                             ;#5414: FE C9
        cmp     cx, 0                                          ;#5416: 83 F9 00
        jb      short APPEND_VERSION_CONFLICT                  ;#5419: 72 E3
        mov     ax, 0B703h                                     ;#541B: B8 03 B7
        int     2Fh                                            ;#541E: CD 2F
        inc     ah                                             ;#5420: FE C4
        jnz     short APPEND_VERSION_CONFLICT                  ;#5422: 75 DA
        mov     [APPEND_STATE], al                             ;#5424: A2 9C 4A
        mov     si, bp                                         ;#5427: 8B F5
        mov     di, CMD_SWITCH_LETTERS - TRANSIENT_BIAS        ;#5429: BF 2D 0C
        mov     ax, 181Dh                                      ;#542C: B8 1D 18
        call    near PARSE_SWITCHES                            ;#542F: E8 72 DD
        jb      short APPEND_BAD_PARAM                         ;#5432: 72 CF
