        jnz     short APPEND_BAD_COUNT                         ;#543E: 75 C8
        mov     bl, [APPEND_STATE]                             ;#5440: 8A 1E 9C 4A
        mov     ax, [APPEND_OPTION_FLAGS]                      ;#5444: A1 9D 4A
        call    near APPEND_SWITCHES_TO_FLAGS                  ;#5447: E8 BB 00
        mov     ax, 0B704h                                     ;#544A: B8 04 B7
        int     2Fh                                            ;#544D: CD 2F
        test    word [APPEND_OPTION_FLAGS], SWITCH_L           ;#544F: F7 06 9D 4A 10 00
