        inc     bl                                             ;#5564: FE C3
        cmp     bl, [DRIVE_COUNT]                              ;#5566: 3A 1E 07 47
        jnb     short ASSIGNLIST_DONE                          ;#556A: 73 24
        mov     dx, PATHBLK_APPEND                             ;#556C: BA A3 4A
        mov     ax, 180Bh                                      ;#556F: B8 0B 18
