        ; from FOR_LIST_BUF, each NUL-terminated with a second NUL to close the set, and
        ; 5818h loads DI with FOR_BODY_END before 5820h sets STD -- so the body is copied
        ; backwards from the far end of the same buffer.  Two structures of unknown size
        ; in one allocation, meeting in the middle.
        mov     ax, 81h                                        ;#578C: B8 81 00
        call    near PARSE_SWITCHES_AT_BP                      ;#578F: E8 60 DA
        jb      short FOR_BAD_PARAM                            ;#5792: 72 F3
