        ; jnz     short EXIST_FOUND           ; ...true, without looking
        ;
        ; 59C5    test    word [IF_SWITCHES], SWITCH_S     ; /S
        ; jz      short EXIST_CALL_INT21
        ; mov     cx, 10h                     ; ...directories count too
        ;
        ; /V short-circuits to EXIST_FOUND, which is `xor cx, cx / ret` -- CX zero
        ; meaning "handled" in #1155's convention, with IF_RESULT untouched and
        ; therefore true.
        ; So the test succeeds without a find being issued at all.
        ;
        ; /S puts 10h in CX for the AH=4Eh, so a directory satisfies EXIST as well as a
        ; file, and 59DBh then has to skip "." and ".." through IS_DOT_ENTRY and continue
        ; with AH=4Fh -- because those two exist in every directory and would make the
        ; condition meaningless.
        ;
        ; Bit 0 is /A, and nothing reads it.  It is admitted by the mask and never
        ; tested, so `IF /A EXIST name` parses and behaves exactly as `IF EXIST name`.
        ; Worth writing down: a switch that parses is not evidence of a switch that does
        ; something, and the mask is the only place /A appears.
        mov     ax, 281h                                       ;#5999: B8 81 02
        call    near PARSE_SWITCHES_AT_BP                      ;#599C: E8 53 D8
        jb      short EXIST_RETURN                             ;#599F: 72 54
        mov     [IF_SWITCHES], ax                              ;#59A1: A3 CA 49
        mov     di, IF_NAME_BUF                                ;#59A4: BF CC 49
        call    near ARG_PARSE_INIT                            ;#59A7: E8 60 D9
        jb      short EXIST_RETURN                             ;#59AA: 72 49
        test    byte [ARG_FLAGS], ARG_DRIVE_INVALID            ;#59AC: F6 06 2D 47 80
        jnz     short EXIST_NOT_FOUND                          ;#59B1: 75 3C
        test    word [IF_SWITCHES], SWITCH_V                   ;#59B3: F7 06 CA 49 00 02
        jnz     short EXIST_FOUND                              ;#59B9: 75 38
        call    near SET_SHARED_DTA                            ;#59BB: E8 9E D6
        mov     dx, IF_NAME_BUF                                ;#59BE: BA CC 49
        mov     ah, 4Eh                                        ;#59C1: B4 4E
        xor     cx, cx                                         ;#59C3: 33 C9
        test    word [IF_SWITCHES], SWITCH_S                   ;#59C5: F7 06 CA 49 80 00
        jz      short EXIST_CALL_INT21                         ;#59CB: 74 03
        mov     cx, 10h                                        ;#59CD: B9 10 00
