        jb      short EXIST_NOT_FOUND                          ;#59D2: 72 1B
        cmp     word [SHARED_DTA+DTA_ENTRY_NUM], 0FFFFh        ;#59D4: 83 3E E7 47 FF
        jz      short EXIST_NOT_FOUND                          ;#59D9: 74 14
        test    word [IF_SWITCHES], SWITCH_S                   ;#59DB: F7 06 CA 49 80 00
        jz      short EXIST_FOUND                              ;#59E1: 74 10
        mov     si, SHARED_DTA                                 ;#59E3: BE DA 47
        call    near IS_DOT_ENTRY                              ;#59E6: E8 4B D6
        mov     ah, 4Fh                                        ;#59E9: B4 4F
        jnb     short EXIST_CALL_INT21                         ;#59EB: 73 E3
        jmp     short EXIST_FOUND                              ;#59ED: EB 04

EXIST_NOT_FOUND:
