        ; 5A52    inc     cx
        ; cmp     cx, 8
        ; jnb     short GOTO_REWIND
        ; inc     bp
        ; mov     al, [bp]
        ; call    near IS_CR_OR_BLANK
        ; jnz     short GOTO_COUNT_CHAR
        ;
        ; Then the file goes back to the beginning, every time:
