        ; 5C8D    jmp     near COPY_NEXT_ARGUMENT
        ;
        ; COPY_FLAGS is deliberately cleared on the way, so nothing about the current
        ; source survives.  Coming back in, BP is set to 81h again and the source
        ; argument is parsed out of the command tail from scratch, the search is opened
        ; again with find-first, and the position is recovered by replaying it:
        ;
        ; 5B14    mov     cx, [COPY_RESUME_INDEX]
        ; jcxz    COPY_BUILD_DEST
        ; 5B1A    call    near COPY_FIND_NEXT
        ; jnb     short COPY_REPLAY_LOOP
        ; jmp     near REPORT_FILES_COPIED
        ; 5B22    loop    COPY_REPLAY_STEP
        ;
        ; A find-next that fails during the replay means the previous copy took the last
        ; match, which is why running out mid-replay reports success rather than an
        ; error.
        ;
        ; So COPY never holds a directory search open across a file copy.  It re-reads
        ; the command line, re-opens the search and steps forward COPY_RESUME_INDEX
        ; times, which is why that variable exists at all.  Copying the k-th match costs
        ; k find-nexts, so a wildcard copy walks the directory a quadratic number of
        ; times -- the price of keeping no state across the copy itself.
        ;
        ; A trailing separator is expanded before any of that.  If the parsed source ends
        ; with PATH_SEP_CHAR the code steps back over it and calls
        ; APPEND_SLASH_STAR_DOT_STAR, so "COPY A:\ B:" is "COPY A:\*.* B:" by the time
        ; the search opens, and COPY_ECHO_NAMES records that the wildcard was the
        ; program's idea rather than the user's.
        and     byte [COPY_DEST_FLAGS], 0F9h                   ;#5ACA: 80 26 C5 4D F9
        mov     di, CURRENT_NAME_BUF                           ;#5ACF: BF 89 4B
        mov     bp, PSP_TAIL                                   ;#5AD2: BD 81 00
        call    near COPY_PARSE_ONE_SOURCE                     ;#5AD5: E8 A2 03
        jnb     short COPY_ARG_HAVE_SOURCE                     ;#5AD8: 73 03
COPY_ARG_GIVE_UP:
        ; Nothing more to parse — leave through COPY_RETURN
        jmp     near COPY_RETURN                               ;#5ADA: E9 F2 01

COPY_ARG_HAVE_SOURCE:
        ; A source name in hand: expand a trailing separator to \*.*
        mov     di, [FILEOP_NAME_POS]                          ;#5ADD: 8B 3E CF 4D
        call    near SKIP_TO_NUL_AT_DI                         ;#5AE1: E8 1D F1
        mov     al, [PATH_SEP_CHAR]                            ;#5AE4: A0 63 46
        cmp     [di-1], al                                     ;#5AE7: 38 45 FF
        jnz     short COPY_ARG_FIND_FIRST                      ;#5AEA: 75 11
        dec     di                                             ;#5AEC: 4F
        call    near APPEND_SLASH_STAR_DOT_STAR                ;#5AED: E8 00 F1
        or      byte [COPY_SEARCH_STARTED], SEARCH_FIND_OPEN   ;#5AF0: 80 0E C8 4D 01
        or      byte [COPY_FLAGS], COPY_ECHO_NAMES             ;#5AF5: 80 0E C4 4D 40
        call    near SAVE_SEARCH_NAME                          ;#5AFA: E8 28 05
COPY_ARG_FIND_FIRST:
