        jz      short COPY_ARG_GIVE_UP                         ;#5B07: 74 D1
        call    near COPY_NEXT_SOURCE                          ;#5B09: E8 57 03
        jnz     short COPY_ARG_HAVE_SOURCE                     ;#5B0C: 75 CF
        call    near COPY_ERR_BAD_PATH                         ;#5B0E: E8 2B 02
        jmp     near COPY_RETURN                               ;#5B11: E9 BB 01

COPY_REPLAY_SEARCH:
