        call    near IS_PATH_SEP                               ;#5B33: E8 38 D4
        jz      short COPY_DEST_SEPARATOR                      ;#5B36: 74 23
        call    near IS_SEPARATOR_OR_COLON                     ;#5B38: E8 EF 0A
        jz      short COPY_DEST_SWITCH                         ;#5B3B: 74 26
        call    near COPY_APPLY_MODE                           ;#5B3D: E8 4A 02
        jb      short COPY_DEST_RETURN                         ;#5B40: 72 16
        jz      short COPY_DEST_ENDED                          ;#5B42: 74 27
        cmp     ah, 0FFh                                       ;#5B44: 80 FC FF
        jz      short COPY_DEST_BAD_PARAM                      ;#5B47: 74 0C
        mov     al, [bp]                                       ;#5B49: 8A 46 00
COPY_DEST_STORE:
