        call    near UPCASE_AL                                 ;#5B4C: E8 B1 D3
        mov     [di], al                                       ;#5B4F: 88 05
        inc     di                                             ;#5B51: 47
        inc     bp                                             ;#5B52: 45
        jmp     short COPY_DEST_CHAR                           ;#5B53: EB DB

COPY_DEST_BAD_PARAM:
        ; MSG_PARAMETRO_INVALIDO and out
        call    near COPY_ERR_BAD_PARAM                        ;#5B55: E8 E9 01
COPY_DEST_RETURN:
        ; The shared exit once the destination is settled
        jmp     near COPY_RETURN                               ;#5B58: E9 74 01

COPY_DEST_SEPARATOR:
        ; A path separator: mark it and keep going
        inc     di                                             ;#5B5B: 47
        mov     [FILEOP_DEST_POS], di                          ;#5B5C: 89 3E D1 4D
        dec     di                                             ;#5B60: 4F
        jmp     short COPY_DEST_STORE                          ;#5B61: EB E9

COPY_DEST_SWITCH:
