        or      byte [COPY_SEARCH_STARTED], SEARCH_DEST_POS_SET ;#5BA1: 80 0E C8 4D 02
        or      byte [COPY_DEST_FLAGS], DEST_WAS_NAMED         ;#5BA6: 80 0E C5 4D 02
        inc     di                                             ;#5BAB: 47
        inc     di                                             ;#5BAC: 47
        inc     di                                             ;#5BAD: 47
COPY_DEST_TERMINATE:
