        mov     byte [di], 0                                   ;#5BAE: C6 05 00
        mov     si, [FILEOP_DEST_POS]                          ;#5BB1: 8B 36 D1 4D
        call    near SCAN_NAME_FOR_WILD                        ;#5BB5: E8 5B 01
        jnb     short COPY_DEST_TEST_DIR                       ;#5BB8: 73 1C
        or      byte [COPY_SEARCH_STARTED], SEARCH_DEST_POS_SET ;#5BBA: 80 0E C8 4D 02
        cmp     byte [COPY_SEARCH_STARTED], 3                  ;#5BBF: 80 3E C8 4D 03
        jnz     short COPY_DEST_COMPARE                        ;#5BC4: 75 05
        mov     byte [COPY_SEARCH_WAS_OPEN], 1                 ;#5BC6: C6 06 C7 4D 01
COPY_DEST_COMPARE:
