        mov     si, [FILEOP_DEST_POS]                          ;#5BCB: 8B 36 D1 4D
        mov     di, [FILEOP_NAME_POS]                          ;#5BCF: 8B 3E CF 4D
        call    near COPY_CHECK_NAME                           ;#5BD3: E8 71 01
COPY_DEST_TEST_DIR:
