        push    bx                                             ;#5C0A: 53
        mov     ax, 4400h                                      ;#5C0B: B8 00 44
        int     21h                                            ;#5C0E: CD 21
        test    dl, 80h                                        ;#5C10: F6 C2 80
        jnz     short COPY_DEST_IS_DEVICE                      ;#5C13: 75 07
        or      byte [COPY_DEST_FLAGS], DEST_IS_FILE           ;#5C15: 80 0E C5 4D 04
        jmp     short COPY_DEST_CLOSE                          ;#5C1A: EB 22

COPY_DEST_IS_DEVICE:
