        call    near CHECK_OVERWRITE                           ;#5C48: E8 BD 01
        jb      short COPY_ARG_CHECK_RESUME                    ;#5C4B: 72 27
        call    near SET_COPY_BUF_SIZE                         ;#5C4D: E8 2C 04
        mov     [COPY_BUF_SEG], dx                             ;#5C50: 89 16 DC 4D
        mov     word [COPY_BUF_OFF], 0                         ;#5C54: C7 06 DE 4D 00 00
