        dec     bp                                             ;#5FD2: 4D
        cmp     byte [si], 0                                   ;#5FD3: 80 3C 00
        jz      short STAR_TERMINATE                           ;#5FD6: 74 34
        inc     bp                                             ;#5FD8: 45
        call    near COPY_TO_DOT                               ;#5FD9: E8 35 00
        jmp     short STAR_TERMINATE                           ;#5FDC: EB 2E

STAR_FIND_DOT:
