COPY_TOUCH_DATE:
        ; COPY /D: stamp the file with now and close it again
        ; Not a copy at all.  5C90h tests SWITCH_D -- /D, for *data* -- and only then
        ; comes here, where the file is opened, stamped with the current
        ; date and time, and closed again.  MS-DOS's COPY has no such switch; the error
        ; message when the target is a device says exactly what the routine is for:
        ; "Impossível mudar a data de dispositivos".
        ;
        ; The stamp is assembled by rotating bits through the carry rather than by
        ; shifting and OR-ing:
        ;
        ; 61BA    mov     cl, 4
        ; shl     dh, cl
        ; mov     cl, 3
        ; shl     dl, cl
        ; pop     ax
        ; sub     ax, 7BCh
        ; mov     cx, 4
        ; 61C9    shl     dh, 1
        ; rcl     ax, 1
        ; loop    DATE_SHIFT_IN_MONTH
        ;
        ; AH=2Ah leaves the year in CX, the month in DH and the day in DL.  The year less
        ; 7BCh -- 1980 -- goes in AX, and then each `shl` pushes the top bit of a field
        ; into the carry for `rcl` to pull into AX from below.  Four for the month, five
        ; for the day, and the packed word assembles itself without a mask or an `or`
        ; anywhere.  The time is built the same way from AH=2Ch.
        ;
        ; Two things follow from where this sits.  #1183 found the ordinary copy skipping
        ; its timestamp when bit 3 is set, which is the same switch saying "the date I
        ; want is now, not the source's".  And the device check has to happen first,
        ; because AX=5701h on a character device is the one case that cannot work.
        mov     dx, CURRENT_NAME_BUF                           ;#6188: BA 89 4B
        mov     ax, 3D00h                                      ;#618B: B8 00 3D
        int     21h                                            ;#618E: CD 21
        jb      short TOUCH_NOT_FOUND                          ;#6190: 72 77
        mov     [COPY_SRC_HANDLE], ax                          ;#6192: A3 E2 4D
        or      byte [COPY_OPEN_FLAGS], COPY_SRC_OPEN          ;#6195: 80 0E ED 4D 01
        push    ax                                             ;#619A: 50
        test    byte [COPY_FLAGS], COPY_ECHO_NAMES             ;#619B: F6 06 C4 4D 40
        jz      short TOUCH_TEST_DEVICE                        ;#61A0: 74 03
        call    near PRINT_SOURCE_NAME                         ;#61A2: E8 44 04
TOUCH_TEST_DEVICE:
        ; A device has no date to copy
        pop     bx                                             ;#61A5: 5B
        call    near SRC_IS_DEVICE                             ;#61A6: E8 5D 04
        jb      short TOUCH_FAILED                             ;#61A9: 72 64
        test    byte [COPY_FLAGS], COPY_SRC_IS_DEVICE          ;#61AB: F6 06 C4 4D 04
        mov     dx, MSG_IMPOSSIVEL_MUDAR_DATA_DE - TRANSIENT_BIAS ;#61B0: BA CC 0A
        jnz     short TOUCH_REPORT_ERROR                       ;#61B3: 75 57
        mov     ah, 2Ah                                        ;#61B5: B4 2A
        int     21h                                            ;#61B7: CD 21
        push    cx                                             ;#61B9: 51
        mov     cl, 4                                          ;#61BA: B1 04
        shl     dh, cl                                         ;#61BC: D2 E6
        mov     cl, 3                                          ;#61BE: B1 03
        shl     dl, cl                                         ;#61C0: D2 E2
        pop     ax                                             ;#61C2: 58
        sub     ax, 7BCh                                       ;#61C3: 2D BC 07
        mov     cx, 4                                          ;#61C6: B9 04 00
DATE_SHIFT_IN_MONTH:
        ; Four bits of month into the packed date
