COPY_READ_BLOCK:
        ; AH=3Fh into the buffer; COPY_SRC_IS_DEVICE picks the chunk size
        ; A file and a device are read by different loops, and the reason is what counts
        ; as an error.
        ;
        ; A file gets one AH=3Fh for the whole request, and anything short is a failure:
        ;
        ; 64AB    mov     ah, 3Fh
        ; int     21h
        ; jb      short READ_FAILED
        ; cmp     cx, ax
        ; jnz     short READ_FAILED
        ;
        ; A device gets 80h bytes at a time instead, because a short read from a device
        ; is not a failure -- it is a line, or whatever the user has typed so far.  So
        ; the count can never be compared, and the loop stops on Ctrl-Z or on nothing
        ; coming back:
        ;
        ; 6486    mov     cx, 80h
        ; mov     ah, 3Fh
        ; int     21h
        ; or      ax, ax
        ; jz      short READ_DEVICE_DONE
        ; mov     cx, ax
        ; call    near FIND_CTRL_Z
        ; pushf
        ; add     di, cx
        ; add     dx, cx
        ; jb      short READ_ADVANCE_SEGMENT
        ; popf
        ; jnb     short READ_DEVICE_CHUNK
        ;
        ; Two carries are in play there and neither can be allowed to see the other's.
        ; FIND_CTRL_Z returns one and the two `add`s produce another for a 64K crossing,
        ; so the first is pushed while the address arithmetic runs and popped to decide
        ; whether to go round again.  `pushf` between them is the whole of keeping the
        ; question "did we find it" apart from "did the pointer wrap".
        ;
        ; The Ctrl-Z scan itself also lands differently.  A device is scanned after every
        ; 128 bytes, so typing it ends the input at once; a file is scanned once at the
        ; end, and only when #1178's bit-3 conditions say the input is text at all.
        push    ax                                             ;#6479: 50
        test    byte [es:COPY_FLAGS], COPY_SRC_IS_DEVICE       ;#647A: 26 F6 06 C4 4D 04
        jz      short READ_WHOLE_FILE                          ;#6480: 74 29
        xor     di, di                                         ;#6482: 33 FF
        push    dx                                             ;#6484: 52
        push    ds                                             ;#6485: 1E
READ_DEVICE_CHUNK:
        ; 80h bytes at a time; a short answer is a line, not an error
        mov     cx, 80h                                        ;#6486: B9 80 00
        mov     ah, 3Fh                                        ;#6489: B4 3F
        int     21h                                            ;#648B: CD 21
        or      ax, ax                                         ;#648D: 0B C0
        jz      short READ_DEVICE_DONE                         ;#648F: 74 0F
        mov     cx, ax                                         ;#6491: 8B C8
        call    near FIND_CTRL_Z                               ;#6493: E8 3B 01
        pushf                                                  ;#6496: 9C
        add     di, cx                                         ;#6497: 03 F9
        add     dx, cx                                         ;#6499: 03 D1
        jb      short READ_ADVANCE_SEGMENT                     ;#649B: 72 09
READ_DEVICE_CONTINUE:
