        mov     cx, di                                         ;#64A0: 8B CF
        pop     ds                                             ;#64A2: 1F
        pop     dx                                             ;#64A3: 5A
        jmp     short READ_ACCOUNT                             ;#64A4: EB 2A

READ_ADVANCE_SEGMENT:
