        jb      short READ_FAILED                              ;#64AF: 72 25
        cmp     cx, ax                                         ;#64B1: 3B C8
        jnz     short READ_FAILED                              ;#64B3: 75 21
        test    byte [es:COPY_FLAGS], COPY_SRC_BINARY          ;#64B5: 26 F6 06 C4 4D 02
        jnz     short READ_ACCOUNT                             ;#64BB: 75 13
        cmp     byte [es:COPY_SEARCH_STARTED], SEARCH_FIND_OPEN ;#64BD: 26 80 3E C8 4D 01
        jz      short READ_SCAN_CTRL_Z                         ;#64C3: 74 08
        test    byte [es:COPY_FLAGS], 89h                      ;#64C5: 26 F6 06 C4 4D 89
        jz      short READ_ACCOUNT                             ;#64CB: 74 03
