        ; 650E    push    cx
        ; mov     cx, 0FFFFh
        ; call    near COPY_WRITE_BLOCK
        ; pop     cx
        ; jb      short WRITE_BUF_RETURN
        ; call    near ADVANCE_DS_64K
        ; loop    WRITE_FULL_64K
