        ; operands are written in opposite orders.  Nothing about the machine cares --
        ; the exchange is symmetric -- but the encoding is not, so the decoder has to
        ; give back the order each one was written in.  It does, and neither site needs
        ; a [code] override to stay bit-exact.
        push    ds                                             ;#64EB: 1E
        call    near SET_COPY_BUF_SIZE                         ;#64EC: E8 8D FB
        cmp     byte [COPY_BUF_FULL], 0                        ;#64EF: 80 3E C6 4D 00
        jz      short WRITE_MEASURE_PARTIAL                    ;#64F4: 74 6A
        mov     [COPY_BUF_SEG], dx                             ;#64F6: 89 16 DC 4D
        mov     word [COPY_BUF_OFF], 0                         ;#64FA: C7 06 DE 4D 00 00
