        mov     bx, [es:COPY_DST_HANDLE]                       ;#6502: 26 8B 1E E4 4D
        mov     cx, [es:COPY_BUF_SIZE_HI]                      ;#6507: 26 8B 0E DA 4D
        jcxz    WRITE_LAST_PART                                ;#650C: E3 0F
