        pop     cx                                             ;#6515: 59
        jb      short WRITE_BUF_RETURN                         ;#6516: 72 40
        call    near ADVANCE_DS_64K                            ;#6518: E8 84 FB
        loop    WRITE_FULL_64K                                 ;#651B: E2 F1
